INSERT INTO "Articles" (slug, title, author_id, cover_path, cover_blur, cover_width, cover_height, excerpt, content_blocks, published_at)
VALUES (
  'mrd2-kuma-kuma',
  'Кума-Кума',
  (SELECT id FROM "Authors" WHERE name = 'Иван Гобзев' ORDER BY id LIMIT 1),
  'mrd2/mrd2-kuma-kuma.jpg',
  'data:image/jpeg;base64,',
  1200,
  663,
  '— Послушай, да хватит уже вести себя как маленькая девочка! Ты — не маленькая девочка!',
  '[{"kind":"image","path":"mrd2/mrd2-kuma-kuma.jpg","caption":null},{"kind":"paragraph","text":"— Послушай, да хватит уже вести себя как маленькая девочка! Ты — не маленькая девочка!"},{"kind":"paragraph","text":"— Почему это?"},{"kind":"paragraph","text":"— Да потому что тебе сто пятьдесят два года!"},{"kind":"paragraph","text":"— Ну и что? Ты хочешь сказать, я выгляжу на свой возраст?! А ­сам-то — старик, выглядишь на сорок пять!!!"},{"kind":"paragraph","text":"Она обиделась. Схватила сумочку, выскочила и хлопнула дверью."},{"kind":"paragraph","text":"Ивану Андреевичу и правда было немало — сто восемьдесят пять, только сегодня исполнилось, и он годился ей в отцы. Да и выглядела она на двадцать."},{"kind":"paragraph","text":"Но сегодня был его день рождения, а она, придя, спросила:"},{"kind":"paragraph","text":"— Что ты мне подаришь?"},{"kind":"paragraph","text":"— Ужин в ресторане? — предложил он."},{"kind":"paragraph","text":"— Опять?!"},{"kind":"paragraph","text":"— Но… Послушай, милая, сегодня же мой день рождения…"},{"kind":"paragraph","text":"— Что?! Вот как? То есть, ты сейчас попрекаешь меня своим днём рождения? Эгоист!"},{"kind":"paragraph","text":"И вот тогда она упала в кресло и принялась изображать рыдания. А он ей про маленькую девочку… Зря он это, конечно, — в нашем мире к людям надо быть снисходительнее, особенно к тем, кто перевалил за сотню. Потому что, хоть мы и научились жить вечно, ­мозг-то всё равно стареет быстрее, чем восстанавливается…"},{"kind":"paragraph","text":"Она ушла."},{"kind":"paragraph","text":"И к счастью!"},{"kind":"paragraph","text":"Потому что Иван Андреевич решил: с него хватит."},{"kind":"paragraph","text":"Хватит каждодневного лубезяро торопо и хуземяки лапору!"},{"kind":"paragraph","text":"Сегодня, когда объявили обеденный перерыв, он, поднимаясь из-за стола, вдруг замер. Замер на месте в такой вот полувставшей позе и схватился за голову. Нет, у него ничего не заболело, он просто неожиданно осознал всю трагичность сложившегося положения."},{"kind":"paragraph","text":"Вот уже сто пятьдесят лет пять дней в неделю он ходит в этот офис и делает лубезяро торопо. Ровно в девять приходит, ровно в пять уходит, перерыв на обед с двух до трёх, часто — дедлайны, когда надо работать сверхурочно и даже в выходные. А по выходным давно опостылевшие развлечения…"},{"kind":"paragraph","text":"И всё одно: лубезяро торопо, лубезяро торопо, лубезяро торопо. Однажды, впрочем, начальство пошло ему навстречу"},{"kind":"paragraph","text":"и предложило заняться хуземякой лапору. В итоге, он стал заниматься и тем, и тем и перестал видеть разницу. Да, он на хорошей должности, у него отличная зарплата, его любят и уважают, у него самая красивая девушка в Солнечной системе. Но камон! В сто восемьдесят пять у него нет семьи и даже постоянного дома! Он как вечный подросток… Всё ждёт ­чего-то и ждёт. А ничего и не происходит!"},{"kind":"paragraph","text":"И что дальше? Тысячелетия? Вечность?"},{"kind":"paragraph","text":"Он похолодел от ужаса. В чём смысл? Зачем? Разве для этого рождён человек? Это же какой самообман — иллюзия жизни! Жить, чтобы зарабатывать деньги для того, чтобы дальше жить, чтобы зарабатывать деньги для того, чтобы дальше жить, чтобы…"},{"kind":"paragraph","text":"— Иван Андреевич! С вами всё хорошо? — его размышления прервала начальница отдела по корпоративным связям."},{"kind":"paragraph","text":"— Да-да, Марина, всё хорошо…"},{"kind":"paragraph","text":"Ей было всего шестьдесят три, но выглядела она по моде — на двадцать. Хотя сейчас среди прогрессивной части общества популярна другая тенденция — выглядеть на свой возраст. Потому что это естественно. Иван Андреевич был отчасти согласен с этим: сам он выглядел на сорок с ­чем-то — быть юношей в своём возрасте казалось ему странным. Его начальник, Семён Иолактович, считал иначе и ходил в теле шестнадцатилетнего, хотя по слухам ему перевалило за четыреста."},{"kind":"paragraph","text":"Марина придерживалась средневековых взглядов, то есть изо всех сил хотела нравиться своей внешней, физиологической стороной."},{"kind":"paragraph","text":"— Иван Андреевич, от лица коллектива я хочу поздравить вас с юбилеем! Ура! Ура! Ура! Вам подарок! Вот!"},{"kind":"paragraph","text":"Она протянула ему пакет."},{"kind":"paragraph","text":"В пакете был термос для чая с логотипом фирмы и подарочная карта магазина одежды номиналом в три тысячи."},{"kind":"paragraph","text":"Ивану Андреевичу стало грустно. Он сел на край стола и почесал бороду. Нет, он не рассчитывал получить в подарок новый самолёт или виллу у моря. Но этот трёхкопеечный термос? И карта, на которую он сможет купить себе разве что один ботинок в том магазине?.."},{"kind":"paragraph","text":"Он задумчиво посмотрел в большое окно: там бесшумно взлетали корабли, распугивая чаек, и, перечеркнув небо белой росписью, исчезали в вышине за ­что-то скрывающими облаками. Они отправлялись в другие миры."},{"kind":"paragraph","text":"— Спасибо, Марина. А Семён Иолактович на месте? — спросил он, улыбнувшись ей."},{"kind":"paragraph","text":"— Да, — улыбнулась она в ответ. — Вам нравится?"},{"kind":"paragraph","text":"— Очень."},{"kind":"paragraph","text":"Он поднялся, прошёл к кабинету Семёна Иолактовича и открыл дверь."},{"kind":"paragraph","text":"— Заходи, Иван! С днём рождения, кстати!"},{"kind":"paragraph","text":"Семён Иолактович сидел в кресле: юный и немыслимо красивый. Впрочем, эта внешность мало кого могла обмануть — жесты, мимика, глаза Семёна Иолактовича выдавали в нём человека, привыкшего повелевать. Ещё бы: вот уже две сотни лет он руководил одной из крупнейших корпораций в мире в сфере шулепяки туру и протолебехозо. Говорят, что начинал он с са-"},{"kind":"paragraph","text":"мого дна, что был бедным индийским мальчиком, собиравшим мусор в Ганге. Потом он был послушником, затем монахом на Шри-­Ланке и дошёл якобы до того, что медитируя вспомнил все свои предыдущие жизни. В конце концов он перебрался сюда и открыл своё дело."},{"kind":"paragraph","text":"— Семён, я решил уволиться, — с порога сказал Иван Андреевич."},{"kind":"paragraph","text":"Начальник удивлённо посмотрел на него."},{"kind":"paragraph","text":"— Вот ты меня сейчас поймал врасплох. Это чего вдруг? Конкуренты переманили? Проблема в деньгах? Ты же знаешь, это обсуждаемо, если в разумных пределах."},{"kind":"paragraph","text":"— Нет, ничего из этого."},{"kind":"paragraph","text":"— А в чём же дело?"},{"kind":"paragraph","text":"— Я просто больше не хочу делать лубезяро торопо. Это… Извини, это идиотизм ­какой-то! Я всю жизнь занимаюсь этим и даже не понимаю, что это такое!"},{"kind":"paragraph","text":"— Не горячись, Иван. Не хочешь — не делай! Тебя никто не заставляет. Займись фулоло хололотротолепе, например. Там непочатый край…"},{"kind":"paragraph","text":"— Да это то же самое! Я больше не хочу!"},{"kind":"paragraph","text":"— Ты говоришь, как маленький."},{"kind":"paragraph","text":"— По сравнению с тобой я и есть маленький. Тебе сколько?"},{"kind":"paragraph","text":"Семён Иолактович повертел пальцами в воздухе:"},{"kind":"paragraph","text":"— Я не люблю говорить о своём возрасте. Но планирую прожить ещё не меньше. Чего не скажешь о тебе. Ты ведь понимаешь, что, уйдя, ты не сможешь оплачивать медстраховку?"},{"kind":"paragraph","text":"Да, Иван Андреевич это понимал. Поддерживать себя молодым и здоровым после ста стоит приличных денег."},{"kind":"paragraph","text":"— И всё же я решил, — твёрдо сказал он."},{"kind":"paragraph","text":"Семён Иолактович покачал головой."},{"kind":"paragraph","text":"— Дело твоё! Незаменимых, как ты знаешь, не бывает. Хотя, я думаю, это эгоистично с твоей стороны!"},{"kind":"paragraph","text":"Иван Андреевич понял его намёк — самая красивая девушка в Солнечной системе требовала вложений. Потому что в сто пятьдесят два оставаться такой довольно сложно. Но он не сомневался, что она найдёт себе другого."},{"kind":"paragraph","text":"И Иван Андреевич улетел на Кума-­Кума, планету земного типа в созвездии Стрельца."},{"kind":"paragraph","text":"Летел с пересадкой на Плутоне, потому что Плутон — транзитная зона, где проверяют документы и груз. Даже если груза особо и нет, как в случае Ивана Андреевича, всё равно проверяют долго."},{"kind":"paragraph","text":"О Кума-­Кума ходят легенды. Райский островок во вселенной, единственная кроме Земли полностью пригодная для жизни планета в нашей галактике. Кума-­Кума покрыта лесами, реками и морями, там исключительная экология и никакой вредной промышленности. Люди там живут в специальных автономных зонах и только тем и занимаются, что исследуют новые уголки планеты."},{"kind":"paragraph","text":"Разумных обитателей на Кума-­Кума нет, но живые существа есть. Они настроены к человеку исключительно дружелюбно, не боятся его, да и люди никого не обижают. В тамошних лесах растут поющие деревья, и те, кто слушает их, впадают в безвременное блаженство."},{"kind":"paragraph","text":"Словом — настоящий рай."},{"kind":"paragraph","text":"И Иван Андреевич понял, что хочет провести остаток жизни в лесах, лугах и горах Кума-­Кума. Ему хватит на это средств, хотя и придётся отказаться от части медстраховки с услугами по омоложению. И отлично, его это не пугало. Людям не нужна вечность — за вечность даже рай станет постылым. Всё, что угодно, превратится в подобие лубезяро торопо, если дать тебе на это целую вечность. Ценностью обладает только временное, преходящее, то, что можно и страшно потерять."},{"kind":"paragraph","text":"Поэтому каждый день на Кума-­Кума в его сто восемьдесят пять, когда он станет дряхлеть буквально по часам, стремясь к своему естественному состоянию, будет для него полным смысла и жизни. Каждый день, ускользая, станет последним. И каждое новое утро станет бесценным подарком."},{"kind":"paragraph","text":"Он проведёт последние годы (или месяцы) в гармонии с природой, то есть так, как и должен жить человек. Да и кто знает, не даст ли ему созерцание поющих лесов новое, духовное бессмертие?"},{"kind":"paragraph","text":"Сидя на Плутоне в очереди на проверку, Иван Андреевич перечитал все информационные материалы о Кума-­Кума и понял, что потерял слишком много времени. Он должен быть отправиться туда ещё лет сто назад. Но лучше поздно, чем никогда."},{"kind":"paragraph","text":"Плутон не только транзитная зона, но и место обитания всяких отбросов общества. Тут и тюрьмы, и поселение для тех, кто из них освободился. Местные жители работают в шахтах по добыче камня и льда, которые никому не нужны. Некоторые вылетают на другие объекты пояса Койпера за более ценными ресурсами и билетом прочь отсюда, но, понятное дело, не многие возвращаются."},{"kind":"paragraph","text":"Плутон — серый и невзрачный мир, единственное место в Солнечной системе, где почти всё население до сих пор занимается физическим трудом. Притом цены здесь выше, чем на Земле, и приходится платить за довольно необычные вещи. Так, воздух с высоким содержанием кислорода здесь платный, а нет денег — дыши азотом. То же и с водой: хотя она добывается здесь же, производство стоит дорого, поэтому очищенная вода не для всех. Нет денег — соси метановый лёд."},{"kind":"paragraph","text":"Глядя в окно офиса транзитной зоны, Иван Андреевич обозревал этот мир и поражался тому, как в нём выживают люди. И ведь есть тут даже поэты, которые воспевали холодные ночи и тёмные дни Плутона."},{"kind":"paragraph","text":"— Долго ещё ждать? — спросил он начальника транзитной зоны."},{"kind":"paragraph","text":"— Может час, а может неделю, — недружелюбно ответил тот. — Как документы и груз проверят. Тут есть отель неподалёку. Идите, отдыхайте, посмотрите достопримечательности. Вам сообщат, как будет готово."},{"kind":"paragraph","text":"Иван Андреевич понимал его неприязнь. Местные не любят землян. Они считают, что земляне настоящей жизни не нюхали."},{"kind":"paragraph","text":"Иван Андреевич вышел и сразу прикрыл нос и рот ладонью — воздух был ужасный. Как этим можно дышать? Он хотел вернуться — купить баллон с маской, но до отеля в самом деле было недалеко, перейти площадь и всё. Да и не обязан ли он теперь потерпеть, как терпят миллионы людей, живущих здесь, — сейчас, когда он начал новую жизнь?"},{"kind":"paragraph","text":"И он пошёл, задыхаясь и хватаясь за горло, вытирая слезящиеся глаза и часто останавливаясь. Он знал, что нужно привыкнуть, если ты тут не родился."},{"kind":"paragraph","text":"— Не подскажете, который час?"},{"kind":"paragraph","text":"К нему подошли двое. Иван Андреевич заподозрил неладное, но всё же вскинул руку, чтобы посмотреть. Его толкнули в спину, он упал на землю и пока пытался подняться, чужие руки шарили по его карманам. Сопротивляться, тем более убегать не было сил — все уходили на то, чтобы просто дышать."},{"kind":"paragraph","text":"Когда он поднялся, грабители исчезли. У него забрали всё: деньги, часы, телефон и даже куртку с ботинками. В отель идти смысла не было. К тому же, он только сейчас заметил, что огни в отеле не горят, стёкла разбиты, а на заржавевших рольставнях в дверном проёме написаны оскорбительные слова в адрес жителей Земли."},{"kind":"paragraph","text":"Иван Андреевич пошёл обратно, в транзитную зону."},{"kind":"paragraph","text":"— Меня ограбили. Что мне делать? — сказал он начальнику транзитной зоны."},{"kind":"paragraph","text":"Тот не скрывал радости."},{"kind":"paragraph","text":"— Обратитесь в полицию, — улыбнулся он. — Можете вызвать сюда? — Не могу. — Хорошо. Я могу взять у вас воздух и воду, а потом оплатить? — Нет. — А мои документы? — Они отправились на проверку."},{"kind":"paragraph","text":"Иван Андреевич как был — босиком и в майке — снова вышел на улицу. Плутон смотрел на него сумеречно и враждебно."},{"kind":"paragraph","text":"До отделения Иван Андреевич добрался почти уже на четвереньках, не в силах идти из-за сильной одышки и кашля. Он написал заявление и спросил, что ему делать дальше. В ответ посоветовали устроиться на работу, чтобы прожить, пока не будут готовы документы, и выставили на улицу."},{"kind":"paragraph","text":"Иван Андреевич, опираясь на стены попадающихся на пути домов, пошёл по указанному адресу. Там находился Центр занятости имени Джерарда Петера Койпера. Ещё издали он заметил длинную очередь — местные стояли в ожидании работы."},{"kind":"paragraph","text":"Он занял место и сел прямо на каменные плиты, как и многие здесь. Виды вокруг были унылые и малообещающие, да и сам Центр занятости выглядел так, будто его бомбили."},{"kind":"paragraph","text":"Единственное, что утешало: он понемногу привыкал к местному воздуху. Правда, на коже началось ­какое-то раздражение, но он старался не обращать внимания."},{"kind":"paragraph","text":"На следующий день в обед подошла его очередь."},{"kind":"paragraph","text":"— В какой области вы специалист? — спросила его женщина за стеклом. — Не приближайтесь! — повысила она голос, когда Иван Андреевич из-за слабости попытался облокотиться на выступ под окошком."},{"kind":"paragraph","text":"Он отстранился и ответил:"},{"kind":"paragraph","text":"— По части лубезяро торопо."},{"kind":"paragraph","text":"— Что?! — спросила она."},{"kind":"paragraph","text":"— Лубезяро торопо. Сто пятьдесят лет этим занимаюсь уже."},{"kind":"paragraph","text":"— Это что такое? Впервые слышу! Мань?! — позвала она ­кого-то. — Ты знаешь, что такое лубезяка торо… Как?!"},{"kind":"paragraph","text":"— Лубезяро торопо, — повторил он."},{"kind":"paragraph","text":"— Мань, лубезяро торопо!"},{"kind":"paragraph","text":"Ей ­что-то ответили, и она рассмеялась. Смеялась ещё довольно долго, а потом сказала:"},{"kind":"paragraph","text":"— У нас такого нет. Что вы ещё умеете?"},{"kind":"paragraph","text":"— Ну… Шулепякой фуру владею. Протолебехолосо. Разбираюсь неплохо в хуземяке лапору."},{"kind":"paragraph","text":"Женщина пристально на него посмотрела."},{"kind":"paragraph","text":"— Ты пьяный что ли? Или ещё под чем?"},{"kind":"paragraph","text":"Через ­какое-то время… Какое время? Сложно сказать: он потерял ему счёт. Может, прошли недели, а может, и месяцы — до того всё было однообразно. В общем, через ­какое-то время он обнаружил себя лежащим в канаве со стоками из промышленного района."},{"kind":"paragraph","text":"До этого он сидел, прислонившись к стене дома в переулке за углом столовой — у самой столовой он сидеть не мог: там уже было занято. Он сидел в надежде, что ему подадут на пропитание, и хотя шансов, что на Плутоне подадут, было ноль — ему всё же подавали, как и другим таким же. Подавали редко, как правило, объедки, но этого хватало, чтобы выжить."},{"kind":"paragraph","text":"Иногда в минуты просветления Иван Андреевич думал о том, что в принципе его жизнь теперь мало чем отличается от жизни отшельников на Кума-­Кума. А на Земле шраманы и брахманы вели такую жизнь тысячелетиями."},{"kind":"paragraph","text":"И всё же было в этом ­что-то не то. Не то заключалось в том, что они творили своё подвижничество не на Плутоне. Как бы они справились здесь, в этой холодной ядовитой атмосфере, в каменных джунглях и вечных сумерках?"},{"kind":"paragraph","text":"И вот он очнулся в канаве. Вероятно, он сел слишком близко к столовой, и его убрали конкуренты. Или сочли, что он умер, и поэтому выбросили."},{"kind":"paragraph","text":"Выбравшись из канавы, он впервые за долгое время увидел в её мутной воде своё отражение. Одряхлел он порядком. Ещё бы: без инъекций человек быстро возвращается в своё актуальное состояние. И чем дальше, тем быстрее. Если сейчас он выглядел уже на девяносто, то через месяц будет на все сто пятьдесят."},{"kind":"paragraph","text":"В общем, он вылез из канавы, попил из неё же воды и побрёл обратно, в свой переулок за угол столовой."},{"kind":"paragraph","text":"Поначалу он пытался найти работу, но шансы были только на самую тяжёлую, где требовалась физическая сила и молодость. О шахте не могло быть и речи, а всё попроще оказалось нарасхват. К тому же, он стал терять зрение и слух — то ли по чисто возрастным причинам, то ли из-за токсичной среды."},{"kind":"paragraph","text":"Пару раз он наведывался в транзитный центр. В первый ему сказали, что его документы ­где-то потерялись и их ищут,"},{"kind":"paragraph","text":"а во второй — что впервые видят, и если он ещё раз к ним заявится, вызовут охрану."},{"kind":"paragraph","text":"Друзей Иван Андреевич не завёл. В основном, по причине того, что не владел плутонским диалектом."},{"kind":"paragraph","text":"Иногда бродягам с площади удавалось раздобыть жидкость для промывки двигателей кораблей — в ней содержался спирт. Похоже, это и было основной целью их существования — раздобыть сию жидкость. Если Иван Андреевич пытался заняться медитацией (безуспешно), то те жили от одной возможности выпить до другой."},{"kind":"paragraph","text":"В дни, когда жидкость удавалось купить, настроение у бродяг сильно поднималось уже на стадии предвкушения: они собирались в кружок, разливали в железные кружки напиток, шутили и хрипло смеялись. После выпивали, меняли цвет с синего на зелёный и обратно, закуривали самокрутки с навозом Центромидона — местной модификации земной крысы, — и лица их расплывались в блаженстве."},{"kind":"paragraph","text":"Им становилось хорошо. Затем они оживлялись, спорили о ­чём-то, ругались, а потом плакали, глядя на звёзды."},{"kind":"paragraph","text":"Кончалось всё тем, что они падали на дорогу и засыпали. Просыпались утром не все."},{"kind":"paragraph","text":"Со временем Иван Андреевич стал понимать местную речь."},{"kind":"paragraph","text":"— Старый, будешь водяру?"},{"kind":"paragraph","text":"Так они называли свой алкогольный напиток."},{"kind":"paragraph","text":"— Нет, спасибо, — отвечал он. Однажды он попробовал и чуть не умер."},{"kind":"paragraph","text":"— Смотрите, — смеялись они, — он сказал «спасибо»!"},{"kind":"paragraph","text":"Или:"},{"kind":"paragraph","text":"— Вау, старый опять пошёл к урне!"},{"kind":"paragraph","text":"Дело в том, что Иван Андреевич всегда выбрасывал ненужные вещи не рядом с собой, как все, а в мусорный контейнер. И ещё он время от времени стирал в канаве свою одежду. Не сказать, чтобы она становилась чище, но хотя бы немного свежее."},{"kind":"paragraph","text":"Поначалу бродяги издевались над ним и кидались всякими отходами, пока главный среди них, одноногий бывший спецназовец с женским именем Церера, не стал делать то же самое — убирать за собой. А потом и другие подтянулись. И в ­какой-то момент, непонятно, когда именно, Иван Андреевич вдруг стал у этого сброда пользоваться уважением."},{"kind":"paragraph","text":"Однажды Иван Андреевич лежал на земле в закоулке за столовой и смотрел на свою длинную жёлтую бороду, распластанную по каменной плите. Сидеть он почти уже не мог, поэтому лежал. Он смотрел и думал, что вот, кстати, в чём одна из особенностей Плутона — здесь нет насекомых. И вообще никакой жизни, кроме людей и центромидонов. Что неудивительно: Плутон непригоден для жизни."},{"kind":"paragraph","text":"— Хей, старик, — услышал он бодрый голос. — Ты живой?"},{"kind":"paragraph","text":"Иван Андреевич пошевелил пальцами."},{"kind":"paragraph","text":"— Сброд на площади говорит, что ты ­когда-то занимался лубезяро торопо?"},{"kind":"paragraph","text":"— Было дело, — прохрипел Иван Андреевич."},{"kind":"paragraph","text":"— Вот это удача! Нам срочно нужен такой человек! Ты не поверишь: на всём Плутоне не нашли никого, кто знал бы, что это такое… А с Земли выписывать — это…"},{"kind":"paragraph","text":"Человек выругался по-местному."},{"kind":"paragraph","text":"— Взяли, понесли, — сказал второй голос."},{"kind":"paragraph","text":"Они схватили Ивана Андреевича — один за ноги, другой подмышками — и ­куда-то быстро потащили."},{"kind":"paragraph","text":"— Эй, смотрите! — закричали бродяги у столовой. — Старика тащат! Откинулся, видать."},{"kind":"paragraph","text":"— Вечная память! Снимите шапки!"},{"kind":"paragraph","text":"— Прощай, дед!"},{"kind":"paragraph","text":"Иван Андреевич хотел возразить, но не смог."},{"kind":"paragraph","text":"Его принесли в помещение с хорошо одетыми людьми и яркими экранами."},{"kind":"paragraph","text":"— Есть-пить хочешь?"},{"kind":"paragraph","text":"Он кивнул."},{"kind":"paragraph","text":"— Ну смотри, старый, если дуришь нас, пожалеешь! Давай-ка, скажи, что тут написано?"},{"kind":"paragraph","text":"Его ткнули носом в монитор. Он стал читать:"},{"kind":"paragraph","text":"— Фулоло хололотротолепе, фолопяказо…"},{"kind":"paragraph","text":"Эти слова зазвучали для него давно забытой музыкой, срывая пелену с памяти, и перед его взором вдруг вспыхнули картины прежней, совершенно другой жизни — на Земле. На глаза навернулись слёзы, и он остановился."},{"kind":"paragraph","text":"— Ты понимаешь, что это значит? — спросили его."},{"kind":"paragraph","text":"Он кивнул. Хотя это было неправдой, он не понимал. Но он знал, что с этим делать."},{"kind":"paragraph","text":"— Продолжай! — Шулепяка фуру… Лубязяро торопо."},{"kind":"paragraph","text":"За несколько дней, благодаря омолаживающим инъекциям, хорошему питанию и сну в нормальных условиях Иван Андреевич вполне поправился."},{"kind":"paragraph","text":"По удивительному стечению обстоятельств вышло так, что база на Плутоне заключила договор с компанией, в которой ­когда-то работал Иван Андреевич. И по ещё более удивительному стечению обстоятельств запрос касался именно его специализации. Пожалуй, во всей Солнечной системе не было ни одного человека, который мог бы справиться с задачей лучше, чем он!"},{"kind":"paragraph","text":"Три недели с утра до позднего вечера он не выходил из офиса, сидя перед экраном. За это время вдруг нашлись его документы, и он заработал приличные деньги, которых вполне хватало на то, чтобы продолжить путешествие. Больше его здесь ничего не держало."},{"kind":"paragraph","text":"— Ну что? — спросил начальник транзитной зоны. — Дальше, на Кума-­Кума?"},{"kind":"paragraph","text":"— Нет. Я возвращаюсь на Землю."},{"kind":"paragraph","text":"Перед вылетом он посетил площадь перед Центром занятости. Там всё было по-прежнему: те же люди сидели и лежали на своих местах. К­то-то исчез, ­кто-то появился новый, но в целом тот же контингент."},{"kind":"paragraph","text":"Он принёс им деньги, довольно много денег. Конечно, он знал, на что они их потратят — на жидкость для промывки двигателей кораблей. Но предложи он им сделать с этими деньгами ­что-нибудь другое, они бы его не поняли. А возможно, и побили бы."},{"kind":"paragraph","text":"— Держи, — протянул он свёрток Церере. — Это на всех. А я улетаю."},{"kind":"paragraph","text":"— Старый, это ты что ли? — прохрипел тот со смехом. — Тебя не узнать!"},{"kind":"paragraph","text":"Они постояли молча, глядя на звёздное небо."},{"kind":"paragraph","text":"— Ну что, рады за тебя! Бывай, — Церера крепко хлопнул его по плечу."},{"kind":"paragraph","text":"Тут и другие подошли прощаться. Говорили, чтобы помнил Плутон. Иван Андреевич обещал, что не забудет."},{"kind":"paragraph","text":"Когда он со всеми попрощался и пошёл по площади к космопорту, его догнал Церера."},{"kind":"paragraph","text":"— Такое дело… Это мы тебя тогда грабанули. Ты не обижайся, ладно?"},{"kind":"paragraph","text":"— Что было, то было."},{"kind":"paragraph","text":"— Вот, собрали в дорогу, — Церера протянул ему коробку с сушёными фекалиями Центромидона и обёрточной бумагой. — Покуришь."},{"kind":"paragraph","text":"Это было кстати — за время, проведённое на Плутоне, Иван Андреевич пристрастился к курению."},{"kind":"paragraph","text":"— Привет, Иван! — Семён Иолактович встал и пожал ему руку. — Рад, что ты вернулся. Твоя ставка как раз свободна."},{"kind":"paragraph","text":"Он помолодел ещё на пару лет."},{"kind":"paragraph","text":"— Неужели никого не нашёл за такое время? — удивился Иван Андреевич."},{"kind":"paragraph","text":"— Нашёл. Но сотрудник не стойкий оказался — быстро наступило профессиональное выгорание. Кстати, как тебе на Плутоне? Что на Кума-­Кума не долетел?"},{"kind":"paragraph","text":"Иван Андреевич посмотрел в глаза начальнику, но подвоха не заметил."},{"kind":"paragraph","text":"— На Плутоне нормально, — ответил он. — Завёл определённые связи."},{"kind":"paragraph","text":"— Понятно… Слушай, а чем это от тебя пахнет? — Семён Иолактович покрутил пальцами в воздухе."},{"kind":"paragraph","text":"— Да это… Это так. Привычку приобрёл дурную."},{"kind":"paragraph","text":"— Мда… Я тоже был на Плутоне… Долго. Лет тридцать."},{"kind":"paragraph","text":"— Да?! Что ты там делал?"},{"kind":"paragraph","text":"— Занимался самосозерцанием. Впрочем, давно это было. Даже не уверен, что в этой жизни, а не в ­какой-­нибудь другой… Ладно. Когда приступить сможешь?"},{"kind":"paragraph","text":"— Хоть сейчас."},{"kind":"paragraph","text":"— Ну, сейчас не надо… Давай, отдохни месяцок. Думаю, тебе нужно!"},{"kind":"paragraph","text":"— Окей. Я тогда пошёл?"},{"kind":"paragraph","text":"— Иди."},{"kind":"paragraph","text":"Иван Андреевич направился к двери."},{"kind":"paragraph","text":"— А, вот ещё, кстати, — вдогонку сказал Семён Иолактович. — Хочу тебя повысить. Будешь моим замом?"},{"kind":"paragraph","text":"— Ты называл меня старухой! — Нет, не было этого. — Было! — Нет! — Да! — Ну извини. — Ага! Ты значит сознаёшься, что считаешь меня старухой?"},{"kind":"paragraph","text":"Она упала перед ним на ковёр и стала рыдать. Он молчал."},{"kind":"paragraph","text":"— Ты что так глубоко вздыхаешь? — всхлипывая, спросила она."},{"kind":"paragraph","text":"— Всё в порядке."},{"kind":"paragraph","text":"— Нет, ­как-то подозрительно ты сейчас вздохнул! Думаешь, я долбанутая? Знаешь, через что я прошла, пока тебя не было?"},{"kind":"paragraph","text":"— Не знаю… Слушай, а выходи за меня замуж?"},{"kind":"paragraph","text":"— А жить на что?"},{"kind":"paragraph","text":"— Меня взяли обратно на работу."},{"kind":"paragraph","text":"— Лубезяро торопо?"},{"kind":"paragraph","text":"— А куда ещё?"},{"kind":"paragraph","text":"— Ясно. — Она поднялась и вытерла глаза тыльной стороной ладони. — Будешь кофе?"}]'::jsonb,
  '2021-12-30T12:00:00.000Z'
)
