INSERT INTO "Articles" (slug, title, author_id, cover_path, cover_blur, cover_width, cover_height, excerpt, content_blocks, published_at)
VALUES (
  'mrd2-larisa',
  'Лариса',
  (SELECT id FROM "Authors" WHERE name = 'Анна Пашкова' ORDER BY id LIMIT 1),
  'mrd2/mrd2-larisa.jpg',
  'data:image/jpeg;base64,',
  1175,
  775,
  'Лариса спала плохо и беспокойно — да и назовёшь ли это сном? На маленькой тахте, накрытой то ли простынёй, то ли тонкой тряпицей, женщина полусидела-­полулежала на подушках в предчувствии, что скоро придётся открыть глаз',
  '[{"kind":"image","path":"mrd2/mrd2-larisa.jpg","caption":null},{"kind":"paragraph","text":"Лариса спала плохо и беспокойно — да и назовёшь ли это сном? На маленькой тахте, накрытой то ли простынёй, то ли тонкой тряпицей, женщина полусидела-­полулежала на подушках в предчувствии, что скоро придётся открыть глаза. Первым просыпался маленький Антошка."},{"kind":"paragraph","text":"«Баба», — звал он сначала тихо, потом требовательно. Лариса поднималась, пытаясь нащупать тапки в темноте, находила одну и хромала до деревянной кроватки, вынимала внука, прижимала его, полусонного, тёплого и тяжёлого, к груди. Она любила эти минуты. Весь дом ещё спал. В соседней комнате нервно ворочался муж. Он работал допоздна, утром уходил в университет читать лекции. Муж злился, когда его отвлекали. Заглядывая в его комнату, Лариса отмечала, что он всё ещё красив. Высокий, седой, он нравился всем, даже своим студенткам. В нём были именно"},{"kind":"paragraph","text":"те благородство и красота дореволюционного учителя, о которых Лариса читала в книгах. Давно, когда сама была его студенткой. О красоте мужа она думала с гордостью. Лариса подходила с Антошкой к длинному зеркалу в коридоре. «Купить бы новый халат», — она разглядывала с ног до головы усталую женщину, которую иногда даже не узнавала. Лариса была младше мужа на восемнадцать лет. Выглядели они ровесниками."},{"kind":"paragraph","text":"Пасынок Митенька вставал позже всех. Молча завтракал, отвозил жену на работу. Ольга иногда помогала Ларисе, но чаще была недовольна её работой. Антошка не слушался, капризничал, бабушка его баловала и совсем не воспитывала. Лариса не знала, как это делать: её саму воспитывал муж с тех пор, как она появилась в этой квартире с высокими потолками, через год после смерти Митиной мамы — мальчику тогда было два года. Она чувствовала себя вторым ребёнком — и не всегда старшим. В детстве Митя её любил и даже звал играть на равных. С отцом он ничем не делился, и Лариса гордилась тем, что у них есть общие тайны."},{"kind":"paragraph","text":"Когда Мите было восемь лет, она подобрала крошечного таксика. «Малыш, — подумала Лариса, — я назову его так». Малышу ­кто-то связал жилетку и вывел в ней на мороз. Щенок увязался за Ларисой и бежал, высунув язык, до самого дома. «Что с тобой делать? — вздохнула она и подняла его на руки. Лариса знала, что Миша будет против, и ­всё-таки храбрилась. — Кто я тут? Гостья или полноправная хозяйка? Я живу в этом доме шесть лет. Митя обрадуется…»."},{"kind":"paragraph","text":"Митя обрадовался. Размечтался, как будет гулять с Малышом на поводке, возьмёт его летом на дачу. «Можно он будет спать со мной?» — попросил сын. Лариса, поколебавшись, ответила, что лучше бы устроить щенка на подстилке в коридоре. Она тоже воображала радостные картины летних прогулок с Митей"},{"kind":"paragraph","text":"и Малышом. «Завтра надо будет свозить его к ветеринару, купить ошейник», — решила Лариса."},{"kind":"paragraph","text":"Миша вернулся вечером, Малыш прибежал к порогу встречать. Он успел освоиться в новом доме и радостно носился за Митей, оглашая весь дом хриплым лаем."},{"kind":"paragraph","text":"— Что это? — спросил Миша."},{"kind":"paragraph","text":"Лариса вдруг почувствовала, что снова сидит у него на экзамене."},{"kind":"paragraph","text":"— Мы с Митей подобрали собачку, Малыш совсем замёрз, — улыбнулась она, ­зачем-то записав к себе в сообщники Митеньку."},{"kind":"paragraph","text":"— Чтобы завтра его тут не было. Никаких собак в моём доме."},{"kind":"paragraph","text":"Митя плакал всю ночь. Лариса лежала рядом, Малыш свернулся у них в ногах."},{"kind":"paragraph","text":"— Мы его отвезём в приют, к другим собачкам, ему там будет хорошо! Тут у него нет друзей… — она сама не верила своему радостному голосу. — А хочешь, завтра не пойдём в школу?"},{"kind":"paragraph","text":"На следующий день Митя не пошёл в школу. Малыш был в той же жилеточке, Лариса прижимала его к себе, укрывая от холода шарфом. Щенок уткнулся тёплым носом ей в шею, лизнул её и тихонько забил хвостом."},{"kind":"paragraph","text":"Они ехали на метро через весь город. За железными воротами стоял ряд вольеров, из каждого блестели несколько пар чёрных глаз. Железные миски ещё не остыли от овсяной каши, которую разносил собакам на завтрак мальчик чуть старше Мити. Когда дверь вольера закрылась, Малыш завыл. Они слышали его вой"},{"kind":"paragraph","text":"до самой автобусной остановки. В тот день Митя съел свой первый гамбургер и выпил первую газировку. Они не сказали об этом папе."},{"kind":"paragraph","text":"Так на общих секретах зародилась их дружба, они копились один за другим. Отец не знал про Митин первый поцелуй и первую сигарету, и что сын не собирался после школы учиться на врача. Даже Олю Митя привёл знакомиться с родителями, когда отца не было дома. Случайно или нарочно."},{"kind":"paragraph","text":"Чем больше Лариса сближалась с Митей, тем сильнее отдалялась от Миши, словно ничего у них не было. Ни прогулок по университетскому парку. Ни того дождя, когда рассеянный красивый профессор отдал ей свой пиджак, как будто не заметив, что она в плаще и дождевике, а у него только тонкая рубашка."},{"kind":"paragraph","text":"Лариса не знала, разочарован ли он, что у них так и не появилось общих детей или, наоборот, рад, что Мите досталась вся её любовь? Благодарен ли ей, что она не стала защищать кандидатскую, чтобы не получить хорошую должность в их университете? Догадывался ли, что работу она ­всё-таки дописала и убрала в стол, потому что видела, как Миша нахмурился, когда читал первые страницы? Это значило, что ему понравилось — а тех, кто ему нравился, он никогда не любил…"},{"kind":"paragraph","text":"Она завидовала невестке. Оля сразу всё переставила в их с Митей комнате — Ларисе не разрешалось даже переклеить обои или повесить картину. Оля затеяла ремонт и на общей территории: поменяла плитку в ванной, сделала перестановку на кухне. «Ребёнку тут негде будет бегать», — сказала Оля, и Миша согласно закивал, хотя Митя бегал на той же кухне."},{"kind":"paragraph","text":"Решение о том, что с Антошкой будет сидеть именно Лариса, приняли негласно. Оля заявила, что с осени выходит на работу. Митя и Миша промолчали."},{"kind":"paragraph","text":"И муж, и сын, и невестка были высокими, черноволосыми, с аристократичными тонкими чертами лица. Белокурый, с пухлыми румяными щёчками и ручками в перетяжках Антошка больше напоминал Ларису на детских фотографиях. Он словно был её, Ларисиным, ребёнком."},{"kind":"paragraph","text":"— Признавайся, ты бабушкин! Ба-буш-кин! — шутила она."},{"kind":"paragraph","text":"И Антоша заливался смехом, тянул к ней ручки, обвивал её шею и осыпал поцелуями. Ольга была права: бабушка его баловала, но иначе она не могла."},{"kind":"paragraph","text":"Единственным Ларисиным увлечением были походы к врачам. Миша называл это «турне». У Ларисы болело то справа, то слева. Или даже не болело, а покалывало. Порой она натыкалась на медицинскую статью в журнале и находила у себя все симптомы. Лариса и сама уже не могла понять, где у неё болит, поэтому привыкла ориентироваться на мнение Миши."},{"kind":"paragraph","text":"— Миша, если колет ­где-то в районе лопатки, стоит сходить к врачу? Или, может, просто неудобный стул?"},{"kind":"paragraph","text":"— Сходи к врачу, — советовал Миша, не отрываясь от газеты."},{"kind":"paragraph","text":"Тогда она шла в маленькую частную клинику у дома. Администратор её уже знала, Лариса боялась, как «ту сумасшедшую старуху». Встречали её всегда приветливо, но разговаривали, как с маленькой: «Сейчас мы нашу Ларису Николаевну про-"},{"kind":"paragraph","text":"водим к Алексею Евгеньевичу, и Алексей Евгеньевич скажет, что попить…»"},{"kind":"paragraph","text":"Лариса стыдилась признаться себе, что её подкупали настойчивая забота, ласковые голоса, добрые руки, которые брали её и сами вели, а не требовали, чтобы она вдруг выросла и шла, принимая самостоятельные решения и совершая ­какие-то поступки."},{"kind":"paragraph","text":"Да, ей нравилась эта доброта, она платила за неё, тем более что даром никто с ней приветлив не был. С мстительной решимостью Лариса искала очередной повод обратиться за помощью. У неё чесалась рука и ныло в плече, слезились глаза и стучало в висках. Ей хотелось крикнуть за ужином: «Вам всем всё равно, но есть те, кому не плевать! Я буду ходить к ним снова и снова. Смейтесь сколько влезет, я всё равно пойду»."},{"kind":"paragraph","text":"Вскоре ­кто-то начинал беспокоиться по-настоящему, и ей становилось стыдно. Особенно тяжело это воспринимал Антошка."},{"kind":"paragraph","text":"— Баба, ты болеешь?"},{"kind":"paragraph","text":"— Ну что ты, милый! Просто бабушка уже старенькая."},{"kind":"paragraph","text":"— Старенькая, да удаленькая! — цедила Ольга."},{"kind":"paragraph","text":"С Антошкой они ходили гулять в лес. Лариса уставала, потому что полдороги несла его на руках. Он часто останавливался, рассматривал камушки и листочки. Она вспоминала, что Митя тоже любил остановиться и поговорить с муравьями. Лариса даже хотела купить ему муравьиную ферму, но Миша не разрешил."},{"kind":"paragraph","text":"— Не плачь, муравьишка! — приговаривал маленький Митя. — Ты вырастешь, и у тебя будет колечко. Ты подаришь его невесте, у вас будет свадьба…"},{"kind":"paragraph","text":"Он помнил свадьбу папы с Ларисой. Праздновали скромно: Миша позвал только своих друзей, её друзей пригласить было неловко, ведь они тоже были его студентами. Мама Ларисы, хоть тогда и была ещё жива, не поехала. Слишком долго и далеко, к тому же Миша не слишком её уговаривал. Митю оставили дома с няней, он плакал и просился со всеми. Митя только проснулся и стоял босичком в коридоре, без штанишек, когда все уезжали. С горшком в руках."},{"kind":"paragraph","text":"— Возьмём его, Миша? — попросила Лариса."},{"kind":"paragraph","text":"Миша пожал плечами:"},{"kind":"paragraph","text":"— Ему и надеть нечего. Будет капризничать."},{"kind":"paragraph","text":"И Митя остался дома. После свадьбы Миша представил Ларису уже официально: «Теперь это — твоя мама», — но Митя звал её Лариса, как папа, хотя родную маму не помнил. По неопытности, стараясь понравиться Мите, Лариса однажды купила ему большое ведёрко мороженого. И Митя слёг! Он никогда не болел так сильно, даже Миша заволновался, накричал на Ларису."},{"kind":"paragraph","text":"Митя лежал с грелкой на лбу. Перед глазами у него всё плыло. Лариса стояла, вжав голову в плечи, и нервно ковыряла заусенцы на ногтях."},{"kind":"paragraph","text":"— Ты теперь должна заботиться о ребёнке, а не валяться с книжками. Если хотела учиться — надо было учиться, а не прыгать в постель!"},{"kind":"paragraph","text":"Митя не понимал, почему нельзя прыгать в постель, если там так тепло и мягко. Он хотел позвать Ларису, но болело горло,"},{"kind":"paragraph","text":"а имя было слишком сложным. И, когда папа ушёл, он прохрипел: «Мама… мама»."},{"kind":"paragraph","text":"Лариса вздрогнула. Она не сразу поняла, что обращаются к ней. Лариса подошла к мальчику и погладила его по голове, поцеловала лоб, чтобы проверить температуру."},{"kind":"paragraph","text":"— Я никогда раньше не ел мороженое, мама, — тихо сказал Митя."},{"kind":"paragraph","text":"Он часто защищал Ларису от отца. Миша всё больше отдалялся от них, уходил в комнату, хлопнув дверью, зарывался в свои дела, важные и большие. Совсем не такие, какие были у Мити с мамой."},{"kind":"paragraph","text":"Папа писал научную работу, а они гуляли по лесу и смотрели на муравьёв. Лариса однажды поймала ему большого жукабронзовку, и тот целую неделю жил в коробочке! Митя старался не болеть, чтобы не подводить маму, и сильно волновался, если ­всё-таки заболевал. Если папа приходил, а он лежал в постели, Митя первым делом старался убедить его: «Я сам! Я прыгал по лужам, и сапоги протекли»."},{"kind":"paragraph","text":"— А я давно говорил тебе купить ему новые сапоги, — замечал муж Ларисе."},{"kind":"paragraph","text":"Теперь она гуляла с Антошкой, Митиным сыном, но то и дело останавливалась, потому что у неё кололо в боку. Она шла с трудом и присаживалась отдохнуть каждые пять минут. Антошка ждал любимую «бабу»."},{"kind":"paragraph","text":"— Расскажи ещё про муравьёв! — умолял он."},{"kind":"paragraph","text":"И Лариса придумывала невероятные истории о муравьиных царствах, о колониях-­захватчиках и муравьиных принцессах. Она вспоминала, что ­когда-то хорошо писала и преподавательница по русской литературе просила её не бросать учёбу, но Лариса думала об этом без сожаления. Эти события казались ей такими же невероятными и далёкими, как муравьиные вой­ны, о которых ей приходилось рассказывать Антошке."},{"kind":"paragraph","text":"В тот вечер они вернулись позже обычного. Ольга уже разогревала ужин, который Лариса приготовила перед прогулкой. Они сели за стол, Митя рассеянно потрепал по голове сына, Антошка принялся болтать о том, как много интересного они с бабой видели в лесу."},{"kind":"paragraph","text":"— Ничего, скоро у тебя будет ещё больше интересного. Мы переедем в большой город. Ты хочешь жить в большом городе? Где есть зоопарк и огромные машины?"},{"kind":"paragraph","text":"— Да, да! — обрадовался Антошка."},{"kind":"paragraph","text":"— Митю приглашают работать в Петербург, — Ольга повернулась к Мише. — Пока вот думаем, нам с Антоном ехать сейчас или с осени — ему в следующем году в детский сад."},{"kind":"paragraph","text":"— Езжайте сейчас, — сказал Митя. — Что я там буду делать один? Да и мать летом отдохнёт немного, освободится."},{"kind":"paragraph","text":"— Антошка уезжает? — переспросила Лариса."},{"kind":"paragraph","text":"Глаза у неё наполнились слезами. Ещё сильнее закололо в боку."},{"kind":"paragraph","text":"— А баба поедет с нами? — заволновался Антошка."},{"kind":"paragraph","text":"— Нет, баба останется тут, но мы будем её навещать, и она приедет к нам в гости."},{"kind":"paragraph","text":"Переговоры шли долго, Лариса унесла Антошку спать. Она особенно крепко прижимала его к себе в тот вечер и баюкала"},{"kind":"paragraph","text":"даже после того, как услышала, что дверь в спальню Ольги и Мити хлопнула, а Миша щёлкнул в своей комнате выключателем. Она держала внука, пока перебиралась на тахту и, тревожно оглядываясь, что ­кто-то заметит, положила рядом с собой, чтобы встать рано утром и перенести обратно в кровать. Ныла левая рука, но Лариса боялась, что Антошка проснётся, и не вытаскивала её из-под него. Перед тем как крепко заснуть, Антошка, как и Митя, смешно дёргал ногой, словно пытался оттолкнуться и выпрыгнуть из сна, но не мог."},{"kind":"paragraph","text":"Лариса подумала, что утром надо записаться к Алексею Евгеньевичу, потому что ныл сустав. Она вспоминала, как бродила по лесу с маленьким Митей, но уже во сне он ­почему-то превратился во взрослого Антошку."},{"kind":"paragraph","text":"— Баба… Баба! — кричал он, как будто заблудился, хотя стоял совсем рядом."},{"kind":"paragraph","text":"— Ты что, опять спала с Антошкой? Его надо приучать к своей кровати! — нависал над ней во сне Миша."},{"kind":"paragraph","text":"— Она его и так разбаловала, — возмущалась Ольга."},{"kind":"paragraph","text":"Митя молчал. Лариса не понимала, как они оказались в лесу, и удивлялась, что не успела переложить Антошку, хотя вставала раньше всех взрослых в доме."},{"kind":"paragraph","text":"«Надо бы купить новый халат, — подумала она, проваливаясь обратно в сон, — а то поеду в гости к Антошке, а там и ходить не в чем. И поскорее поехать. Может, напроситься на первое время с ними, помогать?»"},{"kind":"paragraph","text":"Переложить Антошку Лариса действительно не успела. Из комнаты вышли все одновременно — Миша, допоздна"},{"kind":"paragraph","text":"работавший над книгой, Ольга и Митя. Рядом с тахтой стоял испуганный Антошка."},{"kind":"paragraph","text":"— Баба замёрзла, — сказал он и заплакал."}]'::jsonb,
  '2021-12-30T12:00:00.000Z'
)
