INSERT INTO "Articles" (slug, title, author_id, cover_path, cover_blur, cover_width, cover_height, excerpt, content_blocks, published_at)
VALUES (
  'mrd2-duremar',
  'Дуремар',
  (SELECT id FROM "Authors" WHERE name = 'Василий Вялый' ORDER BY id LIMIT 1),
  'mrd2/mrd2-duremar.jpg',
  'data:image/jpeg;base64,',
  1200,
  663,
  'Отцом Валерки был скучноватый, неторопливый человек с соответствующей облику профессией — учитель математики. Его статичная деятельность, в нашем детском понимании, едва ли походила на разумный и созидательный труд, прин',
  '[{"kind":"image","path":"mrd2/mrd2-duremar.jpg","caption":null},{"kind":"paragraph","text":"Отцом Валерки был скучноватый, неторопливый человек с соответствующей облику профессией — учитель математики. Его статичная деятельность, в нашем детском понимании, едва ли походила на разумный и созидательный труд, приносящий видимые результаты. С вялой подвижностью, неохотно погружаясь в очередной день, он отправлялся на работу. Слава богу, не в ту школу, где учился Валерка. По вечерам, когда он возвращался с тренировки или от друзей, отец со смиренным достоинством на лице проверял тетради. Озабоченно-­отвлечённым взглядом он сопровождал следующего в свою комнату отпрыска и снова погружался в унылую работу. Валерку раздражала профессия отца. Улица, где мальчишка проводил большую часть своего времени, — не то место, чтобы гордиться папой-­ учителем. Отцы его друзей ходили на футбол, частенько выпивали, после чего иногда дрались в пивной за углом, ездили на рыбалку, а то и просто, сидя за столиком в беседке, играли в домино или шахматы, обсуждали важные мужские темы. У его же отца не было подобных увлечений, и в разговорах он участия не при-"},{"kind":"paragraph","text":"нимал, ибо не знал того, что знать было необходимо: кто стал последним чемпионом мира по боксу в тяжёлом весе, какой размер бюста у Памелы Андерсон и где живёт Люська-­самогонщица."},{"kind":"paragraph","text":"Кроме того, у отца было странное хобби — он коллекционировал жуков. Папа называл себя энтомологом-­любителем и очень этим гордился. Поздней весной, когда заканчивались занятия в школе, он исследовал окрестные пролески, поля, животноводческие фермы, ставя нехитрые ловушки на «жесткокрылых», как по-научному называл жуков. Вечером, уставший и грязный, но невероятно довольный, он извлекал из спичечных коробков различных по размеру и окрасу насекомых: изумрудно-­ золотистых бронзовок, бархатно-­чёрных скарабеев, тёмно-­ коричневых носорогов. В самые жаркие летние месяцы отец на несколько дней уезжал к Чёрному морю, где лазал по скалам и кустарникам в поисках дубовых усачей и голубоватых, омерзительно пахнущих гигантских жужелиц. Осторожно и бережно, словно сокровище, он извлекал из картонного плена свою добычу и помещал её в банку. Затем бросал в неё смоченную эфиром ватку. Непритворно жалел «жесткокрылых», приговаривая: «Уж простите меня, бедненькие». Виновато смотрел на Валерку, и тому казалось, что в отцовских глазах стояли слёзы. Навеки «уснувших» жуков он нанизывал на булавки и помещал в специальные дощатые коробки, подписывал латинскими буквами, словно эпитафией, каждую свою жертву. Лишь в эти счастливые для него моменты папа становился разговорчивым, охотно поясняя те или иные повадки очередного экземпляра коллекции."},{"kind":"paragraph","text":"«Всё это было бы смешно, если бы не было так грустно». К­акимто образом соседи прознали о папином увлечении и за глаза назвали его Дуремаром. «Почему Дуремар? — обижался за отца Валерка и ворчал: — Тот ведь пиявок отлавливал»… Ему было"},{"kind":"paragraph","text":"неприятно и в то же время немного жаль папу. Под вечер отец возвращался с «охоты», ­чему-то улыбаясь, такой сказочно-­ нелепый, и ­что-то бормотал себе под нос. Увидев мужиков в беседке, папа на миг приостанавливался, улыбка тотчас сползала с его лица, делая его чуть глуповатым. Отец морщился, словно вспоминал нечто досадное, заметно горбился и норовил незаметно проскочить в подъезд. Валерка надеялся, что отец не слышал обидного прозвища, а если и слышал, то, может, не знал, что это слово относится к нему. С холодной, пустой приветливостью отец здоровался с соседями и, не проронив более ни слова, шёл по своим делам. В выходные дни, по утрам, учитель математики выходил во двор и делал зарядку, чем вбил последний гвоздь в гроб своей репутации нормального человека. Энергичные гимнастические упражнения не ­очень-то вязались с обликом низкорослого, чуть полноватого мужчины с явно обозначенными залысинами на голове."},{"kind":"paragraph","text":"— Смотри-ка, Майкин снова мышцы качает, — посмеивалась соседка, втайне завидуя маме, что папа не пьёт и не курит, не волочится за женщинами."},{"kind":"paragraph","text":"— Лучше бы он ­что-нибудь другое накачал, — ехидничала другая."},{"kind":"paragraph","text":"— Позавчера супружница его с работы пришла едва ли не в полночь, — она наклонялась к товарке, нашёптывая ей на ухо. — Видать, не до…бывает Майку учитель."},{"kind":"paragraph","text":"— Да ты что! — притворно удивлялась первая. — Никогда бы не подумала."},{"kind":"paragraph","text":"Валерка не особенно понимал суть разговора между соседками, но догадывался, что они обсуждали ­что-то неприличное, касающееся только его родителей. Он замечал, как играющие в домино мужики, словно по команде, поворачивали головы вслед проходящей маме и восхищённо прищёлкивали"},{"kind":"paragraph","text":"языками. Очевидно, им ­что-то в ней нравилось. Вглядываясь в неё, Валерка хотел понять, что именно, но не мог определить. Мама как мама…"},{"kind":"paragraph","text":"Дома мать постоянно ворчала на отца:"},{"kind":"paragraph","text":"— Есть ли в этом доме хозяин? — и сама себе отвечала: — Есть. Это, скорее всего, я."},{"kind":"paragraph","text":"Действительно, ей самой приходилось менять перегоревшие лампочки, чинить утюг и замок, красить окна. В общем, пресловутый «гвоздь в доме» всегда забивала она, а не папа. С безразличной бесхозяйственностью отец смотрел на оторванный кусок обоев в прихожей, равнодушно проходил мимо неработающей розетки в спальне, игнорировал неплотно прикрывающуюся дверцу холодильника на кухне. Безусловно, Валерка не мог знать, что столь же безынициативно отец проявлял себя на супружеском ложе и в ­какой-то степени являлся толстовцем. Семён Юрьевич считал, что для женщины семья и ребёнок есть единственный смысл наполнения жизни, а остальное — распутные вольности, без которых вполне можно обойтись. Лишённая многих оттенков простой бабьей радости Майя придерживалась другого мнения. Иногда ей хотелось почувствовать определённую дерзость мужа, ощутить его распущенность, испытать смелость и разнообразие ласк партнёра, от которых кружится голова. Но что можно было ожидать от мужчины, если он испытывал едва ли не патриархальный страх перед её наготой? И, наверное, краснел от смущения, верша стремительно-­скучный супружеский долг."},{"kind":"paragraph","text":"Тогда она решила стать женщиной-­инициатором. Майя прикупила подходящее для таких случаев нижнее бельё и ждала удобного момента для совращения собственного мужа. Небеса оказались благосклонны к Майе — вскоре супругов пригласили"},{"kind":"paragraph","text":"на свадьбу. Более удачного стечения обстоятельств не придумаешь. Шампанское, танцы, да и сама атмосфера мероприятия, где витал дух узаконенной физической близости, предполагала если не открытое обольщение, то уж точно решительный флирт. Майя выбрала первое. Она подливала вино практически не пьющему мужу, нежно и страстно прижималась к нему в медленном танце, кокетливо строила глазки. На остальных ухажёров, коих было немало, Майя внимания не обращала. Сидя за столом, она клала руку на ширинку мужниных брюк, шептала крайне непристойные фразы, самой благозвучной из которых являлась:"},{"kind":"paragraph","text":"— Сенечка, я хочу тебя. Поехали домой, — наклоняясь к нему, вожделенно лепетала Майя. — Прямо сейчас."},{"kind":"paragraph","text":"Семёна Юрьевича невероятно смущало поведение супруги. Безуспешно пытаясь отстраниться от жены, он стыдливо оглядывался по сторонам и бубнил:"},{"kind":"paragraph","text":"— Майя, прекрати, пожалуйста, на нас уже люди смотрят."},{"kind":"paragraph","text":"«Клеила» благоверного она недолго: после нескольких бокалов шампанского Семёну Юрьевичу стало плохо, и супруги по-английски удалились с торжества. Сына дома не оказалось: Валерка, как всегда, околачивался на улице. Учитель математики долго и мучительно «рычал» в унитаз, затем принял душ и, совершенно обессилевший, направился в спальню. Однако там ждало новое испытание. Его жена, облачённая в вульгарное белье, словно Мессалина, в распутной позе возлежала на кровати. Весь её похотливый вид говорил, что сейчас начнётся сексуальная оргия. Семён Юрьевич не ошибся. Едва он присел на краешек брачного ложе, как супруга набросилась на него, как на добычу. С решительным забвением приличия она погрузила мужа в такую вакханалию, что учителю не могло приснить-"},{"kind":"paragraph","text":"ся в самом грешном сне. Такого морального беспредела стены их спальни ещё не видели. Семён Юрьевич пытался сопротивляться, но куда там! Жена похотливой фурией обвивалась вокруг его тела, преподнося всё новые ласки, самые отвратительные из которых он видел начертанными на стенах школьного туалета. Это ошеломляющее открытие — что она себе позволяет! — стало для Семёна Юрьевича потрясающим уроком снижения его супруги. Утром Майя, улыбнувшись, взглянула на мужа, словно спрашивая: «Ну как, понравилось, дорогой?» Но натолкнулась на непривычно колючий прищур тёмно-­серых глаз: «Нет, не понравилось. Это было отвратительно», — безмолвно кричали они. Больше таких попыток она не делала. Между супругами возникли ­какие-то особые, обострённые отношения, хотя внешне всё было пристойно. С работы — Майя трудилась в строительном управлении — после той злополучной «свадебной» ночи, она стала возвращаться позднее, чем обычно, да и командировки участились. Семён Юрьевич делал вид, что задержки жены его мало волнуют, но на душе у учителя было смутно. Валерка чувствовал, что между родителями разлад, хотя и раньше их отношения едва ли можно было назвать идеальными. Каждый из них с утра погружался в свои дела и мысли. Уходя на работу, мать оставляла на столе завтрак и коротко бросала в пространство:"},{"kind":"paragraph","text":"— Обед в холодильнике, — перед тем, как захлопнуть дверь, добавляла: — К ужину не ждите. Возможно, приду поздно: готовлю квартальный отчёт."},{"kind":"paragraph","text":"И действительно, в те дни, когда она предупреждала о задержке, возвращалась за полночь. Отягощённый недоверием к столь поздней работе мамы, отец недовольно хмурился и вполголоса бубнил:"},{"kind":"paragraph","text":"— Где можно так долго шляться?"},{"kind":"paragraph","text":"— Мама ведь предупреждала, что задержится, — Валерка вновь жалел папу. Он смотрел на часы и оптимистично-­фальшивым голосом добавлял: — Скоро уже придёт."},{"kind":"paragraph","text":"На лице отца застывала каинова печать интеллигента-­ неудачника. Едва заметно кивнув, он молча уходил в спальню. Валерке же нужно было общение — он с юношеской жадностью начинал познавать мир. Дома ему никто не объяснял, почему ему так часто стала сниться Лариска с соседнего подъезда, почему не засчитали гол Кержакова в ворота бельгийцев, почему все говорят, что «ганжибас» употреблять плохо, а рок-музыканты охотно это делают? Однако ответы на подобные вопросы можно было услышать около беседки, в которой дворовые мужики играли в домино или в шахматы. Они будто соревновались друг с другом в излишествах и пороках: курили дешёвые, с запахом горящего сарая, сигареты, пили купленный у Люськи самогон и жутко сквернословили. Эти весёлые, плохо разговаривающие, зачастую грубые люди ­почему-то притягивали Валерку к себе. Как, впрочем, и остальных мальчишек двора. Они, со слов Пашилётчика, вскоре выяснили, что Лариска так часто улыбается потому, что «уже давно просится на травку»."},{"kind":"paragraph","text":"— Кержаков, оказывается, спит на ходу, потому его больше не берут в сборную, — авторитетно заявлял дядя Саша. Он же, с видом знатока, добавлял: — Курить гашиш — гиблое дело, уж лучше стакан-­другой портвейна хлопнуть."},{"kind":"paragraph","text":"К­то-то из мужиков высказался и о Валеркиной маме. Мол, идёт и попкой всем подмигивает. На него тут же цыкнули остальные — сынок её тут. Сколько Валерка потом не приглядывался, так ничего подобного не смог заметить. Когда взрослая беседа приобретала уж слишком фривольный оттенок, мальчишек отгоняли прочь. Да и больно надо! Колька-­армянчонок нашёл"},{"kind":"paragraph","text":"на чердаке оставшиеся от своего отца порнографические журналы, и они как следует рассмотрели некоторые пикантные особенности женского тела. Не понравилось… Серёжка Червонный сказал, что всё это фигня, и лучше сходить на озеро искупаться. Так они и сдружились, как это происходит, наверное, на каждой улице, в каждом дворе."},{"kind":"paragraph","text":"Валерке нравилось в своих друзьях всё, вернее, почти всё. Его немного смущала кличка, которую ему присвоили новые товарищи. Ещё он не любил, когда Червонец заставлял их надевать боксёрские перчатки и драться друг с другом. Впрочем, в боксёрскую секцию Валерке тоже пришлось идти. Один за всех, все за одного… Однако редкая тренировка заканчивалась без синяка под глазом, разбитой губы или припухшего носа. Однажды отец, удивлённо разглядывая очередной фингал, тихо спросил:"},{"kind":"paragraph","text":"— Обижают во дворе, сынок?"},{"kind":"paragraph","text":"— А хоть бы и обижали, — вмешалась в разговор мать. — Можно подумать, что ты пошёл бы заступаться, — она сердито гремела посудой."},{"kind":"paragraph","text":"— Я только спросить хотел, — ответил папа, опустив глаза."},{"kind":"paragraph","text":"— Спросить, спросить, — передразнила его мама. — Размазня…"},{"kind":"paragraph","text":"— Это меня на тренировке ударили! — выкрикнул Валерка. Ему так не хотелось, чтобы мама снова ругала отца."},{"kind":"paragraph","text":"— А ты не ори, — парировала мать и заявила: — На бокс свой больше ни ногой. Ходишь вечно в синяках, как уличный хулиган, — она сурово посмотрела на сына, ожидая, что он ей поперечит. Но Валерка возражать не стал и даже обрадовался запрету: теперь у него появилась веская причина отказаться от ненавистных тренировок."},{"kind":"paragraph","text":"— Мать не разрешает, — опустив глаза, буркнул он друзьям, когда пришло время собираться в спортивный зал."},{"kind":"paragraph","text":"— Мама не пускает… Бу-бу-бу-бу…— Юрка сплюнул на землю."},{"kind":"paragraph","text":"— А вот он и будет у нас Бу-­Бу, — усмехнувшись, сказал Червонец. — Кликуха лучше не придумаешь, — он повернулся к остальным мальчишкам: — Поняли?"},{"kind":"paragraph","text":"— Чего ж не понять? Поняли, — засмеялся Юрка. — Иди, Бу-­Бу, к своей мамочке, она тебе шоколадку купит."},{"kind":"paragraph","text":"Так растаявшее мороженое делает пятно на рубашке — ничем не отмоешь. Теперь иначе как «Бу-­Бу» никто из друзей Валерку не называл. Долгое время Валерка не чувствовал за спиной отца никакой защищённости и даже стеснялся его интеллигентской неловкости. Но однажды произошло событие, поставившее папу на пьедестал героя. И теперь уже он, Валерка, ходил с гордо поднятой головой, охотно рассказывая друзьям и соседям подробности отважного поступка отца. К­ак-то июльским жарким днём мама сказала, что к ней придёт подруга и, чтобы Валерка с отцом не мешали женщинам секретничать, отправила их на городской пляж. Спасаясь от пекла, они часа два плескались в тёплой мутной воде, затем пообедали в чебуречной и снова вернулись на водоём."},{"kind":"paragraph","text":"— Может, домой пойдём, пап? — с нескрываемой скукой в голосе спросил Валерка."},{"kind":"paragraph","text":"— Мама ведь сказала, чтобы мы возвращались домой только вечером, — отец, словно оправдываясь, развёл руками. Было видно, что ему самому надоел принудительный отдых. Медленно тянулось время. День клонился к закату, неохотно отпуская тепло."},{"kind":"paragraph","text":"— Смотри, сынок, — отец указал пальцем на верхушки тополей. Закрыв собой почти половину неба, с запада надвигалась огромная тёмно-­лиловая туча. Стало сумрачно и тихо. Вдруг подул сильный порывистый ветер, и на горячий песок упали первые капли дождя. Уже через несколько секунд небеса обрушили на землю шипящие потоки воды. Ещё более усилившийся"},{"kind":"paragraph","text":"ветер ломал ветки деревьев, срывал пластиковые листы с кабинок для переодевания. Люди, не успев надеть верхнюю одежду, заполнили прибрежное кафе. Прильнув к окнам, они с интересом и даже с некоторым страхом наблюдали за буйством стихии. Последний шквал ветра, прогремев железной обшивкой крыши, нагнул деревья едва ли не до земли и стремительно помчался дальше. И вновь стало тихо. Лишь тополя, роняя крупные капли, жалобно шелестели уцелевшими листьями."},{"kind":"paragraph","text":"— Пойдём, папа, — Валерка тронул отца за руку. — Дождь уже закончился."},{"kind":"paragraph","text":"— Закончился? — переспросил он. Кажется, мысли отца находились очень далеко отсюда. Они вышли из кафе и, минуя огромные мутные лужи, направились к дому. Брюки, чтобы не испачкать их грязью, не надели. Сквозь поредевшие тучи радостно пробились последние лучи заходящего солнца. Гроза миновала. Возле поваленного бурей дерева собралась небольшая толпа. Бестолково толкаясь и мешая друг другу, люди суетились вокруг лежащего на земле мальчишки. Но близко к нему никто подходить не решался."},{"kind":"paragraph","text":"— Всё понятно, — сказал отец, когда они поравнялись с толпой. — Током ударило."},{"kind":"paragraph","text":"Мальчишечьего плеча касался оборванный провод, но все попытки желающих ему помочь были безуспешны."},{"kind":"paragraph","text":"— Бьёт, собака, — сказал один мужчина, пытающийся палкой сбросить провод с пострадавшего."},{"kind":"paragraph","text":"— А ведь не выдержит парнишка…— он с отчаянием посмотрел на окружающих."},{"kind":"paragraph","text":"— П­алка-то у вас мокрая, оттого и бьёт, — пояснил очевидную ситуацию ­кто-то из сочувствующих."},{"kind":"paragraph","text":"Отец стремительно натянул на себя брюки — наверное, ему казалось, что умереть в трусах будет крайне неприлично. Он выхватил из Валеркиных рук сухую рубашку, бросил её рядом с мальчишкой. Изловчившись, папа прыгнул на неё, а своей майкой обхватил смертоносный провод и отбросил его в сторону. Одна из женщин подбежала к мальчику и пощупала его пульс. «Живой!» — быстро взглянув на окружающих, она тут же принялась делать парнишке искусственное дыхание. Ощутив безопасность, зеваки подошли к ним вплотную и, естественно, принялись давать всевозможные советы. Отец же, напротив, попятившись, выскользнул из толпы и взял Валерку за руку."},{"kind":"paragraph","text":"— Пойдём, сынок? — спросил он."},{"kind":"paragraph","text":"— Пойдём, — ответил Валерка, широко открытыми глазами глядя на отца и не веря, что он, его папа, пару минут назад спас человека от гибели. За несколько секунд он разрушил представление о себе как о слабом, чуть нелепом, чудаковатом учителе математики. «Как жаль, что папин поступок не могли видеть мама, соседи и все мои друзья!» — словно от зубной боли, сморщился от досады Валерка."},{"kind":"paragraph","text":"— Нагулялись? — поинтересовалась мама, открывая им дверь. Настроение у неё было хорошее: видимо, встреча с подругой принесла много приятных минут. Однако через мгновение выражение её лица заметно изменилось."},{"kind":"paragraph","text":"— А где твоя рубашка? — вопрос, скорее всего, относился к Валерке, но мамин сердитый взгляд был направлен на отца."},{"kind":"paragraph","text":"— Я… Мы…— папа, похоже, растерялся и никак не мог ответить ей толком. А может, он и не помнил вовсе, что произошло с этой дурацкой рубашкой. Валерка попытался рассказать маме, как самоотверженно проявил себя отец, но она, не обращая внимания на его слова, бросила коротко-­привычное «растяпа» и ушла на кухню."},{"kind":"paragraph","text":"— Сынок, — папа печально взглянул на Валерку. — А давай об этом случае никому не будем рассказывать, хорошо?"},{"kind":"paragraph","text":"— Хорошо, — вздохнув, согласился мальчик. Всё бы так и закончилось обидным забвением, если бы… На следующий день в прихожей раздался звонок. К двери подошла мама."},{"kind":"paragraph","text":"— Валерий Добровольский здесь проживает? — спросил у неё ­кто-то."},{"kind":"paragraph","text":"— Сынок, к тебе пришли, — позвала Валерку мама. — А что, собственно, вам от него нужно?"},{"kind":"paragraph","text":"На пороге стояли несколько взрослых людей, и среди них — Валерка сразу его узнал — тот самый мальчишка, которого спас отец. Вскоре выяснилось, что взрослые — это родители мальчика, а также корреспондент и фотограф местной газеты. В брошенной на пляже Валеркиной рубашке находилась квитанция из прачечной, по которой и нашли эту квартиру. А отец Валерия Добровольского, как утверждали свидетели, и есть тот самый герой. Переждав слёзные благодарности родителей мальчишки, газетчики тут же принялись за работу — они хотели написать статью об отважном поступке отца. Хорошенькая журналистка безуспешно пыталась выудить у папы хоть ­какие-­нибудь подробности происшествия. Тот лишь краснел, бледнел, беспрестанно вытирал лоб платочком и безбожно заикался. Помогла мама."},{"kind":"paragraph","text":"— Сынок, расскажи, пожалуйста, девушке, как было дело."},{"kind":"paragraph","text":"Валерка добросовестно, не упуская сопутствующих подвигу подробностей, изложил всё по порядку."},{"kind":"paragraph","text":"— …и мы, забыв рубашку, пошли домой, — виновато взглянув на маму, закончил он повествование. Фотограф, ещё более смутив отца, несколько раз «щёлкнул» «отважного учителя». На следующий день вышла газета с репортажем о проис-"},{"kind":"paragraph","text":"шествии на пляже. Валерка, закупив в киоске несколько её экземпляров, с явным удовольствием раздавал их соседям и друзьям."},{"kind":"paragraph","text":"— Нуучитэлмаладэс! — дворник Ибрагим, прислонив метлу к плечу, разглядывал папину фотографию. Паша-лётчик, отодвинув костяшки домино в сторону, вслух читал заметку об отважном соседе."},{"kind":"paragraph","text":"— Вот тебе и Дуремар! — дядя Саша удивлённо прищёлкнул языком."},{"kind":"paragraph","text":"— Кто бы подумал…— Червонец, словно сомневаясь в подлинности снимка, долго исследовал изображение отца. Посмотрел на Валерку своим раскосым взглядом и сказал:"},{"kind":"paragraph","text":"— А мне всегда дядя Сеня нравился. Понты никогда не колотил, а как до дела дошло — настоящим мужиком себя проявил, — он аккуратно сложил газету и сунул её в карман. — Не возражаешь, я матери покажу?"},{"kind":"paragraph","text":"Валерка кивнул и довольно шмыгнул носом. Бу-­Бу чувствовал себя так, будто мальчишку спас именно он, а не папа. Интуитивно, с юношеской непосредственностью, Валерка понимал, что в сказанном есть здравый смысл. Червонец никогда не бросал слов на ветер. Даже мама смотрела на отца ­как-то особенно и порой загадочно улыбалась. Хотя роль, которую она отводила ему, оставалась прежней. На один день из тихони и размазни папа превратился в человека значительного и особенного, можно сказать, в героя. Но отца эта сиюминутная популярность только смущала. Он ещё больше терялся, если ­кто-нибудь из соседей выказывал ему восхищение. Однако Валерке такая перемена очень нравилась. Раз за разом, с новыми обнадёживающими подробностями, он вещал знакомым о случае на пляже. Казалось, этот эпизод вдохнул в него значительную долю уверенности и даже некой дерзости. На берегу озера, в кулачных поединках с Чомгой, Бу-­Бу непременно стал побеждать армянчонка, хотя ранее их бои шли с переменным успехом."}]'::jsonb,
  '2021-12-30T12:00:00.000Z'
)
