INSERT INTO "Articles" (slug, title, author_id, cover_path, cover_blur, cover_width, cover_height, excerpt, content_blocks, published_at)
VALUES (
  'mrd2-adelaida',
  'Аделаида',
  (SELECT id FROM "Authors" WHERE name = 'Дарина Стрельченко' ORDER BY id LIMIT 1),
  'mrd2/mrd2-adelaida.jpg',
  'data:image/jpeg;base64,',
  1200,
  999,
  '— Ада! — крикнул я. — Свари кофе!',
  '[{"kind":"image","path":"mrd2/mrd2-adelaida.jpg","caption":null},{"kind":"paragraph","text":"— Ада! — крикнул я. — Свари кофе!"},{"kind":"paragraph","text":"Вместо того, чтобы послушно загреметь туркой, она недовольно попросила:"},{"kind":"paragraph","text":"— Не называй меня Ада, — но всё же отправилась на кухню."},{"kind":"paragraph","text":"Странные пошли роботы, однако."},{"kind":"paragraph","text":"— Ада, как тебе новый сезон «Рассказа служанки»?"},{"kind":"paragraph","text":"— Я же просила: не называй меня так! — раздражённо проговорила она. Поправила волосы из канекалона и примирительно произнесла: — Аделаида. Несложно, правда?"},{"kind":"paragraph","text":"— Слишком длинно."},{"kind":"paragraph","text":"— Люди совсем разучились запоминать, — хмыкнула она. Матово блеснуло полихлорвиниловое веко — совсем как настоящее."},{"kind":"paragraph","text":"— Ада… Аделаида! Срочно «Скорую»! Площадь Карнавалов…"},{"kind":"paragraph","text":"— …Тринадцать, квартира двадцать пять, — подхватила робот. — Я вызвала. Уже. Слышала, как ты звонил маме. Судя по тому, что она описала — просто отравление. Всё будет в порядке. Не переживай."},{"kind":"paragraph","text":"— Спасибо, Ад… делаида…"},{"kind":"paragraph","text":"Я начал подозревать, что с ней ­что-то не так, в первый же вечер. Она сразу же начала обращаться ко мне на «ты», иногда подкалывала, часто капризничала, когда я ставил её на зарядку. Дальше пошли эти выкрутасы с именем, а ведь по документации универсусам вообще плевать, как их зовут. А потом она интерпретировала мой разговор с мамой и, предупредив мою просьбу, вызвала врача. Я перечитал инструкции и убедился: хикки-­роботам такая эмоциональная интерпретация не доступна."},{"kind":"paragraph","text":"Т­огда-то я и решил показать её специалисту."},{"kind":"paragraph","text":"— Ты оделась? — Тебе больше нравится синее платье или зелёное? — Зелёное."},{"kind":"paragraph","text":"Для робота, призванного стать идеальным компаньоном, вопрос вполне стандартный. Нестандартно вышло, когда Ада появилась из гардеробной в синем."},{"kind":"paragraph","text":"— Я же сказал, мне больше нравится зелёное."},{"kind":"paragraph","text":"— А мне — синее, — улыбнулась она и пошла открывать дверь: Вадим, вопреки ожиданиям, явился минута в минуту."},{"kind":"paragraph","text":"— Привет, привет! — Он кивнул мне, галантно поклонился Аде. — Что там у вас стряслось? Барахлит зарядник?"},{"kind":"paragraph","text":"— Ничего у меня не барахлит, — насторожилась Аделаида."},{"kind":"paragraph","text":"— Не барахлит, не барахлит, — кивнул я. — Сделай нам кофе."},{"kind":"paragraph","text":"— Не бережёшь сердце, — вздохнула робот и скрылась за стеклянной дверью кухни."},{"kind":"paragraph","text":"— Нравная она у тебя, — заметил Вадим, вешая на крючок пальто."},{"kind":"paragraph","text":"— Вот именно. Даже слишком… Осмотри её, а? Мне кажется, шалит центр эмоций…"},{"kind":"paragraph","text":"— Усыпляй. Посмотрим."},{"kind":"paragraph","text":"— Боюсь, придётся подождать, пока кончится зарядка. Заикнёшься о выключении — сразу истерика…"},{"kind":"paragraph","text":"Вадим проводил мелькнувший за стеклом силуэт задумчивым взглядом. Пожал плечами."},{"kind":"paragraph","text":"— Могу попробовать договориться."},{"kind":"paragraph","text":"— Попробуй…— без особой уверенности кивнул я."},{"kind":"paragraph","text":"Вадим исчез в кухне, а через пять минут вышла Аделаида, быстро глянула на меня и шепнула, что разрешает себя усыпить. Села в кресло, расстегнула на спине платье, позволила нажать на неприметную стандартную родинку под лопаткой. За несколько секунд, прошедших до того, как она заснула, её зрачки расширились: если бы речь шла о человеке, я бы сказал, что в них мелькнул страх."},{"kind":"paragraph","text":"— Я быстро, — обнадёжил её Вадим, и Ада уснула, но не закрыла глаза, как делают во сне люди, а бесстрастно уставилась в потолок."},{"kind":"paragraph","text":"— Ну-те-с, ну-те-с, — забормотал друг, стягивая с её лопаток покрытую канекалоновым пушком кожу. — Что тут у нас… С эмоциями всё в порядке, центр работает. С реакциями тоже всё хорошо. Давай посмотрим центр переосмысления. Нуте-с… ну-те… Мля, Дима! Крышка сорвана!"},{"kind":"paragraph","text":"— А?.."},{"kind":"paragraph","text":"— Щель. Щёлочка. Клапан пропускает."},{"kind":"paragraph","text":"— Какой клапан? Попроще можно?"},{"kind":"paragraph","text":"Вадим отстранился от Ады. Хмуро глянул в потолок. Напряжённо спросил:"},{"kind":"paragraph","text":"— Никогда не задумывался, что отличает робота от человека?"},{"kind":"paragraph","text":"— Мысли? Чувства? — глуповато предположил я."},{"kind":"paragraph","text":"— Мысли и чувства им впаивают на заводе, — ответил друг, опасливо заглядывая в глаза спящей Аделаиде. — Но все эти мысли и чувства — стандартные. Предустановленные. Если роботу сказали, что убивать — это плохо, то он будет считать так до самой утилизации, и ты его не переубедишь. Просто потому, что на центре переосмысления опыта стоит блок. У твоей, — Вадим показал на Аду, — крышка прилегает к клапану неплотно. Она не переосмысляет весь новый опыт, но кое-что просачивается. Кроме того, посмотри: сорвана пломба. Но не срезана, а просто отошла и, к тому же, исцарапана. Скорее всего, из-за механического воздействия вроде вибрации."},{"kind":"paragraph","text":"— И как так случилось? — спросил я, чувствуя, как мерзко покалывает кончики пальцев."},{"kind":"paragraph","text":"— А где ты её брал?"},{"kind":"paragraph","text":"— В «Шёлковой дороге»."},{"kind":"paragraph","text":"— Тогда, может быть, из-за тряски. У нелегальных поставщиков нет фирменных контейнеров с креплениями, вот и возят роботов как дрова. Случай, конечно, один на миллион. Но…"},{"kind":"paragraph","text":"— И что мне теперь делать?"},{"kind":"paragraph","text":"Вадим пожал плечами. Я растерянно подошёл к Аде, взял кабель, поднёс к спрятанному под волосами порту на шее."},{"kind":"paragraph","text":"— Погоди, — велел друг. — Ты понимаешь, что это частичное воодушевление? Нужно либо убрать, либо узаконить…"},{"kind":"paragraph","text":"— Убрать? — переспросил я, глядя в бледное, безмятежное, почти человеческое лицо."},{"kind":"paragraph","text":"— Дим. Это незаконно ­вообще-то. Блок снимают только у роботов, которые призваны заменить умерших людей. Чтобы они учились вести себя похоже на тех, кого заменяют… А у остальных это нельзя."},{"kind":"paragraph","text":"— И что делать? Если я не хочу… убирать?"},{"kind":"paragraph","text":"— Подай заявку, что у тебя ­кто-то умер из близких, и ты хочешь их прототип."},{"kind":"paragraph","text":"Я присвистнул."},{"kind":"paragraph","text":"— Сколько та заявка стоит! Я за сто лет не наскребу."},{"kind":"paragraph","text":"— Тогда не свети её, — кивнув на Аду, посоветовал Вадим. — С собой не води, гостей не зови. Если никто не узнает, ничего и не будет."},{"kind":"paragraph","text":"— А если узнает?.."},{"kind":"paragraph","text":"— Штраф, — развёл руками Вадим. — И изъятие робота."},{"kind":"paragraph","text":"— А что мне ей сказать? Когда проснётся?"},{"kind":"paragraph","text":"— Скажи, что пыль почистил на клапане эмоций. Это стандартная процедура, она должна знать."},{"kind":"paragraph","text":"— Дим."},{"kind":"paragraph","text":"Я вздрогнул: Ада ещё никогда не звала меня по имени."},{"kind":"paragraph","text":"Обернулся."},{"kind":"paragraph","text":"Она лежала в кровати, укрывшись до носа. В свете бра я разглядел припухшие веки, красные щёки, лихорадочно блестящие глаза. Если бы Ада не была роботом, я сказал бы, что она выглядит как самый настоящий прихворавший человек."},{"kind":"paragraph","text":"— Что? — как можно мягче спросил я, подкатываясь к ней вместе с креслом."},{"kind":"paragraph","text":"— Не выключай меня больше."},{"kind":"paragraph","text":"— Я и не собирался."},{"kind":"paragraph","text":"— Не выключай, пожалуйста."},{"kind":"paragraph","text":"— Что такое, Аделаид? Даже если выключить, ты же всё равно проснёшься, как только подключишься к сети."},{"kind":"paragraph","text":"— Понимаешь, — она приподнялась на локте, поймала мою руку, прижала к щеке, — я испугалась сегодня. Это очень холодно — засыпать. У меня такое чувство… что если отключат, то я уже не включусь."},{"kind":"paragraph","text":"Я погладил её пальцы, поправил одеяло."},{"kind":"paragraph","text":"— Никто тебя не отключит. Всё будет хорошо."},{"kind":"paragraph","text":"— А что сказал твой друг?"},{"kind":"paragraph","text":"— Я же тебе объяснил. Просто почистил пыль на эмоклапане, проверил схемы…"},{"kind":"paragraph","text":"— Нет. Ты не понял. Я имею в виду — что он на самом деле сказал? Я же чувствую, что эмоклапан не трогали. — Аделаида нетерпеливо дёрнула плечом. — Я бы поняла, если бы он ­что-то чистил."},{"kind":"paragraph","text":"— Ну… Слушай, ты лучше у него спроси. Мне он именно так сказал."},{"kind":"paragraph","text":"Ада посмотрела на меня грустно и с обидой."},{"kind":"paragraph","text":"— Я же даже в выключенном состоянии воспринимаю волны — вы ведь не поставили общую блокаду. Я проснулась и интерпретировала…"},{"kind":"paragraph","text":"Она помолчала, мягко улыбнулась и виновато добавила:"},{"kind":"paragraph","text":"— Я же чувствую, когда обманывают."},{"kind":"paragraph","text":"Зря я позвал Вадима. Он открыл мне глаза. А может, его действия сделали щель в клапане ещё шире: теперь я отчётливо видел, как Аделаида меняется, становится всё умнее, всё человечней. Она жадно вбирала и интерпретировала новый опыт, всё меньше походя на сошедший с конвейера прототип и всё больше напоминая индивидуально настроенного антропоморфа."},{"kind":"paragraph","text":"Совет не показывать её людям плохо сочетался с целью, для которой я приобрёл Аду. Для покупки, — пусть даже в «Шёлковой дороге», — мне пришлось влезть в долги, и теперь нужно было отдавать кредит, жить самому, содержать робота… Отказаться от работы выглядело немыслимым, так что я продолжал шить шмотки, а Ада каждый день выходила на подиум, чтобы вертеться перед экспертами и позировать фотографам, клепавшим объёмные натуры для виар-шопов."},{"kind":"paragraph","text":"Сказать, что я жалел о её покупке — соврать. Своя модель — это настоящая роскошь: пропорции, которые можно подкрутить в соответствии с продукцией; походка, которую можно скорректировать в зависимости от подиума, коллекции и предпочтений жюри; безлимитные примерки и возможность перенастраивать внешность без страха испортить арендованного робота. Кроме того, она была нужна мне для Недели робомоды. Если меня заметят, пойдёт уже совсем другая история: не придётся выбивать заказы, выискивать жильё по дешёвке, обходиться стандартными материалами… Я получу допуск к цифровой материи, если повезёт — возьму заказ на разработку моделей для конвейера. А это уже совсем другие деньги! Совсем другие перспективы…"},{"kind":"paragraph","text":"От мечтаний разморило: я чуть не проглотил зажатую во рту булавку и спустился с небес на землю."},{"kind":"paragraph","text":"Чтобы всё получилось, предстояло пахать и пахать."},{"kind":"paragraph","text":"Я готовил коллекцию для Недели робомоды ночами — Аде было хоть бы хны, а я жёстко недосыпал, но желание пробиться перевешивало всё. Тем более, на первых порах мы с ней сработались просто отлично. Я смог творить почти круглосуточно, подновил и выставил на продажу старые коллекции — на подтюненной Аде даже прошлогодние шмотки выглядели вызывающе аппетитно. К концу квартала почти выплатил кредит, купил ей мощный зарядный блок, мы слетали в Египет. Дальше пошло ещё круче. А потом… Потом и проявилась её нравность."},{"kind":"paragraph","text":"Впрочем, я оказался нравен не меньше, подумав в один из вечеров, что мне совсем не хочется, чтобы Ада выходила на подиум. От мысли, что на неё вновь будут пялиться жюри, спонсоры, эксперты и — в отдалении — толпы чужих мужиков, подкатывала тошнота."},{"kind":"paragraph","text":"Я тряхнул руками и выругался. Ада ойкнула: я случайно уколол её иголкой."},{"kind":"paragraph","text":"— Прости! — Задумался? — Ага…"},{"kind":"paragraph","text":"Я посмотрел, как она глядит в зеркало, как трогает подшитый низ платья, ощупывая ткань длинными загорелыми пальцами. Решил, что Неделю робомоды мы отработаем на двести процентов."},{"kind":"paragraph","text":"А потом заляжем на дно."},{"kind":"paragraph","text":"В понедельник отгремело оглушительное открытие. Салют, фонтаны шампанского (Ада попробовала, но сказала, что ей не понравилось), фуршет, блеск чужих коллекций… Я рассматривал их с замиранием сердца: изучал фактуру, швы, покрой, лекала. Раньше я мог разглядывать шмотки только на экране, но в этом году у меня появился робот, и я наконец купил билет: дизайнеров пускали на выставки только в паре с моделями."},{"kind":"paragraph","text":"Вторник и среду я не отрывал взгляда от подиума: шли коллекции корифеев. Ада дёргала меня, звала в кафетерий, в зону интерактива, просилась познакомиться с другими моделями, но я отмахивался, заставляя её сидеть рядом. На субботу был назначен наш выход, и я страшно нервничал, что с ней ­что-то произойдёт. Подпортить чужую модель — на таких мероприятиях считалось едва ли не хорошим тоном."},{"kind":"paragraph","text":"Весь четверг я подшивал, подгонял, перекраивал и наводил лоск на свою собственную коллекцию. Аделаида нервничала: видимо, моё лихорадочное состояние передалось и ей. К вечеру мы заказали таксокар и повезли коллекцию в павильон. Зашли со служебного входа: с парадного из-за репортёров и гостей было не пробиться. Я миновал турникет, держа на весу бесценный вакуумный пакет со сжатой одеждой, прошёл уже десяток шагов, когда услышал сзади испуганное и беспомощное:"},{"kind":"paragraph","text":"— Дима!.."},{"kind":"paragraph","text":"Оглянулся. Ада растерянно стояла перед турникетом, такая красивая, непорочная и яркая в дерзком неоновом свете — а за локоть её держал дубина-­охранник."},{"kind":"paragraph","text":"— Просрочена лицензия, — скрипуче заявил он."},{"kind":"paragraph","text":"Я запрокинул голову, выругался про себя, сжал бы кулаки, если бы руки были свободны. Как некстати! А ведь говорил себе, что нужно проверить… Лицензия действовала год и активировалась на следующий день после покупки робота. Но мастера «Шёлковой дороги» часто проводили оживление по лицензии другого робота — уже списанного, но ещё не утилизированного. Ада оказалась не исключением…"},{"kind":"paragraph","text":"— Просрочена лицензия, — повторил охранник."},{"kind":"paragraph","text":"На робота было жалко смотреть."},{"kind":"paragraph","text":"— Это я виновата…— всхлипнула Ада, забиваясь в угол таксокара."},{"kind":"paragraph","text":"— Да при чём тут ты, — буркнул я. — Я же хозяин. Нужно было позаботиться."},{"kind":"paragraph","text":"— Я могла напомнить… Забыла…"},{"kind":"paragraph","text":"Нормальные хикки-­роботы о таких вещах не забывают — что ещё раз доказывало, что Ада не нормальна."},{"kind":"paragraph","text":"«Не свети её», — вспомнил я слова Вадима. Потом вспомнил, какой гонорар полагался за выступление на Неделе робомоды. Вспомнил, какие открывались перспективы."},{"kind":"paragraph","text":"Живут же люди с роботами-­нелегалами. К­ак-то решают проблемы с лицензией. Не я первый, не я последний."},{"kind":"paragraph","text":"— Аделаида."},{"kind":"paragraph","text":"Она вскинула голову; в глазах вспыхнули огоньки проносившейся мимо ночной столицы."},{"kind":"paragraph","text":"— Собери свои документы. И запиши меня в МФЦ на завтра. На самый поздний слот."},{"kind":"paragraph","text":"— Добрый день. Мне нужно обновить документы на замещающего робота. — По утере или по графику? — По графику."},{"kind":"paragraph","text":"Я протянул в окошко папку с бумагами Аделаиды, мысленно повторяя легенду."},{"kind":"paragraph","text":"Если верить статистике, вечером пятницы служащие бывают не очень расторопны и не слишком внимательно всматриваются в документы. Но, увы, мне попалась служащая иного сорта. Несмотря на то, что её коллеги в соседних окошках уже гремели стульями и натягивали плащи, она помахала моей папкой и воззрилась не без сомнения:"},{"kind":"paragraph","text":"— Это не замещающий робот."},{"kind":"paragraph","text":"— О, извините… У меня их два, один замещающий и один хикки. Видимо, перепутал… Прошу прощения."},{"kind":"paragraph","text":"Я протянул руку, но служащая не спешила отдавать папку."},{"kind":"paragraph","text":"— Вы в курсе, что лицензия на…— она быстро глянула в паспорт и снова воззрилась на меня: — Аделаиду просрочена?"},{"kind":"paragraph","text":"— М-м… возможно. Я займусь этим, — пообещал, берясь за уголок папки."},{"kind":"paragraph","text":"— Вы знаете, что владение роботом без лицензии влечёт за собой административную ответственность?"},{"kind":"paragraph","text":"— Да, да. Прощу прощения. Я займусь этим завтра же… Вернее, в понедельник, с самого утра."},{"kind":"paragraph","text":"Служащая резко дёрнула на себя папку и бросила паспорт Аделаиды на сканер."},{"kind":"paragraph","text":"— Я поставлю вас на контроль."},{"kind":"paragraph","text":"— М-м… Мы можем обойтись без этого? — улыбаясь самой очаровательной улыбкой, которую Ада называла «лорд», спросил я."},{"kind":"paragraph","text":"Внутри медленными ледяными пузырьками надувалась паника."},{"kind":"paragraph","text":"Можно было перегнуться через барьер окошка, дотянуться до паспорта, схватить папку и убежать. Но индекс Ады уже мерцал на мониторе. Побег означал бы мгновенный приговор."},{"kind":"paragraph","text":"Кляня себя за то, что позарился на гонорар за Неделю робомоды и вообще пошёл в МФЦ, я отчаянно повторил:"},{"kind":"paragraph","text":"— Мы можем обойтись без этого? Мой второй робот… Он замещает маму. Я… В последнее время я был слишком подавлен, выпустил из виду продление лицензии…"},{"kind":"paragraph","text":"— Сочувствую, — железным тоном ответила тётка, снимая паспорт со сканера и наконец отдавая мне документы. — Ждём вас с Аделаидой в понедельник для постановки на лицензионный учёт. Перед процедурой рекомендуется провести откат к заводским настройкам."},{"kind":"paragraph","text":"— Зачем? — похолодев, спросил я."},{"kind":"paragraph","text":"— Перед продлением лицензии хикки-­роботов возвращают к стандартным параметрам. Лучше заранее сделать это дома — потратите меньше времени здесь."},{"kind":"paragraph","text":"Я вышел из МФЦ, ничего не видя перед собой. Чуть не навернулся со ступеней. Солнце жгло, раскалённым шаром вертясь в зените."},{"kind":"paragraph","text":"— Аделаид, я задержусь. Разбери почту и отмени все заказы на завтра."},{"kind":"paragraph","text":"— Да, конечно, — чуть запыхавшись, ответила Ада. Я слышал стук, шорохи и шкворчание — очевидно, она готовила обед. — Ты надолго?"},{"kind":"paragraph","text":"— Час-два."},{"kind":"paragraph","text":"— Как раз дойдёт запеканка. Ой! Молоко убегает… Отключаюсь!"},{"kind":"paragraph","text":"Я представил, как она машет полотенцем, выгоняя из кухни запах гари, нервно улыбнулся и набрал Вадима."},{"kind":"paragraph","text":"— Слушай… Ты говорил, у тебя знакомый полиграфист. Сможет он подсобить с бумагами? Да… Просто отпечатать. Так, чтоб неотличимо от оригиналов. Да хоть сколько… Наскребу. Хорошо. Еду."},{"kind":"paragraph","text":"День давно перевалил за половину. По-весеннему пронзительно щебетали птицы. Я вышел из мрачного подвальчика типографии и снова набрал Вадима."},{"kind":"paragraph","text":"— Ничего не вышло. У твоего друга нет светокраски для штампов."},{"kind":"paragraph","text":"— Жаль, — после паузы ответил друг."},{"kind":"paragraph","text":"— Поеду туда, где покупал Аду, — медленно, больше себе, чем ему, сказал я. — Поищу пустые готовые лицензии."},{"kind":"paragraph","text":"— У тебя есть с собой электрошокер хотя бы? Без него туда лучше не суйся."},{"kind":"paragraph","text":"— Спасибо за науку."},{"kind":"paragraph","text":"Я набрал Аделаиду. С языка почти сорвалось: закажи электрошокер на угол Николямской и Синего шоссе. Но в последний момент, побоявшись напугать её, я выпалил:"},{"kind":"paragraph","text":"— Привет! Прости, всё ещё задерживаюсь. Сможешь зарядиться без меня?"},{"kind":"paragraph","text":"— Да, конечно, — растерянно ответила Ада. — Запеканка остыла уже…"},{"kind":"paragraph","text":"— Прости. Спешу, как могу."},{"kind":"paragraph","text":"День катился к вечеру, под палатками и пыльными козырьками киосков уже сгущалась мгла. Я шагал, минуя шопы, подпольные казино, цветочные лавки, лотки с масками и искусственными частями — для людей и роботов. Из кабаре с окнами в пол неслась сладкая, густая волна музыки и ароматов. Боясь прилипнуть, я поскорей проскочил мимо, но всё же не смог не задержать глаз на сцене за стеклом: снаружи к стене прибило грязь, огрызки и месиво брошюр, зато внутри сверкали огни, и девушки в блестящих диадемах и нарядах из перьев танцевали канкан. Их руки, ноги, павлиньи хвосты и разукрашенные лица мелькали так быстро, что было не различить, роботы это или люди."},{"kind":"paragraph","text":"Я встряхнулся. Краем глаза заметил позади двух типов в тёмных толстовках. Они шли за мной от самого входа на рынок — может, и не зря Вадим посоветовал шокер."},{"kind":"paragraph","text":"Я аккуратно повращал в карманах кулаки, повертел головой, разминая шею, — и с облегчением заметил на углу кабаре нужный символ. В минувшие два часа мне понадобилось пять звонков и два крупных перевода со счёта на счёт, чтобы узнать, как он выглядит."},{"kind":"paragraph","text":"Уже не думая о мрачных парнях, я свернул в проулок. Пробрался в тесный, похожий на душную теплицу шоп, закашлялся от привкуса специй и, жмурясь от сияния мелких кристаллов, заявил бледному с раскосыми глазами продавцу:"},{"kind":"paragraph","text":"— Мне нужна лицензия на робота. Такая, чтобы не отличить от настоящей."},{"kind":"paragraph","text":"— Нет такого. Цьветы продаём. Цьветочки только. Вербена, джусай, кровохлёбка. Цьветочки, нет лисензий."},{"kind":"paragraph","text":"Я хлопнул себя по лбу. Идиот."},{"kind":"paragraph","text":"— Я от Вениамина Каверина."},{"kind":"paragraph","text":"Чувствуя себя дурак дураком, процитировал:"},{"kind":"paragraph","text":"— Последняя минута тишины — выходит в город поезд из депо…"},{"kind":"paragraph","text":"— Вперёд! В зелёный шум, в еловый вой! — подхватил продавец тут же разулыбался, кивая мне и выставляя на прилавок плошку с орехами и дымящуюся чашку: — Пей! Ешь! Отдыхай! Предоставь всё мастеру Си!"},{"kind":"paragraph","text":"Он шлёпнул на дверь табличку «Занят» и скрылся за звенящими занавесками из янтарных бус. Я упал в продавленное кресло в уголке, не глядя влил в себя тёплое пойло. Впервые с тех пор, как Вадим сказал, что Ада незаконна, я почувствовал себя чуть спокойней."},{"kind":"paragraph","text":"— Для хороших друзей — что угодно! — щебетал продавец, грохоча и копаясь. — Мастер Си — мастер на все руки… Лисензия, сертификат, архивировать, память восстановить…"},{"kind":"paragraph","text":"Я достал телефон, чтобы набрать Аделаиде, но мастер Си, дополнительные глаза которого, вероятно, были вмонтированы в прилавок, крикнул:"},{"kind":"paragraph","text":"— Тут не ловить. Тут всё перекрываеть, по всему рынку…"},{"kind":"paragraph","text":"— Аделаид."},{"kind":"paragraph","text":"— Дима? Дима, где ты? Пытаюсь до тебя дозвониться, ты не берёшь…"},{"kind":"paragraph","text":"— Аделаид. Я тебе всё объясню. Я уже совсем скоро поеду домой. Совсем скоро."},{"kind":"paragraph","text":"— Дима… Я видела, ты заказывал электрошокер. Где ты?"},{"kind":"paragraph","text":"Голос Ады звенел. Я вдохнул и постарался ответить как можно спокойней:"},{"kind":"paragraph","text":"— Милая. Закрой двери на ночь. На звонки не отвечай. Я тебе всё объясню. Тебе ничего не угрожает, но просто на всякий случай поставь ночную защиту. Как обычно. Я скоро буду. Жди."},{"kind":"paragraph","text":"Я вошёл в наш холл, когда темнота уже напиталась мерзкой опасной чернильной дымкой. Щёлкнула дверь, и Аделаида выскочила навстречу — босая, в одной ночной сорочке."},{"kind":"paragraph","text":"— Я же велел закрыться на все замки…"},{"kind":"paragraph","text":"Ада не отвечая бросилась ко мне и прижалась, вся дрожа."},{"kind":"paragraph","text":"— Ну что ты… ну чего… Со мной ведь всё хорошо…"},{"kind":"paragraph","text":"— Ты был на катийском рынке. Я послала проверить… Несертифицированный шоп… Я не нашла никакой информации!"},{"kind":"paragraph","text":"— Так те парни были твоими соглядатаями?"},{"kind":"paragraph","text":"— Разве можно ходить в такие места одному? — прошептала Ада, и я впервые увидел в глазах робота слёзы. Я знал: их экзокринная система почти неотличима от людской, но… Просто ­как-то не доводилось раньше."},{"kind":"paragraph","text":"— Пойдём. Пойдём домой. Я тебя уложу, выпью чаю… И мне надо будет ещё раз уйти."},{"kind":"paragraph","text":"— Ты обещал объяснить всё, — цепляясь за меня, нервно потребовала Ада."},{"kind":"paragraph","text":"— Да… да. Только налей чаю, я тебя умоляю. Просто с ног валюсь…"},{"kind":"paragraph","text":"Час спустя пришло сообщение от мастера Си: лицензия готова. Я съел полпротивня холодной запеканки, выпил чашку сладкого кофе и поставил Аду заряжаться — без меня она не смогла толком выставить настройки, и теперь хоть и подняла заряд, маялась головной болью."},{"kind":"paragraph","text":"— А ещё двоится в глазах, — пожаловалась робот."},{"kind":"paragraph","text":"Я никогда не встречал такого синдрома неверной зарядки. Со страхом подумал, что, может быть, это ещё одно последствие катийской сборки. Даже если мне удастся отстоять Аду… Что будет дальше, что вылезет ещё? Сможет ли она вообще нормально функционировать — через месяц, через год? Через десять лет?.."},{"kind":"paragraph","text":"Я уложил Аделаиду и несколько минут сидел рядом, гладя её по руке."},{"kind":"paragraph","text":"— Когда Вадим проверял твои схемы, она обнаружил… мелкую поломку. Это ерунда, но лучше починить. Если делать это через МФЦ, уйдёт уйма времени, плюс налоги, плюс экспертизы… Я не хочу трепать тебе нервы, вот и купил нужную деталь через друзей. Это заняло чуть больше времени, чем я думал. Но всё уже готово. Мне осталось только съездить забрать. Ты потерпишь? Сейчас я уйду, но к утру уже буду дома."},{"kind":"paragraph","text":"Аделаида послушно, но встревоженно кивнула. На прощание, заглядывая в глаза, спросила:"},{"kind":"paragraph","text":"— Ты ведь осторожен, правда? Ты ведь знаешь, что за шопами, где нелегально торгуют деталями, следят соцслужбы?.."},{"kind":"paragraph","text":"Я кивнул, быстро чмокнул её в щёку."},{"kind":"paragraph","text":"— Всё хорошо. Успокойся. Всё будет хорошо."},{"kind":"paragraph","text":"Только выйдя из подъезда, я понял, как нелепо прозвучала эта фраза: «я не хочу трепать тебе нервы». Я как будто забыл, что говорю с роботом."},{"kind":"paragraph","text":"Мы проскочили по нижней магистрали до первых пробок, и я действительно вернулся домой ещё под утро. Вадим сунул мне антипохмельное и бормоча убрался обратно в салон таксокара. Я сжал блистер. Стараясь не делать резких движений, начал медленно подниматься."},{"kind":"paragraph","text":"В последние пять часов мне повезло трижды: во‑первых, я ­всё-таки заполучил лицензию на Аду: мне пообещали, что утром её индекс пропадёт с особого учёта. Во-вторых, со мной поехал Вадим: лазерные инструменты для нейронок в ночных лавочках катийского рынка стоили куда дешевле, чем у официальных дилеров. В-третьих, когда на рынок нагрянул патруль, друг сообразил заскочить в кабаре и затянул меня следом — так мы отделались всего лишь штрафом за посещение запрещённого места."},{"kind":"paragraph","text":"Как только патрульные вышли из прокуренного, пропахшего благовониями зала, я дёрнулся следом, но Вадим крепко взял меня за локоть и процедил:"},{"kind":"paragraph","text":"— Они сейчас второй волной пойдут по улице. Надо выждать… Спокойно!"},{"kind":"paragraph","text":"Он с силой усадил меня на глубокий бархатный диванчик. Музыка наяривала вовсю, голоса и грохот каблуков по сцене сливались в плотный, бьющий по ушам гул."},{"kind":"paragraph","text":"— У меня Ада одна дома…"},{"kind":"paragraph","text":"— Да что ей будет!"},{"kind":"paragraph","text":"— Её индекс на контроле…"},{"kind":"paragraph","text":"— Его снимут утром. Никто не придёт за роботом ночью в субботу. А если ты сейчас высунешься и рванёшь домой — живо накроют! Пойдём лучше, раз уж огребли, насладимся."},{"kind":"paragraph","text":"— А разве кабаре не закроют?"},{"kind":"paragraph","text":"— С луны свалился? — вздохнул друг, скользя взглядом по стёклышкам барной стойки. — Если закроют, где будет отдыхать доблестный патруль?"},{"kind":"paragraph","text":"Шла оперетка: тринадцать разукрашенных девиц прыгали на полукруглой сцене, и каждый раз выходило так, что хотя бы одна из них загораживала пышным хвостом середину. Костюмы были те же самые, что я видел днём — пёстрые, блестящие, вызывающие."},{"kind":"paragraph","text":"К нам подошёл официант, в пальцах сам собой очутился бокал — я не понял, с чем, ­какая-то зеленоватая жидкость. На вкус она напомнила пойло мастера Си, но ударила в голову куда ловчее. Ещё некоторое время я думал об Аделаиде, об индексах, о замещающих роботах, щелях и клапанах… А потом всё внутри взорвалось, заискрилось, и мне стало интересно только одно: что же спрятано в центре сцены?"},{"kind":"paragraph","text":"— Я доктор… Я роботовый доктор… — попадая в мотив, но совершенно мимо слов затянул Вадим."},{"kind":"paragraph","text":"— Они так бережно закрывают середину. Там ­что-то есть?"},{"kind":"paragraph","text":"— Я доктор… доктор… — Ну… на сцене? В серединке? — Я доктор… — Ты пьяница! — Я доктор…"},{"kind":"paragraph","text":"Всё мельтешило, тряслось, рябило. Тёмный неоновый зал заваливался на бок; глотку забивал густой, мылкий и горячий дух, сквозь который пробивались нотки пива. Пустой бокал в моей руке сменился полным."},{"kind":"paragraph","text":"— Что спрятано на сцене? — заплетающимся языком спросил я у официанта. — Жемчужина спрятана?.. За хвостами?.."},{"kind":"paragraph","text":"— Тум-ц-бара-бум-ц! — зарядили барабаны."},{"kind":"paragraph","text":"— Мсье о жемчужине балета? Вы увидите всё в конце представления."},{"kind":"paragraph","text":"Так это у них балет? Вот как…"},{"kind":"paragraph","text":"Конца представления я не дождался. Бокал наполнился снова, и сквозь цветное марево мне подмигнула одна из танцовщиц. Что же ­всё-таки спрятано у них на сцене, что за жемчужина такая, — успел подумать я и провалился в душистую жаркую пелену до самого рассвета."},{"kind":"paragraph","text":"После искусственных розовых лепестков, блеска и тошнотворной сладости своды подъезда окатили приятной прохладой. Я медленно выдохнул из себя все эти пайетки, перья, гирлянды, запах разгорячённых тел и нажал на кнопку звонка. Она отозвалась глухим резиновым чпоком: электричества не было."},{"kind":"paragraph","text":"Я дёрнул дверь. Она отошла легко, с привычным коротким шорохом. Внутри стояла тишина."},{"kind":"paragraph","text":"— Ада?"},{"kind":"paragraph","text":"Молчание."},{"kind":"paragraph","text":"— Аделаида?"},{"kind":"paragraph","text":"Сквозняк подогнал к моим ногам бумажку. Я нагнулся, поднял…"},{"kind":"paragraph","text":"«Опечатано. Патруль Эмска»."},{"kind":"paragraph","text":"«Ты ведь осторожен, правда? Ты ведь знаешь, что за шопами, где нелегально торгуют деталями, следят соцслужбы?..»"},{"kind":"paragraph","text":"Они ­всё-таки заподозрили ­что-то."},{"kind":"paragraph","text":"Они пришли."},{"kind":"paragraph","text":"Они пришли, а у Ады была просроченная лицензия."},{"kind":"paragraph","text":"И меня не было."},{"kind":"paragraph","text":"— Царапины, — глядя в пол, проговорил Вадим. — Забирали наскоро, выключили и поволокли. Если бы она ушла сама, царапин бы не было."},{"kind":"paragraph","text":"— А если бы я был дома?"},{"kind":"paragraph","text":"— Забрали бы вместе с тобой. Было бы хуже. А так только повестка придёт."},{"kind":"paragraph","text":"— А Ада?.."},{"kind":"paragraph","text":"— Выдадут новую."},{"kind":"paragraph","text":"— В смысле?"},{"kind":"paragraph","text":"— Если робот портится, его забирают на утилизацию, а владельцу выдают заводской экземпляр. Ты проверь гарантийные документы, там должно быть указано."},{"kind":"paragraph","text":"Новую Аду привезли, как только я уплатил штраф за содержание робота без лицензии. Уж это точно был настоящий сертифицированный робот прямиком с конвейера: ни скола, ни трещинки. Прекрасная молодая женщина. Спокойная, бестревожная. Словно глубоко спящая — или недавно умершая."},{"kind":"paragraph","text":"Копия моей Ады."},{"kind":"paragraph","text":"Пока я усаживал её в кресле, пока ставил на зарядку, пока снимал гарантийные пломбы на шее и за ушами, билась ужасающая, оглушающая надежда: а вдруг ­всё-таки она. Ада. А вдруг ­всё-таки откроет глаза и скажет: не зови меня так, зови меня Аделаида…"},{"kind":"paragraph","text":"Она открыла глаза, и оказалось, что они не синие — яркоголубые. Такие бывают у роботов, ­только-­только сошедших с ленты."},{"kind":"paragraph","text":"— Добрый день, — поздоровалась она, выпрямляясь. — Меня зовут Аде… Аде…"},{"kind":"paragraph","text":"Робот закашлялась. Я хотел похлопать её по спине, но она покачала головой, справилась с кашлем и сипло договорила:"},{"kind":"paragraph","text":"— Аделаида. Проблемы с речевым аппаратом. Это пройдёт. Пожалуйста, загрузите ваше расписание и мои рабочие обязанности."},{"kind":"paragraph","text":"От неё пахло заводом: свежим пластиком и стандартным парфюмом."},{"kind":"paragraph","text":"Меня пробрала дрожь. Я дёрнул шнур, вытащив его из розетки. Аделаида-два медленно, совсем как человек, закрыла глаза. Аделаида-один тихонько попросила из глубин памяти: «Не выключай меня больше. Это очень холодно — засыпать. У меня такое чувство… что… если отключат, я уже не включусь»."},{"kind":"paragraph","text":"Я взял кредит и отправился по промышленным полисам — по всем пунктам, куда роботов сдавали на ребут. Еутов, Оролёв, Осад, Алашиха. Кхимки, Нитищи, Юберцы… На втором десятке я сбился со счёта. Перед глазами плясали приёмные пункты и офисные конурки при цехах, голова гудела от грохота конвейеров, проникающего сквозь заслоны и стены. Бесконечной лентой убегала и убегала дорога."},{"kind":"paragraph","text":"— Сдалась она тебе? — в который раз спрашивал Вадим, нежно-­салатовый от тряски. Мы исколесили всё Подэмсковье, но даже с его служебным пропуском всё было безрезультатно. От Ады не было и следа."},{"kind":"paragraph","text":"Оставался последний пункт. В который нас не пустили — закрыто на перезапуск линии."},{"kind":"paragraph","text":"— Она тут, — заявил я."},{"kind":"paragraph","text":"От голода и долгой езды потряхивало. Я не был уверен, что говорю именно то, что думаю. Я уже сам не понимал, куда мы приехали и зачем. Огромные металлические ворота, блестящие на солнце, упёршийся в них путь. Расплавленный асфальт под колёсами, палящий полдень и пустота, пустота, пустота…"},{"kind":"paragraph","text":"— Значит, её просто ещё не сдали. Или уже ребутнули. Дима. Ты пойми… Шанс, что мы её найдём, что успеем перехватить до сброса настроек… Зачем она тебе? Давай я помогу собрать денег, купишь нормального замещающего робота. Помогу тебе его подстроить по-своему… Дима!"},{"kind":"paragraph","text":"— Вот ты зачем со мной едешь? — вцепившись в руль, спросил я."},{"kind":"paragraph","text":"— Ты мой друг."},{"kind":"paragraph","text":"— Друг?.."},{"kind":"paragraph","text":"— Безусловно. А ­она-то чего тебе далась?"},{"kind":"paragraph","text":"— Безусловно, — пробормотал я и вжал педаль."},{"kind":"paragraph","text":"Вадим замолчал. Некоторое время он смотрел в окно — как проносились мимо трубы, градирни и стоянки, как мелькали, сходясь и расходясь, провода. Наконец повернулся ко мне. Велел:"},{"kind":"paragraph","text":"— Сверни на нижнюю магистраль. — Зачем? — Поедем на катийский рынок. — Опять? — Ты не в себе. Выпьем, расслабимся. — Выпить можно и в другом месте. — Поехали-­поехали."},{"kind":"paragraph","text":"Я не заметил, как мы очутились в знакомом узком зале. В ладонь мягкой прохладой лёг круглый изумрудный бокал. Официант предупредительно склонился, ожидая, какую выпивку я предпочту сегодня."},{"kind":"paragraph","text":"Жалюзи глушили свет, под низким потолком стоял сумрак, и со сцены снова неслась знакомая едкая оперетка. Снова мелькали пушистые павлиньи хвосты, розовые перья, обтянутые капроном ляжки."},{"kind":"paragraph","text":"Я залпом опустошил бокал и махнул, требуя ещё. Танцовщицы всё ускоряли темп, в ­какой-то миг сцена напомнила мне карусель — увешанная огнями, вечно в движении, в скольжении и сиянии, без финала, без цели."},{"kind":"paragraph","text":"Я пил и пил. Окружающее давно потеряло фокус, вокруг плавали благостные цветные пятна, и единственное, что омрачало мир, — та тянущая пустота внутри, которую не заглушали ни таблетки, ни снеки, ни бокалы «Изумрудного дракона»."},{"kind":"paragraph","text":"Вадим мычал, то и дело подталкивая меня в бок. Я подумал, что ещё чуть-чуть — и я тоже завою «я доктор», не попадая в музыку и слова. Может быть, этого мне и надо."},{"kind":"paragraph","text":"В тот миг, когда я решил, что сегодня точно упьюсь вконец, Вадим дёрнулся и въехал мне локтем под рёбра. Грянул оркестр, выпитое рванулось наружу, я вскочил, и перья на сцене наконец разошлись, открывая моему взору…"},{"kind":"paragraph","text":"Аделаиду."},{"kind":"paragraph","text":"Хмель слетел в момент. Это точно была моя Ада: я видел это по синим блестящим глазам, по ямочке у локтя, по тому, как она вздёргивала губу. Она двигалась в танце совсем так же, как кружилась перед зеркалом, когда я примерял на неё новые наряды. Она улыбалась, глядя прямо на меня, и не узнавала."},{"kind":"paragraph","text":"— Ада! Это Аделаида! — закричал я, тряся Вадима."},{"kind":"paragraph","text":"— Я доктор, — нудил он, падая на пол. Я бил его по щекам, плескал ч­ то-то в лицо…"},{"kind":"paragraph","text":"— Эй, доктор! Проснись!"},{"kind":"paragraph","text":"К нему уже бежали официанты — поднять, оттащить туда, где пьяный клиент протрезвеет, не смущая других посетителей."},{"kind":"paragraph","text":"На сцене творилась фантасмагория: гремел оркестр, яростно грохотали барабаны, сверкали прожектора, рассыпался мелкий блестящий бисер. Я ловил взгляд Ады, и внутри шипело и жгло, словно проглотил кислоты."},{"kind":"paragraph","text":"— Официант! — яростно щёлкая пальцами, завопил я. — Официант! Кто тут отвечает за девочек? Мне понравилась танцовщица… Вон та, в центре, синеглазая!"},{"kind":"paragraph","text":"— Это очень дорогая услуга, мсье, — прокричал официант, перекрывая музыку. — Вы должны обговорить это с хозяином заведения."},{"kind":"paragraph","text":"— Ведите меня к нему! — рявкнул я, хватая парня за накрахмаленный рукав. — Сейчас же! Любые деньги! Ну!"},{"kind":"paragraph","text":"Вадим откатился от дивана, шлёпнул кулаками по коленям и бросил:"},{"kind":"paragraph","text":"— Подтёрто начисто."},{"kind":"paragraph","text":"— Вадик. Ты же мастер, — дрожащим льстивым голосом просипел я. — Ты же купил эти свои нейронные инструменты. Ты наверняка можешь… Если не целиком, то хотя бы частично… Вадик…"},{"kind":"paragraph","text":"Я говорил, говорил, но по его лицу видел — бессмысленно."},{"kind":"paragraph","text":"— Щель в клапане запустила процедуру воодушевления. А ребут прервал её, и это сбило все настройки, затронуло архивационные центры. Дим… Ничего не осталось. Я не в силах вернуть ей память."},{"kind":"paragraph","text":"— Но…"},{"kind":"paragraph","text":"— Я ничего не могу сделать. Прости."},{"kind":"paragraph","text":"Я проглотил противную горечь в горле — выпивка, блевотина, пыль. Голова кружилась. Ада лежала на диване — бесчувственная и безмятежная."},{"kind":"paragraph","text":"— Дим. Дима, — звали меня из далёкого далёка. — Нельзя зацикливаться. Это всего лишь робот. Я посмотрю сертификаты, попробую подобрать тебе ­что-то похожее. Заранее заархивируем память, чтобы больше так не вышло…"},{"kind":"paragraph","text":"«Для хороших друзей — что угодно! Лисензия, сертификат, архивировать, память восстановить…» — как сквозь туман, вспомнил я."},{"kind":"paragraph","text":"Пошатываясь, встал. Посмотрел на друга мутными, опухшими глазами."},{"kind":"paragraph","text":"— Заводи свой драндулет. Едем к мастеру Си."},{"kind":"paragraph","text":"— Тяжёлый, тяжёлый кукьла, — бормотал Си, укладывая Аду на кушетку. Заряд был полным, но он не велел включать её до конца процедуры. — Как чисто всё соскоблено… Можеть получиться, а можеть не получиться…"},{"kind":"paragraph","text":"— Любые деньги, — механически в который раз повторил я."},{"kind":"paragraph","text":"— Двиньтесь, — велел мастер, натягивая на голову ремешок с моноклем и раскладывая по салфетке приборы. — И не лезьте под руку… и не шепчите. Отойдите."},{"kind":"paragraph","text":"— Я… сяду с другой стороны."},{"kind":"paragraph","text":"Ноги не держали: я едва-едва обошёл кушетку и плюхнулся на колени напротив Си. Между нами лежала Аделаида. Мастер поднял ей веки:"},{"kind":"paragraph","text":"— Это чтобы следить за импульсами, — объяснил он, надевая перчатки."},{"kind":"paragraph","text":"У меня мелко тряслось, крутило внутри. Слабость грозила раздавить, распластать как крохотного клопа под белым небом."},{"kind":"paragraph","text":"Я сидел, держа её за руку. По ногам бил мощный сквозняк. Аделаида молча, бесстрастно смотрела в белый потолок."},{"kind":"paragraph","text":"Мастер Си изобразил лицом сложное движение, воздел руки к потолку, словно напоминая, что «можеть получиться, а можеть не получиться». И мягким картавым голосом велел:"},{"kind":"paragraph","text":"— Приступимь."}]'::jsonb,
  '2021-12-30T12:00:00.000Z'
)
