INSERT INTO "Articles" (slug, title, author_id, cover_path, cover_blur, cover_width, cover_height, excerpt, content_blocks, published_at)
VALUES (
  'mrd2-s-poslednimi-luchami-solntsa',
  'С последними лучами солнца',
  (SELECT id FROM "Authors" WHERE name = 'Артём Северский' ORDER BY id LIMIT 1),
  'mrd2/mrd2-s-poslednimi-luchami-solntsa.jpg',
  'data:image/jpeg;base64,',
  1172,
  875,
  'Муж сел в свою грязно-­жёлтую «Газель», которую обычно ставил под окнами.',
  '[{"kind":"image","path":"mrd2/mrd2-s-poslednimi-luchami-solntsa.jpg","caption":null},{"kind":"paragraph","text":"Муж сел в свою грязно-­жёлтую «Газель», которую обычно ставил под окнами."},{"kind":"paragraph","text":"Ольга наблюдала, как машина разворачивается во дворе и медленно катит мимо дремлющих легковушек."},{"kind":"paragraph","text":"Этот ритуал иной раз надолго вводил Ольгу в транс, и она столбенела, глядя в никуда и слушая, как тикают настенные часы за спиной."},{"kind":"paragraph","text":"Вскоре и ей на работу."},{"kind":"paragraph","text":"Над шиферной крышей пятиэтажки выросла туча, и на стекло упало несколько капель. Августовский противный дождь, который Ольга ненавидела всей душой. Вообще, ненавидела каждый дождь, в любое время года, в любой день и час. За компанию с ним в её душу всегда закрадывалось серое отчаяние. Началось это давным-­давно, наверное, десять тысяч жизней назад."},{"kind":"paragraph","text":"Обняв плечи руками, Ольга вздрогнула, заставила тело двигаться, мысленно подбадривала кровь, застоявшуюся в венах: быстрее, ну быстрее!"},{"kind":"paragraph","text":"Взяла со стола посуду — пила только чай, муж ел яичницу с колбасой — и отнесла в раковину. Вымыла всё медленно, тщательно, аккуратно расставила тарелки в сушилке, следя, чтобы ни одна не покосилась. Чашки выстроила столь же чётко в ряд. Ложки и вилки в верхний ящик, вот так. Когда на кухне порядок, гораздо легче переносить окружающее."},{"kind":"paragraph","text":"Собирая крошки со стола, Ольга будто сметала песок, насыпанный на её душу. Песчинки сначала царапали, но позже наступало облегчение."},{"kind":"paragraph","text":"Бросила взгляд на часы. Надо собираться."},{"kind":"paragraph","text":"Тяжело, словно к ногам примотали скотчем гири."},{"kind":"paragraph","text":"Работа её находится в соседнем доме. Пройти по двору, завернуть за угол, мимо магазина, опять повернуть, и вот уже крыльцо цеха по пошиву медицинской одежды. Одноразовые халаты, шапочки, маски, бахилы и прочее. Работа простая — строчи и выполняй план. Чем больше сделал за день, тем больше получишь."},{"kind":"paragraph","text":"«Девчонки у нас вон сколько зашибают, — объяснили Ольге, когда она устраивалась. — Ты молодая, будь шустрой, с такой работой даже мартышка справится»."},{"kind":"paragraph","text":"Ольга — её воспоминание запечатлелось в деталях — сидела на стуле возле стены и тупо взирала на директрису. Милая на вид женщина эта Сутулова, но в глазах есть нечто от паучихи. Тогда Ольга радовалась, что нашла место, где можно заработать, что к ней отнеслись серьёзно и не отмахнулись. С другой стороны, к концу разговора её начало подташнивать. От Сутуловой пахло, словно она не следила за гигиеной. В дальнейшем Ольга старалась близко к ней не подходить. Лучше всего с директрисой оказалось контактировать в курилке — дым заглушал все запахи."},{"kind":"paragraph","text":"Ольга никогда не отличалась хорошим чувством времени. Сколько она уже работает в цехе? Месяца четыре или пять? Может, семь? Мать всегда ругалась. Какой сегодня день, Оля? Не знаю. Какой год? Не знаю. Что ты вообще знаешь? Наградил же бог дочуркой!"},{"kind":"paragraph","text":"В конце концов, разницы нет. Все дни на работе для неё слились в один бесконечный конвейер. Вначале её посадили шить одноразовые хирургические халаты, и она шила, исправно выполняя дневной план. Сверх того получалось неважно, Ольга, сколько ни старалась, не могла осилить и одной трети нормы, следовательно, и заработок не рос. Другие женщины, тоже сидевшие на халатах, строчили как сумасшедшие, делали две, а то и три нормы стабильно, изо дня в день. На неё они посматривали с усмешкой, и Ольга точно знала, что во время перекуров их любимым занятием было перемывать ей косточки — тормоз, неумеха, руки не из того места."},{"kind":"paragraph","text":"Одно время Ольга злилась, искала способ отомстить, одёрнуть, но ничего так и не изобрела. Директриса, которая раньше"},{"kind":"paragraph","text":"верила в её способности, теперь взирала на неё чуть ли не с жалостью. В её глазах читалось: «Ты хуже всех работаешь, милая моя, ты меня разочаровала». Всякий раз, когда Сутулова оказывалась рядом с Ольгиным рабочим местом, та опускала голову, делая вид, что целиком поглощена очередным изделием."},{"kind":"paragraph","text":"Ей никогда не перейти на маски или хирургические шапочки. Их шьют лучшие из лучших. Прострачивая швы, Ольга думала: «Ну и пусть. Это несправедливо. Ну и пусть»."},{"kind":"paragraph","text":"Закрыв квартиру, медленно спускалась по ступеням. Во дворе дождило, мелкие капли щекотали лицо."},{"kind":"paragraph","text":"Едва обогнула угол здания, оставив позади пустой двор, как зазвонил телефон. Ответила. Это была мать со своим хриплым, неприятно дребезжащим голосом. Сообщила, что отец совсем плох и лежит после операции на почках, которая прошла хуже, чем врачи ожидали, и, наверное, скоро умрёт."},{"kind":"paragraph","text":"Ольга стояла, держа возле уха телефон, и смотрела перед собой на безлюдную улицу. Если сейчас пойти вперёд, то ­где-то там, наверное, можно встретить совершенно иную жизнь."},{"kind":"paragraph","text":"Мать прибавила, что Ольгин дед спрашивает, не хотелось ли бы ей сходить проведать отца. В­сё-таки не чужой человек, к тому же, очень страдает."},{"kind":"paragraph","text":"Ольгу тянуло торжественно объявить матери, что она идиотка. Отец бросил их, когда ей только исполнилось пять. Какой родной человек? Все эти годы он был пустым местом, о нём и не говорили никогда, и почему теперь ему становиться частью её жизни?"},{"kind":"paragraph","text":"«Мама, ты действительно в маразме. Или специально причиняешь мне боль», — подумала Ольга, сжимая зубы. Отец пусть лежит и мучается, пусть умрёт со знанием, что ни его бывшая жена, ни дочь не придут даже на похороны. Пусть лежит в вечном холоде. И родственнички с его стороны перестанут наконец давить на её чувство вины, и пусть катятся куда подальше. Они ей безразличны — большую часть времени — но в такие моменты ненависть накрывала Ольгу с головой, как чёрное одеяло."},{"kind":"paragraph","text":"— Я не пойду к нему в больницу. И на похороны, когда он сдохнет, тоже. Я уже говорила тебе миллион раз. Так им и передай. Делайте, что хотите. Мне без разницы."},{"kind":"paragraph","text":"В её детских воспоминаниях отец отсутствовал. Однажды, ещё в старшей школе, она видела у матери в коробке из-под обуви старые фото. Оказалось, Ольга очень похожа на него, практически одно лицо. То самое мерзкое лицо, которое она не выносила, уродливое, с шершавой кожей и тёмными усиками под носом-­ пуговицей. С этим наследием ей приходится жить."},{"kind":"paragraph","text":"Мать вздохнула. Эта манера заканчивать разговор всегда жутко бесила Ольгу, так, что она даже ничего не могла сказать в ответ. Мать словно говорила: «Я всегда знала, что с тобой каши не сваришь»."},{"kind":"paragraph","text":"Ольга посмотрела на экран телефона, отчаянно желая удалить её из контактов и никогда больше не говорить и не встречаться. Пускай живёт как можно дальше от неё во всех смыслах."},{"kind":"paragraph","text":"Швеи курили на крыльце, глядя, как приближается Ольга, полная коротконогая женщина с жидкими волосами, с кислой скуластой физиономией и повадкой школьной тихушницы, что ходит по стенке. Они знали всё, насквозь её видели. Конечно,"},{"kind":"paragraph","text":"она стесняется своего тела, своего роста, своей плохой кожи, вообще странная и неприятная. Слова из неё не вытянешь, с юмором тоже проблемы."},{"kind":"paragraph","text":"— Привет, куда мчишься? — спросила Иванова, курившая возле урны. Две её подруги пристроились по другую сторону асфальтовой дорожки, проложенной к крыльцу. — Рано же."},{"kind":"paragraph","text":"Ольга прошла между ними и шагнула на первую ступеньку. Обернувшись, достала из кармана куртки пачку сигарет. Они курили, смотрели на её движения и улыбались."},{"kind":"paragraph","text":"Не моргнув глазом, Ольга зажгла свою сигарету, убрала пачку."},{"kind":"paragraph","text":"— У тебя вчера куча брака была на проверке, — сказала Иванова. — Ты чего?"},{"kind":"paragraph","text":"— Ничего. Так. У всех брак."},{"kind":"paragraph","text":"— У нас вот не бывает, — «Нас» — это про подружек, что лыбились рядом. Иванова цыкнула."},{"kind":"paragraph","text":"— У всех, — пробормотала Ольга, краснея."},{"kind":"paragraph","text":"— Чего?"},{"kind":"paragraph","text":"— У всех, — громче повторила та."},{"kind":"paragraph","text":"— Работай лучше. Особенная, да? Работай как все."},{"kind":"paragraph","text":"— Работаю."},{"kind":"paragraph","text":"— Я вот тоже с халатов начинала, а уже через неделю перешла на шапочки."},{"kind":"paragraph","text":"Ольга молчала, понимая, что зря остановилась. Они никогда не примут её, никогда не станут говорить с ней как с подругой. Эти девушки моложе, красивее, для них всё легко, они делали то, к чему она была или неспособна, или ей требовалось куда больше времени, чтобы настроиться. Однако ждать никто не любит. Тормозов быстро отсеивают, с тормозами разговор"},{"kind":"paragraph","text":"короткий. Всем плевать на оправдания. Или ты бежишь в группе лидеров, или тебя нет."},{"kind":"paragraph","text":"— Ты же не дура, — сказала Иванова, глядя ей в глаза. — Пойми, ты всему цеху портишь показатели."},{"kind":"paragraph","text":"Ольга покривила рот, это была неудачная усмешка."},{"kind":"paragraph","text":"— Если ты вкалываешь, то вкалывай, — подала голос одна из подружек Ивановой."},{"kind":"paragraph","text":"— Вкалываю, — ответила Ольга, бросив окурок в урну."},{"kind":"paragraph","text":"Под цепкими взглядами швей она повернулась и взобралась по ступеням, открыла серую металлическую дверь, проникла в тамбур, где царил сумрак."},{"kind":"paragraph","text":"Цех оживал, готовясь к работе, и пора было занимать своё место."},{"kind":"paragraph","text":"Оставив вещи в раздевалке, Ольга ушла в туалет, заперлась в кабинке и сидела в ожидании ­чего-то, глядя на сердечко, нарисованное синим маркером на внутренней стороне дверцы. Голова горела, как факел."},{"kind":"paragraph","text":"Десятки промышленных машин гремели так, что дрожали стены. Ольга долго привыкала к этому дикому шуму, но теперь почти не замечала его. Зато выходя после работы на улицу, особенно зимой, она любила слушать оглушительную тишину, которая буквально падала на неё. Точно вся суета мира исчезала в один момент. Даже плакать иной раз хотелось от внезапно нахлынувшего счастья. Глупо, конечно, но это правда."},{"kind":"paragraph","text":"Набрав деталей, Ольга села за машину и принялась автоматически, не думая, прострачивать швы. Её движения были отрабо-"},{"kind":"paragraph","text":"таны, ничего лишнего — свой­ство, похвальное для швеи на массовке. Ещё бы её показатели соответствовали такому профессионализму."},{"kind":"paragraph","text":"Ольга перебирала в уме разговор с девчонками. Им не нравилось, что она мало делает сверх нормы. Претензии предъявляют. Вот уж странно. Директриса если и вздыхала, то воздерживалась от замечаний — формально претензий к Ольге нет, план выполняется. Сверх него — её личное дело. Личное. Дело. Почему они лезут?"},{"kind":"paragraph","text":"Она подняла глаза, высматривая Иванову за её машиной. Удалось заметить только знакомую рыжую макушку под высоко висящей лампой дневного света на другом конце зала."},{"kind":"paragraph","text":"Помассировав глаза, Ольга сосредоточилась на работе."},{"kind":"paragraph","text":"Отыскать спокойствие, настроиться на только ей ведомый ритм. Шагнуть за прозрачную занавеску и пропасть. Ей это удавалось неплохо. Став маленькой лодочкой в реке времени, она приближалась к ­чему-то необычному, ­чему-то, от чего захватывало дух. Странная эта её фантазия, так любовно, тщательно раскрашенная, была иной раз истинным спасением. День проходил за днём, неделя сменяла неделю, месяцы бежали в никуда, не оставляя следов. И где год, где два? Бывало, вспоминая ­какое-то событие, Ольга с удивлением и страхом осознавала, что оно произошло не вчера или на прошлой неделе, нет — минуло пять лет, или даже десять. Как это возможно? Кто имеет право так беззастенчиво воровать её жизнь?"},{"kind":"paragraph","text":"Представляя себя лодочкой, несущейся по бурной реке, Ольга, однако, была уверена в своей безопасности. Нет силы, чтобы перевернуть её и утащить на дно. Она обязательно доберётся"},{"kind":"paragraph","text":"до ­чего-то иного, пусть это и случится нескоро. Однажды всё пропадёт: швейная машина, цех, дом, муж, мать с её претензиями и нытьём, всё — и Ольга пристанет к берегу и, обретя новую плоть, побежит налегке к яркому свету."},{"kind":"paragraph","text":"Посмотрев на готовый халат, она бросила его в корзину к другим. Какой по счёту, она не знала. Очередной брак, пошитый вкривь и вкось."},{"kind":"paragraph","text":"Под конец рабочего дня из своей директорской каморки вышла Сутулова и объявила о том, что из-за сокращения заказов — и это уже точно — им придётся уволить трёх швей. Кого именно, сейчас решает начальство."},{"kind":"paragraph","text":"— Девочки, дело серьёзное, — добавила она, прежде чем уйти."},{"kind":"paragraph","text":"Хотя до конца смены оставалось полчаса, никто не шил, все обсуждали новость. Ворчали, ругали начальство. Иванова удалилась с подружками курить на улицу. Ольга, голова которой снова горела, взяла сигарету и пошла в курилку, и там, стоя у пожарного щита, едва могла высечь огонь из зажигалки."},{"kind":"paragraph","text":"Неподалеку топтались две швеи куда старше неё, пенсионерки. Курили молча, но их мысли были одинаковыми, обращёнными исключительно к ней."},{"kind":"paragraph","text":"«Она первая, — размышляли женщины, — как пить дать уволят»."},{"kind":"paragraph","text":"Ольга дымила, не чувствуя ни губ, ни языка, ни вкуса сигареты. Она ошибалась. Она не просто неслась по реке времени, а приближалась к водопаду. Было ошибкой надеяться на ­что-то."},{"kind":"paragraph","text":"Докурив, Ольга вышла из комнатки в коридор, где столкнулась с Ивановой."},{"kind":"paragraph","text":"— Не дай бог, уволят ­кого-то нормального, — сказала та, грубо напирая, почти прижимая Ольгу к стене. — Не дай бог. Это всё из-за тебя. Всё ты."},{"kind":"paragraph","text":"— Почему? — спросила Ольга, с трудом удерживая зрительный контакт с этой страшной женщиной."},{"kind":"paragraph","text":"— Потому. Ты же убожество. Посмотри на себя!"},{"kind":"paragraph","text":"Иванова улыбнулась во всю ширь. Ольга подбирала слова, очень хотела ­что-то ответить так, чтобы выглядеть достойно. У неё дрожали губы."},{"kind":"paragraph","text":"— Овца, — бросила Иванова и пошла в сторону курилки. За ней потянулся целый шлейф подпевал, и в помещении, где густо висел дым, сразу вспыхнули разговоры и мрачный смех."},{"kind":"paragraph","text":"К­ое-как добравшись до раздевалки, Ольга взяла вещи и выбежала одной из первых на крыльцо, в августовские сумерки."},{"kind":"paragraph","text":"Постояв несколько секунд, спрыгнула со ступеней и пошла вдоль бровки тротуара под низко растущими ветками яблонь. В ушах у неё гудело. Воздух нёс запах листьев, травы и ­почему-то крови."},{"kind":"paragraph","text":"Остановившись там, где соединялись улицы, Ольга посмотрела направо. Если пойти туда — окажешься на трассе, огибающей посёлок и уходящей в неизвестность. Если привычно повернуть налево, то скоро попадёшь домой, вот она стоит, серая пятиэтажка."},{"kind":"paragraph","text":"Ольга достала телефон и проверила, есть ли ­ч то-нибудь новое. Никто ей не звонил и не писал. От мысли, что мать пойдёт к отцу в больницу, сочувствовать ему, жалеть, вспоминать"},{"kind":"paragraph","text":"их общее прошлое, она расплакалась. Мать никогда не позвонит и не придёт, чтобы пожалеть её."},{"kind":"paragraph","text":"Утирая слёзы ладонью, Ольга озиралась по сторонам — может, кто окажется поблизости, — но видела только пустоту. Дома и деревья напоминали картонные декорации. Жили здесь люди хоть ­когда-­нибудь?"},{"kind":"paragraph","text":"Ольга двинулась направо, убыстряя шаг. Ветер налетел на неё, надавил, задул в лицо, разметал жидкие короткие волосы. Но она шла. Мимо кустарников, мимо стоящих торцом к дороге домов, мимо парковки и бани на другой стороне проезжей части, мимо колдобин и трещин в асфальте."},{"kind":"paragraph","text":"Наверное, стоило не ждать, а просто сделать шаг. Взять и пойти. Уже не имеет значения куда."},{"kind":"paragraph","text":"Но улица вела Ольгу всё дальше, пока не бросила у самого края трассы. Мимо неслись легковые машины, автобусы, длинные фуры, невыносимо ревущие лесовозы. Из ниоткуда в никуда был их путь, и они исчезали вдали."},{"kind":"paragraph","text":"Мокрые щёки Ольги холодил ветер. До неё наконец дошло. Она всё поняла."},{"kind":"paragraph","text":"Муж вернулся поздно, вошёл в квартиру, затопал, зазвенел ключами. Не зажигая свет, Ольга встала с кровати, одёрнула покрывало и отправилась на кухню разогреть ему ужин. Муж взглянул на неё жёлтыми глазами, состроил гримасу. Заперся в ванной, стукнув дверью."},{"kind":"paragraph","text":"Ольга включила газ под сковородкой, включила чайник. Стояла возле окна, глядя на двор."},{"kind":"paragraph","text":"Муж пришел на кухню, на ходу вытирая лицо полотенцем. От него пахло чужими людьми, машиной, бензином, грязью улиц, о которых Ольга не имела понятия."},{"kind":"paragraph","text":"Она не спрашивала его, как дела, почти никогда, но он сам охотно начинал говорить, как только усталость немного отступала."},{"kind":"paragraph","text":"Сев напротив и наблюдая за движениями ложки в его руке, Ольга на секунду ощутила себя невесомой, как пылинка в луче солнца. Странное это было чувство, непонятное — и ненужное."},{"kind":"paragraph","text":"Час спустя позвонила мать."},{"kind":"paragraph","text":"— Отец умер сегодня. Я была там. Жаль, что ты не пришла. Да. Совсем был чужой ­какой-то. Как мумия, ты бы видела! Что болезнь делает… Слушай, нам надо пойти на похороны. Надо. Ты как? Пойдёшь? Не передумала?"},{"kind":"paragraph","text":"Муж спал. Ольга сидела в темноте возле окна и слушала."},{"kind":"paragraph","text":"Было так тихо, как ещё никогда на свете."}]'::jsonb,
  '2021-12-30T12:00:00.000Z'
)
