INSERT INTO "Articles" (slug, title, author_id, cover_path, cover_blur, cover_width, cover_height, excerpt, content_blocks, published_at)
VALUES (
  'mrd2-konfety-svety-pshenitsynoy',
  'Конфеты Светы Пшеницыной',
  (SELECT id FROM "Authors" WHERE name = 'Александр Олексюк' ORDER BY id LIMIT 1),
  'mrd2/mrd2-konfety-svety-pshenitsynoy.jpg',
  'data:image/jpeg;base64,',
  1175,
  837,
  'Света Пшеницына была худощавой пятиклассницей с немного мышиным, выступающим вперёд лицом. Каждое утро мама заплетала ей две тугие косы, отчего кожа на голове девочки стягивалась, и Света ещё более походила на мышку. Это',
  '[{"kind":"image","path":"mrd2/mrd2-konfety-svety-pshenitsynoy.jpg","caption":null},{"kind":"paragraph","text":"Света Пшеницына была худощавой пятиклассницей с немного мышиным, выступающим вперёд лицом. Каждое утро мама заплетала ей две тугие косы, отчего кожа на голове девочки стягивалась, и Света ещё более походила на мышку. Это было маленькое, бледное существо с синими прожилками вен на висках."},{"kind":"paragraph","text":"Свету не любили в классе, к ней относились как к тени, как к блёклому растению на подоконнике в кабинете физики: не то алоэ, не то каланхоэ — ­что-то неважное и пустое, Акакий Акакиевич с двумя крысиными хвостиками. Особых успехов в учёбе она не делала, ни с кем близко не общалась, ходила в чистых, но вытянутых от постоянных стирок блузках и старомодных, доставшихся от старшей сестры платьях. Света родилась в многодетной, бедной семье, и одноклассники ей этого не простили."},{"kind":"paragraph","text":"Школьники девяностых быстрее родителей усвоили законы нового мира с его жаждой обогащения и наживы, отчего искренне считали бедность пороком, хотя и сами могли ходить в порванных туфлях. Однако если дырявая подошва на штиблетах Пети или Марины иной раз мимикрировала под ухарство и разгильдяйство, то полинявшие юбки Светы кричали о нищете. Бедность Пшеницыной слишком сильно бросалась в глаза, а девочка не хотела или не умела её скрывать."},{"kind":"paragraph","text":"На одном из уроков русского языка класс писал контрольную работу. Учительница, сгорбившись, сидела за столом и проверяла сочинения. Тема: «Самый лучший день в моей жизни»."},{"kind":"paragraph","text":"Наследие Пушкина и Толстого в пятый «Б», как румяный блин на лопате, заносила Галина Петровна — усталая женщина средних лет. На уроки она приходила в модном по тем временам пиджаке зелёного цвета с вшитыми в плечи поролоновыми подплечниками. Из-за этого учительница напоминала штангиста и вызывала смутные ассоциации с папой Влада Колунова, который «держал рынок» и щеголял в таком же, только малиновом, пиджаке."},{"kind":"paragraph","text":"— Черт-те что понаписали, — прорезал тишину немного хриплый голос Галины Петровны. — Пшеницына!"},{"kind":"paragraph","text":"Света вздрогнула и испуганно посмотрела на учительницу."},{"kind":"paragraph","text":"— Ну, что это такое? Ну, подумаешь, ну сходила, поела, разве ж это лучший день в твоей жизни? — с недоумением спросила педагог. Уже давно она воспринимала детей, как некую однородную пёструю массу — липкий навозный шарик, который она, подобно жуку-скарабею, должна толкать в направлении последнего звонка и выпускных экзаменов. Разумеется, с таким"},{"kind":"paragraph","text":"отношением ни о какой деликатности не могло быть и речи, к тому же о финансовых проблемах Пшеницыных учительница, скорее всего, не догадывалась, своих хватало."},{"kind":"paragraph","text":"— Там же не только про это. Там как с папой в телескоп смотрели ещё было, — тихо, едва живая, ответила Света, но её уже никто не слушал. Класс утопал в хохоте. Школьники быстро соотнесли «лучший день в жизни Светы Пшеницыной» с её выпуклой, голодной нуждой и стали надрываться от смеха."},{"kind":"paragraph","text":"Вообще, они часто над ней смеялись: называли девочку «Светаинфекция». Почему именно «инфекция», сказать затруднительно. Скорее всего, логической причины здесь не было, просто в такое определение трансформировался образ худой школьницы в заштопанных колготках. Советский психотерапевт Владимир Леви описывал похожий случай. Дети заметили, что папа одного из одноклассников постоянно ходит с пузатым туристическим рюкзаком. «Твой папа, что — бард?» — спросил ­кто-то из детей. «Ну да, бард. А ещё турист», — ответил ребёнок. На основании отцовского хобби мальчика стали называть Килиманджаро: всё ж, папа — турист, походник. Альпинист, стало быть. А значит, пусть будет Килиманджаро. Но «Килиманджаро» — слишком сложное и длинное слово, поэтому вскоре оно трансформировалось в «Кильку». Для взрослого человека это странная и нелогичная история, при чём тут килька? С другой стороны, какая разница, если школьники затравили одноклассника этой «килькой» до умопомешательства."},{"kind":"paragraph","text":"До полного исступления Свете было ещё далеко, она привыкла к насмешкам, и когда такое случалось, немного втягивала голову в плечи, подобно боксёру. Однако вместо того, чтобы стремительно атаковать обидчиков, замирала в этой нелепой позе, как гипсовая статуэтка. Когда девочка проходила мимо старой"},{"kind":"paragraph","text":"технички бабы Вали, та цокала языком и называла её «крошечкой-­ хаврошечкой»."},{"kind":"paragraph","text":"У Пшеницыной имелась старшая сестра Лена, уехавшая в другой город, а также трое маленьких братьев. Младший — Саша — учился в первом классе этой же школы. И всю осень до первых холодов проходил в лыжных ботинках, других не было. В семьвосемь лет дети ещё не понимали, что к чему, и необычные ботинки даже произвели некоторый фурор среди одноклассников. В десять-­двенадцать такое уже не пройдёт."},{"kind":"paragraph","text":"Мама Светы — рано постаревшая, ­когда-то красивая женщина с вечно слезящимися печальными глазами — трудилась уборщицей в ЖЭКе, говорила тихим голосом и почти никогда не улыбалась. Тяжёлая, кособокая судьба сделала её похожей на реквизит из подсобного помещения — тёмно-­синий халат, дополнение к железной «лентяйке» и пара рук, выжимающих тряпку и заплетающих косы на маленькой крысиной головке."},{"kind":"paragraph","text":"Считается, что в бедах Пшеницыных был виновен глава семейства, алкоголик дядя Игорь. Массово разводиться с пьяницами женщины начнут чуть позже, в начале нулевых, а в девяностые ещё ­почему-то терпели их. И постепенно привыкая к солёному вкусу слёз, жили в аду."},{"kind":"paragraph","text":"Дядя Игорь ­когда-то работал в этой же школе учителем физики и астрономии. С конца восьмидесятых он начал регулярно пить. В этом ему помогали татарин-­трудовик Марат Радикович и школьный баянист, работавший учителем физкультуры и музыки одновременно. Игорь Викторович приходил на уроки пьяным, ­зачем-то рассказывал детям, как собирать и есть мухоморы, выпивал со старшеклассниками в туалете и наконец был с позором уволен."},{"kind":"paragraph","text":"«Пшеницына, у тебя папка на углу валяется. Поди забери», — иногда говорили Свете одноклассники, и девочка, краснея от стыда как свёкла, бежала прочь. Она любила отца. В редкие дни, когда Игорь трезвел, он доставал с верхней полки хромого шифоньера телескоп, который по ­какой-то иррациональной причине не пропивал, и вместе с дочкой забирался на крышу, где показывал ей лунные кратеры и созвездия."},{"kind":"paragraph","text":"В четверг в расписании пятого «Б» друг за другом шли два урока у Галины Петровны. Сначала русский язык, а потом литература. В тот день Света не стала уходить на перемену — обычно положенные десять минут отдыха она стояла у окошка и о ­чём-то мечтала. Вместо этого девочка достала из рюкзака большой полиэтиленовый пакет и стала ходить по рядам, аккуратно раскладывая у каждого места по пухлому прянику и по две конфеты: шоколадной «Каракум» и сосательной — «Барбарис». Когда прозвенел звонок, толпа детей ворвалась в кабинет. Школьники расселись."},{"kind":"paragraph","text":"— А откуда конфеты и пряники? — спросила Марина Овчинникова."},{"kind":"paragraph","text":"— Это Пшеницына разложила, — ответила Инна Мулаева. Она видела, как девочка раскладывала угощения по партам."},{"kind":"paragraph","text":"— Света, у тебя что, день рождения? — раздался хриплый голос Галины Петровны. В своём огромном пиджаке учительница возвышалась над классом и казалась изумрудной горой, раскинувшейся под лучами «солнца русской поэзии»."},{"kind":"paragraph","text":"— Помяните папу, — тихо ответила Света."},{"kind":"paragraph","text":"— Что? — не расслышала учительница."},{"kind":"paragraph","text":"— Помяните папу, — чуть громче сказала бледная Света. Прошлой ночью Игорь Викторович не проснулся. Сердце любителя астрономии не выдержало очередного запоя."},{"kind":"paragraph","text":"В классе стало тихо-тихо. Дети, привыкшие смеяться над Светой-­ инфекцией, стоило ей сказать хоть ­какое-­нибудь слово, внезапно замерли. Поминальные пряники и конфеты оказались заговорёнными: ехидство растворилось, острые языки размякли, никто не знал, что сказать. Для всего класса Света предстала ещё более блёклой и бледной, однако из разряда каланхоэ она в одночасье перешла в категорию человека. Ведь, оказывается, у неё тоже есть папа. Пьяница, который тонул в луже у «наливайки». А потом его мокрого везли в вытрезвитель."},{"kind":"paragraph","text":"— Что ­делать-то надо? — нарушил тишину Влад Колунов."},{"kind":"paragraph","text":"— Ну, просто берёшь пряник и ешь, — ответила отличница Катя."},{"kind":"paragraph","text":"— Надо подумать ­что-то хорошее о человеке или сказать ­что-нибудь хорошее, — добавила Марина."},{"kind":"paragraph","text":"— Хорошее…— задумчиво произнесла Галина Петровна. — О любом человеке можно сказать ­что-то хорошее. Давайте ешьте, помяните папу Пшеницыной и открывайте рабочие тетради."},{"kind":"paragraph","text":"Дети активно зажевали, а Света неподвижно сидела за партой и не отрываясь смотрела ­куда-то поверх голов одноклассников. Из окна на неё падал весенний свет, такой яркий, что казалось, он вот-вот зажжёт застиранную блузку и два крысиных хвостика на белой маленькой голове."}]'::jsonb,
  '2021-12-30T12:00:00.000Z'
)
