INSERT INTO "Articles" (slug, title, author_id, cover_path, cover_blur, cover_width, cover_height, excerpt, content_blocks, published_at)
VALUES (
  'mrd2-tsylya',
  'Цыля',
  (SELECT id FROM "Authors" WHERE name = 'Олег Золотарь' ORDER BY id LIMIT 1),
  'mrd2/mrd2-tsylya.jpg',
  'data:image/jpeg;base64,',
  1200,
  663,
  'Водитель Иван Цылин сдал дежурному автоколонны ключи от своего ЗИЛа, небрежно расписался в журнале, выскочил из диспетчерской и быстрым шагом направился в сторону гардероба, старательно избегая встреч с коллегами при пом',
  '[{"kind":"image","path":"mrd2/mrd2-tsylya.jpg","caption":null},{"kind":"paragraph","text":"Водитель Иван Цылин сдал дежурному автоколонны ключи от своего ЗИЛа, небрежно расписался в журнале, выскочил из диспетчерской и быстрым шагом направился в сторону гардероба, старательно избегая встреч с коллегами при помощи одичалых клумб и брошенных полуприцепов."},{"kind":"paragraph","text":"Многие водители тоже успели вернуться из рейсов и теперь устало суетились возле своих автомобилей: протирали лобовые стёкла, осматривали днища, перебрасывались фразами друг с другом или прямо со своими многотонными товарищами."},{"kind":"paragraph","text":"Цылина не удивляло подобное отношение людей к автомобилям. И хотя свой потрёпанный ЗИЛ он бросил, едва заглушив мотор, как опытный водитель он прекрасно понимал и разделял чувства своих коллег."},{"kind":"paragraph","text":"Все эти ЗИЛы, МАЗы, КраЗы могли выглядеть бездушными железяками только с самого утра, до первого поворота ключа"},{"kind":"paragraph","text":"зажигания. А вот после, с каждым намотанным километром, эмоциональный расклад окружающего мира претерпевал ощутимые изменения. Возможно, свою роль в этом играла пыль, которая не признавала разницы между одушевлёнными и неодушевлёнными объектами и покрывала их с одинаковым безразличием. Возможно, дело было в усталом воображении самих людей, стремившихся вложить в окружающий мир чуть больше одухотворённости, чем тот обычно демонстрировал сам. Но, так или иначе, к концу дня все эти железяки обретали индивидуальность и даже умудрялись перенимать отдельные черты своих водителей, вследствие чего между людьми и машинами возникала эта странная, почти сентиментальная связь."},{"kind":"paragraph","text":"Цылин бежал от своего автомобиля и коллег вовсе не потому, что ему надоели бесконечные нелитературные вариации насчёт сорванных сцеплений, спущенных баллонов и лживого целомудрия дорожных инспекторов. На самом деле он был совсем не против почесать язык подобными темами. Но в последнее время, едва отмотав положенные километры просёлочных дорог, Цылин вынужден был спешить к месту своего дополнительного заработка. Заработка, который выносил фундаментальные вопросы одушевлённости на принципиально иной уровень и требовал от Цылина напряжения всех его сил."},{"kind":"paragraph","text":"Часть этих сил приходилось расходовать на то, чтобы не быть привычным для всех Иваном Цылиным — словоохотливым и общительным водилой, душой любой компании (даже если одушевлённым в этой компании оказывался только он сам). Другую — чтобы стоически переносить насмешки со стороны коллег, которые упорно не желали соблюдать дистанцию в своих мнениях относительно моральной стороны приработка Цылина."},{"kind":"paragraph","text":"Эта сторона и вправду была крайне неоднозначной, и сам Цылин это прекрасно понимал."},{"kind":"paragraph","text":"Но других возможностей заработать денег у них на селе не было, а окружающий мир продолжал напоминать о своей малоодушевлённости невыплаченным кредитом за выкуп совхозного дома, недостроенным сараем и столичной учёбой дочерей, которая хоть и подразумевала под собой их дальнейшие жизненные перспективы, но пока оборачивалась лишь ежемесячными денежными взносами, обеспечить которые при помощи неспешных бесед со своим ЗИЛом Цылин не мог, как бы ему этого ни хотелось."},{"kind":"paragraph","text":"Поэтому, в очередной раз переключив внимание с моральных переживаний на циферблат своих часов, Цылин только прибавил шагу."},{"kind":"paragraph","text":"В гардеробе, кроме водителей Василия Коробейникова, Лёхи Марокантова и Целлофена Макаровича Чинзе (самого уважаемого и опытного сотрудника их автобазы), пока никого не было. А значит, в душ Цылин, как и рассчитывал, проходил в первых рядах."},{"kind":"paragraph","text":"— Привет, Иван! — с насмешливой ухмылкой поприветствовал Цылина Василий Коробейников. — Ч­то-то ты сегодня особенно рано!"},{"kind":"paragraph","text":"— А чему тут удивляться? — тут же съязвил Марокантов, презрительно покосившись в сторону Цылина. — Не терпится человеку за государственные банкноты задницу частную лизать!"},{"kind":"paragraph","text":"Если подколку Коробейникова Цылин вполне мог бы проигнорировать (в сущности, Васька был хорошим мужиком, хоть и не умел противостоять сквознякам общественного мнения), то выпад Марокантова оставить без внимания было невоз-"},{"kind":"paragraph","text":"можно. Пару лет им пришлось работать напарниками, и Иван до сих пор не мог простить Марокантову привычку пропивать запчасти с их общего ЗИЛа."},{"kind":"paragraph","text":"— Жопе слова не давали! — энергично огрызнулся Цылин, снимая комбинезон и стараясь не смотреть в сторону своего обидчика."},{"kind":"paragraph","text":"Он давно понял, что на любые насмешки коллег лучше всего реагировать ёмкими и короткими фразами, не предполагающими под собой протяжённой диалектической перспективы. Но с Марокантовым это срабатывало далеко не всегда. Внутренняя диалектика этого человека слабо сочеталась со здравым смыслом и не упускала случая агрессивно проявляться вовне в виде банального мордобоя."},{"kind":"paragraph","text":"Вот и сейчас лицо Марокантова мгновенно побагровело, кулаки сжались, а ноги демонстративно сделали несколько решительных шагов в направлении Ивана."},{"kind":"paragraph","text":"В самый последний момент в ситуацию вмешался многоопытный Целлофен Чинзе, седые брови которого показались над дверцей шкафчика."},{"kind":"paragraph","text":"— Захлопнись, Лёха! — хриплым басом одёрнул он Марокантова. — Ваньку не тронь! И впредь не смей! Сейчас всякий вертится, как только может. А Ванька, он для семьи старается! Это дело святое, всякое неудобство извиняющее. Это тебе, Лёха, лишь бы на пропой."},{"kind":"paragraph","text":"— Макарыч, ты вообще слыхал, что эта шавка протявкала? — попытался оправдать точку зрения своих кулаков Марокантов, но снова был оборван на полуслове опытным ветераном."},{"kind":"paragraph","text":"— Помалкивай, Лёха, помалкивай! Сам живи, как знаешь, а других не тронь! И ты, Иван, тоже не торопись жопами каж-"},{"kind":"paragraph","text":"дого несогласного с твоей жизнью называть! Оправдываться тебе не за что, а значит, и внимания обращать на всяких свистунов нужды нет. Работать везде по спокойствию нужно. Уж кем работаешь — тем и трудись! Главное, чтобы польза от этого была. Тебе ли, другим — разницы нет. Кстати, если там место какое освободится, ты мне словечком обмолвись. Годы у меня уже не те за баранкой сидеть, а заработок не помешает. Тоже ведь семья будь здоров."},{"kind":"paragraph","text":"— Макарыч, и ты туда же? — не веря своим ушам, спросил Марокантов."},{"kind":"paragraph","text":"— А что? — невозмутимо ответил Целлофен. — Я за свою жизнь знаешь сколько дерьма перевозил?"},{"kind":"paragraph","text":"Любой спор или разговор, который Целлофен завершал этой фразой (а ей он завершал каждый без исключения спор или диалог), сразу же приобретал в глазах коллег многотонный вес истины, поколебать которую мог только человек, в масштабах своей трудовой книжки не уступавший Целлофену. Но раз уж таковых на автобазе не осталось, мнение этого угрюмого водилы, проработавшего всю жизнь на свинокомплексе и действительно перевозившего за свой век слабо вообразимый среднестатистическим человеком тоннаж нечистот, враз охлаждало пыл любого оппонента, невзирая на должность, размер кулаков или модель внутренней диалектики."},{"kind":"paragraph","text":"Целлофена уважали железно, и Цылину было приятно ощутить поддержку этого сурового, несгибаемого человека."},{"kind":"paragraph","text":"Приняв душ и переодевшись, он бодро вышел с территории автобазы и направился вниз по улочке, насвистывая ­какую-то навязчивую мелодию, напоминавшую не то скрип заднего моста его ЗИЛа, не то одну из патриотических песен советского кинематографа."},{"kind":"paragraph","text":"Место, где он подрабатывал, находилось от автобазы минутах в двадцати ходьбы, и теперь Цылин мог не волноваться на счёт опоздания. Настроение его ощутимо улучшилось. Сейчас было важно сконцентрироваться на этом настроении и постараться не думать об очередном дне, проведённом вне дома, и о дочерях, которые обещали в скором времени приехать погостить и которых Цылин в очередной раз рисковал не увидеть."},{"kind":"paragraph","text":"По договорённости со своим работодателем Цылин отдыхал лишь один день в неделю. Всё остальное время он вынужден был разрываться между агрессивными мнениями коллег и ненавистными обязанностями, к выполнению которых вот-вот должен приступить."},{"kind":"paragraph","text":"«Чтобы жить по-человечески, нужно не всегда оставаться человеком!» — попытался подбодрить себя Цылин, подходя к трёхэтажному особняку Вацлава Михлюка, «хозяина», как называли его все в округе, трудовые отношения с которым сам Цылин временами расценивал как редкую удачу, а иногда считал худшим проклятием своей жизни."},{"kind":"paragraph","text":"Вацлав Михлюк был местным уроженцем, и многие жители посёлка помнили его ещё босоногим мальчуганом — скрытным, злопамятным, склонным к воровству. Сам Цылин, уступавший Вацлаву двумя годами возраста, в школьной столовой не раз становился объектом его атак — жестоких, напористых и, по своему существу, крайне мелочных (Вацлав имел обыкновение отбирать у младших детей еду и компот)."},{"kind":"paragraph","text":"Матери Вацлав лишился ещё в младенческом возрасте (она была жива, но жива ­где-то совсем в другом месте, подальше от сельских трудов и забот), а его отец, Игнатий Михлюк,"},{"kind":"paragraph","text":"всю жизнь проработал трактористом в местном совхозе, ничем не выделяясь в трудовых показателях, но зато сильно выделяясь своей тягой к спиртному."},{"kind":"paragraph","text":"Своего сына Игнатий воспитал в духе наглядного наплевательства, что, вероятно, и предопределило хищный характер юного Вацлава. Сам Вацлав с лихвой отдал должное воспитательным методам отца и, едва повзрослев, уехал в город, после чего на долгие годы забыл об отчем доме и его одиноком спивающемся обитателе."},{"kind":"paragraph","text":"И хотя жители посёлка не так уж сильно горевали по поводу отъезда Вацлава, временами они всё же позволяли себе глубокие и тяжёлые вздохи о его очевидной судьбе, которая, по их твёрдому убеждению, должна была закончиться ­где-нибудь под забором."},{"kind":"paragraph","text":"Только вот у судьбы насчёт Вацлава планы оказались совершенно иные."},{"kind":"paragraph","text":"И вот теперь Цылин, в школьные годы люто презиравший Вацлава за его тупость и немытость, неуверенно подходил к трёхэтажному особняку, обнесённому добротным забором, возле которого в последние дни стали появляться штабеля силикатного кирпича и прочих стройматериалов. Судя по всему, Вацлав снова планировал ­что-то сооружать на своём участке, и размах подготовительных работ говорил, что речь шла о ­чём-то внушительном. Например, о второй бане или гостевом домике."},{"kind":"paragraph","text":"Денег у Вацлава было много, и он легко позволял себе сомнительные траты, принося жертвы божествам своей судьбы, продолжавшей с фанатичным упорством благоволить ему — владельцу компании по производству картофельных чипсов, хозяину сети пивных магазинов и соучредителю нескольких столичных рынков."},{"kind":"paragraph","text":"То, что с возрастом Вацлав неожиданно решил перебраться обратно в деревню, на первых порах вызвало немалое удивление окружающих, но в своём намерении Вацлав оказался неожиданно твёрд. Старательно сравняв с землёй избу батьки-­тракториста и отгрохав на её месте упомянутый особняк, он частично доверил управление своими заводами и офисами голодным городским родственникам своей супруги, после чего вплотную принялся за воплощение своей мечты о спокойной сельской жизни."},{"kind":"paragraph","text":"«С годами понимаешь, что всё, что тебе нужно — это свой домик в деревне и небольшое хозяйство. Так, для души», — говорил он односельчанам, которые, не привыкнув к подобным масштабам жизненного благополучия, далеко не сразу научились испытывать зависть к этому некогда грязному и нелепому человеку."},{"kind":"paragraph","text":"И хотя со временем зависть всё же заняла в их сердцах привычное место, возможность получать деньги благодаря необузданным порывам Вацлава заставляла многих, подобно Цылину, переступать через свои небогатые убеждения и искать подработку у этого местного олигарха."},{"kind":"paragraph","text":"Отворив массивную калитку, Цылин зашёл во двор и осмотрелся. Оба хозяйских автомобиля были на месте, значит, всё семейство Михлюков пребывало сегодня дома. Несмотря на то, что так оно было практически каждый день (Вацлав уезжал на ­какие-то советы директоров максимум два раза в неделю), Цылин всегда надеялся, что свои обязанности ему придётся выполнять без надзора со стороны хозяев."},{"kind":"paragraph","text":"В любом случае выбора у Цылина не было. Следовало приниматься за работу."},{"kind":"paragraph","text":"Выключив звук на мобильном и положив пакет с личными вещами у забора, Цылин расстегнул верхние пуговицы рубахи, поднял с земли красивый кожаный ошейник и отработанным движением застегнул его на своей шее."},{"kind":"paragraph","text":"Теперь Цыле, по идее, следовало подать голос, поставив хозяев в известность, что он в оговорённое время приступил к исполнению своих обязанностей. Но делать этого Цыля не стал."},{"kind":"paragraph","text":"Вместе со щелчком ошейника та лёгкость, которая сопровождала его всю дорогу от автобазы, из него стремительно исчезла: в отличие от Цыли, сидеть на цепи она не собиралась."},{"kind":"paragraph","text":"Цыле и вовсе захотелось забраться в будку и провести в ней остаток вечера. Но пока, пользуясь тем, что хозяев во дворе по-прежнему не наблюдалось, он решил перекурить."},{"kind":"paragraph","text":"Сам Вацлав к курению Цыли относился совершенно спокойно и часто составлял ему компанию, но вот супруга Вацлава Марианна, склочная и подёрнутая беззаботным алкоголизмом натура, очень не любила, когда Цыля курил на виду, и каждый раз требовала от Вацлава лишить Цылю премии."},{"kind":"paragraph","text":"Покурить «по-человечески» Цыле не удалось и сегодня — стоило ему несколько раз затянуться помятой папиросой, как дверь веранды скрипнула, и во двор выпорхнула Лиза, восьмилетняя дочь Вацлава. Сам хозяин вместе с супругой Марианной показался в дверном проёме следом, изрядно помятый и сонный."},{"kind":"paragraph","text":"Кажется, супруги только что очнулись после своего традиционного дневного сна (традиционного в той же степени, что и утренние возлияния) и решили развеяться привычным вечерним бездельем."},{"kind":"paragraph","text":"— О! Цыля пришёл! — радостно залепетала девочка и бросилась к Цыле, едва успевшему выбросить окурок за забор. — Цыля! Цыля! Цыля!"},{"kind":"paragraph","text":"— Лиза! — тут же раздался строгий голос Марианны. — Опять к собаке лезешь? Вацлав, ну скажи ей!"},{"kind":"paragraph","text":"— Да пусть поиграется. Что ей Цыля сделает? — сонно ответил Вацлав, почёсывая живот."},{"kind":"paragraph","text":"— Ну, вот и не говори потом, что я не предупреждала! — нервно ответила супруга, после чего направилась ­куда-то в сторону сада."},{"kind":"paragraph","text":"Проводив супругу безразличным взглядом, Вацлав спустился с веранды, подошёл к Цыле и пожал ему руку."},{"kind":"paragraph","text":"— Привет! — сказал Вацлав. — Давно тут?"},{"kind":"paragraph","text":"— Только пришёл. К пяти, как и договаривались."},{"kind":"paragraph","text":"— Ну да… Сигарета есть? А то домой возвращаться неохота."},{"kind":"paragraph","text":"Цыля достал пачку и протянул Вацлаву, выудив заодно сигарету и для себя."},{"kind":"paragraph","text":"Лиза тем временем продолжала дёргать Цылю за штанины и громко посвящать его в весёлую рутину своего очередного беззаботного дня."},{"kind":"paragraph","text":"— А я сегодня в школу не пошла. Мама и папа сказали, что сегодня не нужно, потому что отвезти некому. Поэтому я утром в бассейне купалась, даже несмотря на то, что сегодня холодно. Мама сначала не разрешала, а папа разрешил. Сказал, что раньше дети всё время босиком бегали и в дождь, и в снег, потому и здоровыми были. А если бы ты к нам прямо с утра пришёл, мы бы вместе купались. Правда, папа?"},{"kind":"paragraph","text":"— Лиза, брысь! Слышала, что мама сказала? — грозным тоном осёк дочь Вацлав. — В самом деле, оставь Цылю в покое! Иди займись ч­ ем-нибудь!"},{"kind":"paragraph","text":"— А чем?"},{"kind":"paragraph","text":"— В песочнице поиграй! — предложил дочурке Вацлав."},{"kind":"paragraph","text":"— Не хочу!"},{"kind":"paragraph","text":"— В сад сходи, свинкам яблочек принеси!"},{"kind":"paragraph","text":"Лиза на секунду задумалась, но идея отца ­всё-таки пришлась ей по вкусу."},{"kind":"paragraph","text":"— А в лукошко насобирать или прямо в руках принести? — спросила она."},{"kind":"paragraph","text":"— Можешь и так. Мать свиней сегодня уже кормила, они не голодные будут, — ответил Вацлав, прикуривая. — Фух! Ну и денёк!"},{"kind":"paragraph","text":"По помятому виду хозяина было несложно определить, что денёк этот был совершенно такой, как и все остальные — наполненный коньяком и планами, отдающими смелым самодурством."},{"kind":"paragraph","text":"— Трудности? — из вежливости поинтересовался Цыля. — Да утром со строителями разговаривал… Ну и люди! — махнул рукой Вацлав. — Цену загнули? — Да не в цене дело. Видел стройматериалы?"},{"kind":"paragraph","text":"Цыля кивнул."},{"kind":"paragraph","text":"— Решил я свинарник нормальный построить. Ну, раз держу свиней не для прокорма, а так, для души. В этом им тесно, — Вацлав кивнул на небольшой деревянный сарай с загоном, который стоял в шагах двадцати от будки Цыли и представлял"},{"kind":"paragraph","text":"из себя то немногое, что досталось Вацлаву в наследство от отца. — Да и старый он, ненадёжный. Помнишь, как у нас в детстве было: если свинарник, значит обязательно покосившийся, заплывший говном и соломой? Вот я и решил, что нужно всё организовать по-другому, как в лучших, передовых хозяйствах. И нанял не абы кого — профессионалов, из города. И знаешь что? Проект, говорят, составлять надо. Мол, если постройка с коммуникациями, — расшибись, но надо! Да я и не против, но какой же это тогда сарай? Придётся, видно, местных подрядить. Эти моментом построят… Ну а потом коньяку жахнул. Нервы, нервы…"},{"kind":"paragraph","text":"Лиза вернулась из сада, неся в подоле своего пёстрого платья яблоки, и принялась звать своим звонким голоском обитателей сарая:"},{"kind":"paragraph","text":"— Свинки! Кушать! Свинки! Кушать!"},{"kind":"paragraph","text":"Через минуту на призыв ребёнка из низкой двери показалась первая свинья. Это был Мишка Пупылёнок, грузный бобыль лет сорока пяти, поношенная милицейская рубаха которого раньше часто мелькала на просторах посёлка. Милиционером Мишка на самом деле никогда не был — рубаха досталась ему в качестве гуманитарной помощи от ­кого-то из жителей села. Работать Мишка сильно не любил и до того, как попасть к Вацлаву, предпочитал перебиваться мелочным соседским прихлебательством и пенсией своей старушки-­матери."},{"kind":"paragraph","text":"Мишка был первым, кто появился в хозяйстве Вацлава, и в силу этого всегда имел ­какой-то особенно гордый вид, предпочитая всё делать молча и не торопясь. Вот и сейчас, едва махнув рукой в знак приветствия Цыле, он взял яблоко у Лизы и, опершись локтями на изгородь, принялся неспешно жевать."},{"kind":"paragraph","text":"Следом из сарая показались ещё две свиньи — некогда работавшие на колхозной ферме Витька Шишев и Гарик Пацук, с позором оттуда уволенные по причине алкоголизма и сопутствующего ему воровства. С ними Цыля близко знаком не был, но даже с первого взгляда на них можно было с уверенностью сказать, что с выполнением своих обязанностей они справляются более чем убедительно. Взяв у Лизы по яблоку, они громко принялись их есть: скорее для того, чтобы позабавить ребёнка, нежели от голода."},{"kind":"paragraph","text":"— А ещё свиней заводить не планируешь? — поинтересовался Цыля у Вацлава, вспомнив просьбу Целлофена. — Ну, когда сарай новый построишь?"},{"kind":"paragraph","text":"— А хрен его знает. Как по мне, так больше и не надо. В мясе не нуждаюсь, сам понимаешь. А так, для души, троих, наверное, и достаточно. А что?"},{"kind":"paragraph","text":"— На работе кое-кто из коллег интересуется. Отличный мужик! О свиньях знает больше, чем любой другой — всю жизнь водителем на свиноферме."},{"kind":"paragraph","text":"На Вацлава жизненные достижения Целлофена особого впечатления не произвели."},{"kind":"paragraph","text":"— Ну, не знаю. Надо с Марианной поговорить. Слушай, а ты, кстати, есть не хочешь? — вдруг подхватился Вацлав. — Ты ж после работы. Сейчас принесу!"},{"kind":"paragraph","text":"— Да не особо, — махнул рукой Цыля."},{"kind":"paragraph","text":"— Да ты не волнуйся, я тебе из холодильника принесу. Со стола только свиньям скармливаю — они не брезгуют. А тебе свежего нарежу. Колбаса, сало. И ещё кое-что, — многозначительно подмигнув, сказал Вацлав."},{"kind":"paragraph","text":"Цыля знал, что Вацлава отговаривать бесполезно, и поэтому молча кивнул головой в знак неизбежного согласия."},{"kind":"paragraph","text":"Вообще, нужно было признать, что в своём самодурственном благополучии Вацлав был человеком весьма щедрым. Помимо оплаты, он всегда кормил всех обитателей своего хозяйства, а иногда и вовсе мог порадовать их ­чем-то более притягательным для сельского обывателя."},{"kind":"paragraph","text":"Вот и сейчас Вацлав выскочил из дома, неся в руках внушительных размеров миску с разного рода едой и две полуторалитровые бутылки пива, одна из которых предназначалась для самого хозяина, а другая, вне всяких сомнений, для Цыли."},{"kind":"paragraph","text":"Сам Вацлав поглощал пиво в объёмах, сравнимых с производительностью небольшого, но прогрессивно развивающегося предприятия, оправдывая подобные возлияния тем, что, будучи владельцем сети пивных магазинов, он лично несёт ответственность за качество товара."},{"kind":"paragraph","text":"И хотя Цыля в целом был человеком непьющим, пропустить пивка после тяжёлого трудового дня он также не возражал. Тем более, что Марианны поблизости по-прежнему видно не было."},{"kind":"paragraph","text":"Свиньи, заметив похмельный энтузиазм хозяина, быстро дожевали яблоки и с нескрываемым любопытством устремили свои взгляды на Вацлава, но сегодня хозяин явно намеревался провести вечер со своим псом. С перепоя за ним это водилось, и Цыля (к своему стыду) иногда даже испытывал по этому поводу ­что-то вроде гордости."},{"kind":"paragraph","text":"— Фух, — выдохнул хозяин, разом осушив половину бутылки. — Не идёт пиво с перепоя, представляешь? Раньше только им и спасался, а теперь…"},{"kind":"paragraph","text":"— Мама, мама! А папа опять Цылю пивом поит! — тут же раздался звонкий возглас дочурки Вацлава, которой уже"},{"kind":"paragraph","text":"наскучили свиньи и которая вновь активно не знала, чем себя занять."},{"kind":"paragraph","text":"— Ты опять за своё?! — отозвалась Марианна, которая как раз возвращалась из сада. — Всё не угомонишься?! То свиней напоит, то собаку. И так толком не лает, а как пива напьётся — дрыхнуть всю ночь будет. Заходи, бери что хочешь! За что, спрашивается, мы ему деньги платим?!"},{"kind":"paragraph","text":"— Много ты понимаешь! — сонно огрызнулся Вацлав. — Цыля своё дело знает! Правда, Цыля? Вор не пройдёт!"},{"kind":"paragraph","text":"— Только если этот вор храпа боится, — продолжала кричать Марианна, отмахиваясь лопухом не то от комаров, не то от своего раздражения. — Ты вообще на себя посмотри, задумайся — сидишь, с собакой разговариваешь!"},{"kind":"paragraph","text":"— Да с ним, в отличие от тебя, хоть по-человечески поговорить можно! — криво улыбнулся Вацлав, весело подмигнув Цыле."},{"kind":"paragraph","text":"— Лучше бы кур наших поискал!"},{"kind":"paragraph","text":"— А что с ними?"},{"kind":"paragraph","text":"— Отравились, видать, ­чем-то. Трое в саду под кустами лежат, стонут. Я им цып-цып-цып, а они даже подняться не могут. Ты их чем утром кормил?"},{"kind":"paragraph","text":"— Шашлыком, — подумав, ответил Вацлав."},{"kind":"paragraph","text":"— Каким шашлыком?"},{"kind":"paragraph","text":"— Который в субботу делали."},{"kind":"paragraph","text":"— Ты что, с ума сошёл?!"},{"kind":"paragraph","text":"— Ну а что?"},{"kind":"paragraph","text":"— Да он протух уже давно! Я же тебе говорила кашу курам сварить!"},{"kind":"paragraph","text":"— Я с утра со строителями занимался, некогда было!"},{"kind":"paragraph","text":"— Алкоголизмом ты своим занимался, а не строительством! Они ж теперь, чего доброго, подохнут!"},{"kind":"paragraph","text":"— Чёрт их не возьмёт! — невозмутимо ответил Вацлав. — Просрутся — бодрее будут! Допивай, Цыля, я сейчас ещё принесу."},{"kind":"paragraph","text":"Последняя фраза хозяина вышла за границы терпения Марианны. От её крика даже свиньи, до того ещё питавшие надежду на выпивку, предпочли срочно укрыться в сарае."},{"kind":"paragraph","text":"— Если ты выпьешь сегодня ещё хотя бы каплю или нальёшь этой своей дворняге, я тебя собственными руками придушу, слышишь?! А ну пошёл кур остальных искать! Лежат ­где-нибудь под кустами или у соседей. Что о нас люди подумают? — прокричала Марианна, и, громко хлопнув дверью, скрылась в доме."},{"kind":"paragraph","text":"— Достала уже! Поназаводит хуеты всякой, а ты потом приглядывай за ней! — недовольно пробурчал Вацлав, направляясь в сторону сада."},{"kind":"paragraph","text":"Оставшись в одиночестве, Цыля спокойно допил пиво и метнул бутылку в сторону мусорного ведра, стоявшего у входа в веранду. Бутылка, срикошетив от корзины, некрасиво шлёпнулась на газон прямо напротив дверей. Чуть дальше, чем доставала цепь от ошейника."},{"kind":"paragraph","text":"Сперва Цыля хотел снять ошейник и отправить бутылку в мусорное ведро, но, подумав, решил ­всё-таки не рисковать. Супруга Вацлава находилась в доме и могла появиться в любую секунду. Без ошейника ей на глаза лучше было не попадаться вовсе."},{"kind":"paragraph","text":"— Ну, привет, дворняга! — вырвал Цылю из его цепных сомнений спокойный, вкрадчивый голос."},{"kind":"paragraph","text":"Обладателя голоса Цыля узнал сразу. Это был Егор Рябов, молодой парень, внешне ­чем-то сильно смахивавший на Пушкина (на чём все его достоинства, по мнению Цыли, и заканчивались), в недавнем прошлом — учитель математики в местной школе."},{"kind":"paragraph","text":"Подтвердив догадку Цыли, Рябов собственной персоной появился в дверях веранды."},{"kind":"paragraph","text":"— А хозяйка права, — сказал он, надменно пнув ногой брошенную Цылей бутылку. — С тебя и правда толку нет. Не будь Вацлав таким пропойным дегенератом, давно бы тебе под зад ногой дал."},{"kind":"paragraph","text":"Рябова Цыля ненавидел всей душой, и каждая их встреча заканчивалась руганью и взаимными оскорблениями. Регулярно дело доходило и до драк, для прекращения которых нередко требовалось вмешательство хозяев. К счастью, во дворе Рябов появлялся редко, предпочитая проводить время на диване перед телевизором."},{"kind":"paragraph","text":"— Как будто с тебя польза ­какая-то есть, — мрачно сплюнул Цыля."},{"kind":"paragraph","text":"— Конечно, есть! — сказал Рябов, присаживаясь на ступеньки веранды и предусмотрительно измерив взглядом длину цепи."},{"kind":"paragraph","text":"Цыля и без того знал, что до ступенек цепь не дотянется, но своё замечание относительно наглядной трусости Рябова решил оставить при себе. Хвастать своей наблюдательностью, сидя на цепи, было глупо и неуместно."},{"kind":"paragraph","text":"Кстати говоря, большинство насмешек Рябова, а заодно и коллег по автопарку, сводились примерно к этой же мысли, с небольшими вариациями. Только в отличие от тех же водителей, Рябов предпочитал дразнить Цылю не из ­каких-то жизненных или моральных принципов, а исключительно ради собственной забавы, что и выдавало в нём ту особую подлую породу, которую Цыля не переносил на дух и в сравнении с которой даже Марокантов выглядел чуть ли не эталоном благородства."},{"kind":"paragraph","text":"— Тут дело понимаешь в чём, — с наигранной задумчивостью продолжил Рябов. — Дело в искренности."},{"kind":"paragraph","text":"— В какой ещё искренности?"},{"kind":"paragraph","text":"— А в такой. Вот ты работаешь собакой на полставки. И при этом испытываешь внутренние сомнения по поводу моральной стороны своего заработка, так? Вот и скажи мне тогда: какая польза может быть от сомневающейся полусобаки?"},{"kind":"paragraph","text":"— А ты, стало быть, сомнений не испытываешь?"},{"kind":"paragraph","text":"— Ни грамма, — на этот раз вполне искренне ответил Рябов. — Да и какие могут быть сомнения? Хозяева — моральные дегенераты. Платят хорошо и исправно. Работа непыльная. Последние два пункта особенно важные. Собственно говоря, только они и важные."},{"kind":"paragraph","text":"— А что люди думают, тебя не волнует? Извращенцами нас называют."},{"kind":"paragraph","text":"— Да плевать на людей и их мнение! Большинство из них с удовольствием заняло бы твоё место и спокойно получало деньги, не испытывая по этому поводу сомнений и не привлекая к этому свою мелочную, надуманную совесть."},{"kind":"paragraph","text":"— И ты вот так всю жизнь планируешь котом быть?"},{"kind":"paragraph","text":"— Я что — идиот? Деньжат соберу и свалю нафиг от этих больных на голову уродов. Начну новую жизнь. Понимаешь? Я искренен, и в этом смысле моя совесть совершенно чиста. Поэтому и польза от меня есть. Польза для меня самого. А вот ты, как ни крути — всего лишь сомневающаяся недособака! Я думаю, дело даже не в том, что тебя волнует мнение окружающих, а в том, что ты и вправду переживаешь по поводу того, что тебе приходится быть собакой лишь наполовину. Вот поэтому ты и есть — самый настоящий извращенец!"},{"kind":"paragraph","text":"Терпение Цыли закончилось, и он принялся нервно искать пальцами застёжку своего ошейника."},{"kind":"paragraph","text":"— А насчёт ошейника — это ты подумай хорошенько! — спохватился Рябов. — Я-то в дом удеру. Побежишь за мной — хозяйка опять Вацлава пилить начнёт, что ты с ошейника срываешься."},{"kind":"paragraph","text":"Цыля и без предупреждений Рябова оставил попытку освободиться от цепи. Бить морду коту прямо сейчас Цыле не хотелось. В конце концов, в словах Рябова чувствовалась ­какая-то особенно ясная правда. В сущности, он действительно исполнял свои обязанности недобросовестно и не раз ловил себя на мысли, что это волнует его не в меньшей степени, чем сама суть его работы. Те же свиньи трудились на своём поприще куда вдохновеннее, а Рябов и вовсе отличался от настоящего кота только тем, что не был котом (но в сложившихся обстоятельствах это, по мнению Цыли, существенной роли не играло). Поэтому сейчас действительно следовало полностью сконцентрироваться на деньгах и не обращать внимания на происходящее вокруг."},{"kind":"paragraph","text":"Воспользовавшись растерянностью Цыли, Рябов предусмотрительно скрылся в доме. А может, он просто заметил Вацлава, который, напустив на себя вид уставшего от бесконечных хлопот хозяина, как раз возвращался из сада. Судя по неуверенной походке, Вацлав успел прибегнуть к ­какому-то более радикальному средству избавления от похмелья — в бане или гараже у него наверняка имелась заначка на случай непредвиденных осложнений в отношениях с Марианной."},{"kind":"paragraph","text":"Окинув нетрезвым взглядом Цылю, он на пару секунд многозначительно задумался, после чего быстро заглянул в веранду и через мгновение вернулся с очередными пивными бутылями."},{"kind":"paragraph","text":"— Ты это куда? — тут же раздался из дома голос хозяйки."},{"kind":"paragraph","text":"О планах супруга она наверняка была предупреждена вездесущим Рябовым."},{"kind":"paragraph","text":"— Пойду Цылю выгуляю! — заплетающимся языком ответил хозяин. — Затосковал он уже, на цепи сидя."},{"kind":"paragraph","text":"— Какой Цыля?! С курами что делать?"},{"kind":"paragraph","text":"— Да разобрался я уже с курами! По домам отпустил, пока не поправятся. А Николаевну уговорил в курятнике полежать, пообещал премию тройную. Она молодец, держится пока."},{"kind":"paragraph","text":"— Ну хоть не подохнут, а? — с тревогой поинтересовалась хозяйка, выглянув в окно."},{"kind":"paragraph","text":"— Пару дней отлежатся, и всё будет в порядке, — заверил её Вацлав. — А пару дней без кур, я думаю, мы переживём."},{"kind":"paragraph","text":"— Вот тебе всё просто — переживём, переживём… Нормальный хозяин давно задумался бы, что пора новых кур завести. Эти изначально слабые были — землю не роют, кудахтать не хотят. Хотя, что я тебе говорю, если у тебя даже собака не лает и полдня шатается неизвестно где?!"},{"kind":"paragraph","text":"— Закрой рот! Цылю ругать не смей! Он вообще один, кто меня понимает! — проявил характер Вацлав, потрепав Цылю за плечо и собственноручно сняв ошейник. — Ну что, Цылька, пойдём погуляем! А эти бабы пусть и дальше из себя куриных королев корчат."},{"kind":"paragraph","text":"Отворив ворота и пропустив Цылю вперёд, Вацлав ещё немного поругался с супругой, после чего, громко хлопнув створкой, жестом указал Цыле в направлении совхозного поля, своего любимого места для прогулок."},{"kind":"paragraph","text":"От пива на этот раз Цыля отказался (завтра ему снова предстояло полдня крутить баранку, и с алкоголем переусердствовать"},{"kind":"paragraph","text":"не хотелось), и Вацлав с удвоенным энтузиазмом принялся вливать в себя содержимое бутылок."},{"kind":"paragraph","text":"— Вот так вот! — удовлетворённо сказал он, как только они с Цылей оказались за околицей. — Крутишься всю жизнь, как белка в колесе. Сам работаешь, других заставляешь работать, а всё для чего? Ты не знаешь, Цыля?"},{"kind":"paragraph","text":"Цыля молча пожал плечами. Ответа на этот вопрос он действительно не знал, тем более если этот вопрос звучал из уст человека, который мог позволить себе почти всё."},{"kind":"paragraph","text":"— Не знаешь, — наигранно вздохнул Вацлав. — Да ты и не можешь знать, Цыля. Без обид, но чтобы понять подобное, нужно сперва ­чего-нибудь в этой жизни добиться. И добиться собственным лбом. Вот я тебе и скажу, Цыля, для чего всё это нужно. А нужно это, чтобы понять: для настоящего счастья нужно совсем другое. Не нужны миллионы, не нужны коттеджи, не нужны подчинённые. Это я раньше всегда мечтал уехать отсюда как можно дальше. От халупы батьковской, от запаха соляры, от кур, свиней этих грязных. А теперь…"},{"kind":"paragraph","text":"Очередная бутылка пива резво пошла в ход, и Цыля начал всерьёз опасаться, что ему придётся обратно тащить хозяина на себе. Учитывая комплекцию Вацлава, это выглядело непростой задачей и к тому же выходило за рамки собачьих обязанностей."},{"kind":"paragraph","text":"— Вот видишь этот луг? — продолжил демонстрировать тайные закоулки своей души Вацлав. — Думаешь, я просто так сюда прихожу? Это ж колхозный луг, не мой. И колхозу на него плевать! Бурьян третий год стоит и ещё десять лет стоять будет, пока всё лесом не зарастёт. А ведь земля здесь — высший класс! Особенно под картофель. Одно время я даже подумывал"},{"kind":"paragraph","text":"этот луг у колхоза выкупить или арендовать. А ведь не стал. Знаешь, почему? А потому что нельзя всё в жизни подчинять целям и выгоде. И хозяйство своими руками держу не из блажи, кто бы что по этому поводу ни говорил. Не могу по-другому! Веришь? Как из города решили сюда перебраться, так Марианне и сказал — мол, только с хозяйством жить будем! Условие поставил, даже кулаком по столу бить пришлось. Потому что в деревне по-настоящему можно только с хозяйством жить! Ты вот говорил, что ­кто-то там с автобазы ещё ко мне хочет. Зови! Зови всех! Мне и свиньи ещё нужны, и петух. Без петуха куры совсем от рук отбились, жрут абы что, хворают. А мне нужно крепкое хозяйство! Я за настоящую жизнь! За искреннюю!"},{"kind":"paragraph","text":"— А чего тогда настоящих животных не заведёшь? — спросил Цыля."},{"kind":"paragraph","text":"Ему захотелось немного унять красноречие Вацлава, который прямо посреди дороги решил справить малую нужду, и этим оскорбил ту часть сознания Цыли, в которой он оставался водителем."},{"kind":"paragraph","text":"— А вот это ты зря, — одёрнулся Вацлав, бросив протяжный и обиженный взгляд на Цылю. — Меня и так каждая собака этим упрекает — мол, самодур, людей за скот держу. Думаешь, я этого не вижу? Иной раз и вправду хочется соседей побесить от нечего делать, есть грешок. Но вот что касается скота, тут уж ты меня упрекать не смей! В этом я честен!"},{"kind":"paragraph","text":"Тема для Вацлава была болезненной, и возмущение в его голосе стремительно уступало место плаксиво-­обиженным интонациям."},{"kind":"paragraph","text":"— Ну не умею я с настоящими животными, понимаешь? — едва не пуская слезу, оправдывался Вацлав. — Хотел, пробо-"},{"kind":"paragraph","text":"вал — ничего не получается! Батька с хозяйством не ладил, вот и я не научился. Свиньи в говне топнут, куры дичают. Да и вообще, если растить настоящих, — что с ними делать потом? В мясе и молоке не нуждаюсь. А ведь порыв есть, понимаешь? Душа требует. Душа! И, на самом деле, нет разницы — настоящие это куры или нет. Взаправда, Цыля, это штука непростая! Она только внутри человека и существует. По внешнему о ней судить нельзя!"},{"kind":"paragraph","text":"В том, что «взаправда» Вацлава действительно штука непростая, Цыля не сомневался. Сформировалась ли она во времена отбирания компота у младшеклассников или в смутные годы построения бизнес-­империи (которая, если верить слухам, начиналась с торговли ворованными семечками), Цыля не знал. Но эта «взаправда» обладала способностью оказывать влияние на всё вокруг, и в этом, по мнению Цыли, Вацлаву следовало отдать должное. В себе самом, по крайней мере, Цыля подобной «взаправды» не ощущал. Наверное, именно поэтому он подрабатывал собакой у Вацлава, а не наоборот."},{"kind":"paragraph","text":"— Слышь, Цыля! — вдруг воскликнул Вацлав. — А давай ко мне собакой насовсем?! Что ты в своём автопарке кроме грыжи и геморроя заработаешь?"},{"kind":"paragraph","text":"— Ну не знаю, — замялся Цыля, — у меня семья. Насовсем не получится."},{"kind":"paragraph","text":"— Ну, будет у тебя один выходной в неделю — никаких вопросов! С женой столько лет душа в душу живёте — чего друг друга чаще видеть? Да и для нас ты уже как член семьи. Дочурка в тебе души не чает, Марианна."},{"kind":"paragraph","text":"— Разве? — засомневался Цыля. — А мне кажется, хозяйка меня недолюбливает. Думаю, это кот Рябов её против меня науськивает."},{"kind":"paragraph","text":"— Я вообще котов не люблю, — поморщился Вацлав. — Они себе на уме, гадят где попало. Только этих баб ведь не пой-"},{"kind":"paragraph","text":"мёшь — нужно им, видите ли, чтобы подле них обязательно ­кто-то был. Тут уж лучше кот, чем мужик ­какой-­нибудь."},{"kind":"paragraph","text":"Вацлав всё больше терял связь с реальностью, и Цылю это здорово начинало беспокоить."},{"kind":"paragraph","text":"— Запомни, Цыля, — продолжал настаивать на своей «взаправде» Вацлав. — В жизни нельзя быть ­кем-то наполовину! Ни дома, ни на работе — нигде! Так что соглашайся! Оклад я тебе сразу удвою, в дом пускать буду! И плевать, что Марианна на это скажет! Ну?"},{"kind":"paragraph","text":"— Не знаю, надо подумать…"},{"kind":"paragraph","text":"— Ну так думай! Я ведь тебя ещё щенком помню. Компот в школьной столовой у тебя отбирал, — усмехнулся Вацлав."},{"kind":"paragraph","text":"— Угу, — мрачно кивнул головой Цыля, которому подобные воспоминания не улучшали настроение."},{"kind":"paragraph","text":"— Да ты на меня не серчай, все так делали. Кто сильнее — тот и прав! Хорошие были времена, хотя и вспоминать о них особо не люблю. Зато ты мне как родной стал, понимаешь? Честно! Вот проси у меня, что хочешь! Ну?! Проси!"},{"kind":"paragraph","text":"— Мне бы недельку отгулов, — подумав, робко сказал Цыля. — Дочери из города на днях приехать должны, повидать хочу. Заодно и предложение твоё обдумаю спокойно, с женой посоветуюсь. Сам понимаешь: круглосуточной собакой становиться с бухты-­барахты нельзя."},{"kind":"paragraph","text":"— На неделю? — переспросил Вацлав, от удивления открыв рот. — Неделю без собаки на дворе? Ну не знаю…"},{"kind":"paragraph","text":"Вацлав выглядел растерянным и даже ­как-то по-детски обиженным. Наверняка он ожидал от Цыли пожеланий совсем другого характера. Например, повышении оклада, более длинной цепи или кастрации домашнего кота. Блёклая в своей бытовой простоте просьба Цыли слишком болезненно подкосила его возвышенное и даже, можно сказать, поэтическое настроение."},{"kind":"paragraph","text":"Вацлав несколько раз горестно икнул, с усердием приложился к бутылке, после чего ­как-то особенно естественно упал прямо наземь, при этом умудрившись сохранить контакт с бутылкой. Он, кажется, и вовсе не заметил, что окружающий его мир вдруг перевернулся. Эту способность хозяина Цыля наблюдал уже не в первый раз и зачастую именно ей объяснял себе все успехи Вацлава, связанные с бизнесом и бытовым достатком."},{"kind":"paragraph","text":"— Может, домой пойдём? — с опаской спросил Цыля."},{"kind":"paragraph","text":"— Какое домой, Цыля? Тебе что — охота на цепи сидеть? — ответил Вацлав, тяжело поднимаясь на ноги и отряхиваясь. — Нет, мы сейчас отдохнём немного, а потом в палку играть будем!"},{"kind":"paragraph","text":"— В палку? — почуяв неладное, переспросил Цыля."},{"kind":"paragraph","text":"— В палку! — ответил Вацлав и довольно уверенными винтами направился к видневшейся неподалёку роще."},{"kind":"paragraph","text":"Вацлава Цыля притащил домой ближе к полуночи. Во дворе стояла тишина, и только кот Рябов лениво курил, сидя на ступеньках веранды. И хотя Цыля был без ошейника и зол как собака, до Рябова ему сейчас дела не имелось."},{"kind":"paragraph","text":"Остаток прогулки выдался для Цыли особенно тяжёлым и беспокойным. Игрой в палку Вацлав на этот раз не ограничился. Сразу после этого жалкого и невразумительного действа (бросать палку у Вацлава получалось плохо, и на земле он сам оказывался гораздо чаще, чем палка), Цыле сперва пришлось сопровождать Вацлава в сельпо за водкой (по словам Вацлава, по-настоящему напиться простой сельский человек может только водкой из сельпо и никак иначе), а потом и на кладбище, где тот хотел попросить прощения у отца, но, так и не сумев отыскать его могилу, каялся у нескольких случайных надгробий."},{"kind":"paragraph","text":"Весь обратный путь Вацлав проделал на спине Цыли, беззаботно и даже ­как-то задорно похрапывая."},{"kind":"paragraph","text":"— Помоги его в дом занести! — сказал Цыля Рябову, пытаясь разогнуть спину."},{"kind":"paragraph","text":"— А мне это надо — дебила этого на себе таскать? — возмущённо ответил кот, поспешно докурив сигарету и швырнув окурок прямо себе под ноги."},{"kind":"paragraph","text":"— А мне — надо?"},{"kind":"paragraph","text":"— Раз таскаешь, значит надо! — пожал плечами Рябов и спокойно скрылся в доме."},{"kind":"paragraph","text":"Выругавшись, Цыля схватил хозяина подмышки и ­кое-как втащил на веранду, после чего, раздражённо пнув лежащий на земле ошейник, нырнул в будку и поклялся себе, что завтра с самого утра он пошлёт Вацлава куда подальше вместе с его «взаправдой» и всеми планами на счёт хозяйства."},{"kind":"paragraph","text":"Но истинную глубину «взаправды» Вацлава Цыля всё же недооценивал. В этом он наглядно убедился, когда под трезвон будильника выполз утром из будки."},{"kind":"paragraph","text":"Несмотря на вчерашний перепой, Вацлав уже не спал. На нём были надеты тщательно выглаженные брюки и свежая рубашка, а сам он — старательно умыт и причёсан. И хотя бодрящая влага колодезной воды оказалась не в состоянии совладать с алкоголической припухлостью физиономии, припухлость эта была Вацлаву, если так можно выразиться, к лицу. Она только добавляла важной уверенности к его образу начальника, неторопливо расхаживающего от свинарника к веранде и погружённого в изучение ­каких-то бумаг."},{"kind":"paragraph","text":"И если вчера вечером Цыля совершенно точно собирался послать куда подальше пьяного самодура, то сегодня перед ним"},{"kind":"paragraph","text":"стоял директор компании, погружённый в размышления по поводу слияния нескольких фирм-конкурентов и явно торопившийся на ­какое-то особо важное совещание. Посылать Вацлава прямо сейчас было неловко, тем более после того, как тот выудил из кармана брюк портмоне и протянул Цыле несколько купюр, в своих номиналах значительно превышавших оговорённый ранее размер ежедневной оплаты."},{"kind":"paragraph","text":"— Премия за то, что притащил меня домой, — деловым тоном пояснил Вацлав. — Итак, на сколько ты там хочешь уйти? На неделю?"},{"kind":"paragraph","text":"— До следующих выходных, — робко ответил Цыля."},{"kind":"paragraph","text":"— Мда, — недовольно пожал плечами Вацлав. — Ладно, как знаешь. Силой удерживать я тебя не могу. Только давай договоримся так: как определишься насчёт моего предложения, сразу дай знать. Если согласен быть собакой постоянно, с одним выходным в неделю — милости прошу! Платить буду по полной, даже больше, чем коту. А вот на полставки больше не надо. Верный ты пёс, надёжный. Это я, поверь, вижу и ценю. Но собак наполовину ­всё-таки не бывает. Так что выбор за тобой. И на работе скажи, кто там интересовался, пусть подходят сегодня же. Надо срочно хозяйство расширять, а то от безделья скоро совсем сопьюсь."},{"kind":"paragraph","text":"На автобазе коллеги встретили Цылина сдержанно, без привычных шуточек и подколок. Мнение Целлофена уже успело проникнуть в массы и теперь заставляло многих переосмысливать своё отношение к людям, животным и всяческим недостроенным жизненным сараям."},{"kind":"paragraph","text":"Даже Марокантов вёл себя непривычно тихо и пожал Цылину руку, сопроводив этот жест растерянной и кривой улыбкой. Судя по всему, внутренняя диалектика этого человека также переживала"},{"kind":"paragraph","text":"непривычный для себя период ломки и усложнения, причиняя своему обладателю заметный невооружённым взглядом дискомфорт."},{"kind":"paragraph","text":"В медпункте, куда Цылин заглянул по пути из гардероба, несколько водителей неуверенно поинтересовались у Цылина хозяйством Вацлава, перспективами его развития и особенностями рациона питания. А оператор передвижной ассенизаторской станции Василий Кудалахин и вовсе не испытывал сомнений в своём желании кардинально сменить сферу деятельности."},{"kind":"paragraph","text":"— Слышь, а Вацлаву там, часом, козлы не нужны? — громко расспрашивал он Цылина по пути к стоянке."},{"kind":"paragraph","text":"— Не знаю, — пожал плечами Цылин. — А почему вдруг именно козлы?"},{"kind":"paragraph","text":"— Да бабка моя, помню, всё коз держала. Ну и козёл, разумеется, был. Работа у него не пыльная, всё лучше, чем у меня. Может поговоришь сегодня с Вацлавом? Замолвишь словечко?"},{"kind":"paragraph","text":"— Я к нему, наверное, больше не пойду."},{"kind":"paragraph","text":"— Случилось чего? — забеспокоился Кудалахин."},{"kind":"paragraph","text":"— Да так, — махнул рукой Цылин."},{"kind":"paragraph","text":"У него на руках был путевой лист, его ждал верный ЗИЛ (даже с самого раннего утра выглядевший живым и очень добрым существом), и Цылину не хотелось тратить время на разговоры о свиньях, собаках и козлах. В том, что сам он к Вацлаву больше не вернётся, Цылин не сомневался."},{"kind":"paragraph","text":"Последним, кто напомнил Цылину о его приработке, был Целлофен Чинзе, тормознувший Цылина у самых ворот автобазы."},{"kind":"paragraph","text":"— Ну, что там насчёт моего вопроса? — крикнул он Цылину."},{"kind":"paragraph","text":"— Всё окей! — бодро ответил Цылин. — Вацлав как раз сарай новый собирается строить, будет увеличивать поголовье. Только не мешкай, а то, как я погляжу, желающих многовато."},{"kind":"paragraph","text":"— Что ж, прямо сегодня и заеду! Спасибо, Ваня! А сам что? Слыхал, ты Вацлава не то послал, не то покусал."},{"kind":"paragraph","text":"— Да ерунда это всё! Просто не могу я больше собакой быть, не получается."},{"kind":"paragraph","text":"— Ну как знаешь… Дело молодое! — ответил Целлофен и пожелал Цылину счастливого пути."},{"kind":"paragraph","text":"— Тут и думать нечего! — сказала жена, помешивая и без того остывший чай."},{"kind":"paragraph","text":"Было уже поздно, за полночь, но они с супругой до сих пор сидели на кухне и пока ещё были очень далеки от взаимного согласия."},{"kind":"paragraph","text":"— Сам же понимаешь, сколько стоит свадьбу сыграть, — вздохнула супруга. — А тем более — две сразу!"},{"kind":"paragraph","text":"Почему дочерям приспичило выходить замуж именно теперь, и при этом обеим сразу, объяснить не могли ни они сами, ни Цылин. Поставив их с женой перед фактом, дочери теперь спокойно дремали на веранде, которую Цылин достроил полгода назад и не в последнюю очередь благодаря своим нечеловеческим усилиям."},{"kind":"paragraph","text":"— До весны как раз на свадьбы заработаешь, — добавила супруга."},{"kind":"paragraph","text":"— Разве?"},{"kind":"paragraph","text":"— Ну, если будешь собакой постоянно, без выходных. Он же тебя и кормить будет. А может и меня курицей возьмёт? Как думаешь?"},{"kind":"paragraph","text":"— Не знаю, — ответил Цылин, после чего протяжным взглядом уставился в потолок."},{"kind":"paragraph","text":"В данный момент его переполняли смешанные мысли. Цылин не мог понять, чтó в планах жены его смущает больше: то, что ему придётся видеть жену сидящей в курятнике, или то, что жене придётся видеть своего супруга с ошейником на шее."},{"kind":"paragraph","text":"В любом случае потолок дать ответа на этот вопрос не мог. Цылин снова вернулся к бумаге и карандашу, при помощи которых уже не первый час пытался сопоставить свои финансовые возможности с пожеланиями дочерей."},{"kind":"paragraph","text":"— А может, они свадьбы в один день сыграют? — рассуждал Цылин, ковыряясь в недружелюбных цифрах, своими длинными рядами напоминавших цепь, от которой шея Цылина едва успела отвыкнуть. — И лимузин им не надо. Можно обычные машины шариками и лентами украсить. Да и зачем в городе праздновать? Можно и здесь, в столовой автопарка."},{"kind":"paragraph","text":"— Вот ты им об этом и скажи, — в очередной раз глубоко вздохнула жена."},{"kind":"paragraph","text":"— И скажу! Что это они нам условия ставят?"},{"kind":"paragraph","text":"— Ну это, в конце концов, твои дочки."},{"kind":"paragraph","text":"— И что? Они голодные росли? Раздетые ходили? Выросли и уехали — ни помощи, ни понимания. Теперь вот свадьбы в ресторанах им подавай с лимузинами! А мне всю жизнь пахать на них, как собака?"},{"kind":"paragraph","text":"— Ну, побудешь собакой ещё полгода, год. Потом отдыхать будем."},{"kind":"paragraph","text":"— Ты сама веришь в это? — спросил Цылин."},{"kind":"paragraph","text":"— Успокойся, Ваня. Думаешь, мне легко?"},{"kind":"paragraph","text":"Ругаться с супругой Цылин не собирался. Пусть она и не работала ­кем-нибудь из животных официально, но после сокращения в школе ей приходилось одновременно совмещать преподавание литературы, математики, химии и физкультуры, и в том,"},{"kind":"paragraph","text":"что она действительно понимает его чувства, Цылин не сомневался."},{"kind":"paragraph","text":"— Я ведь перед собой поклялся, что в собаки больше не пойду, понимаешь? — сухо сказал Цылин. — Думал, до пенсии баранку докручу, потом легче будет."},{"kind":"paragraph","text":"— Кому у нас на пенсии легче становится? Благо ещё, что у нас Вацлав есть. Пусть и самодур, зато сколько людей вокруг него прижилось. А дочери просто хотят жить не хуже, чем остальные. Понять их можно."},{"kind":"paragraph","text":"— Просто собаками они никогда не были."},{"kind":"paragraph","text":"— А ты хотел бы, чтобы им пришлось?"},{"kind":"paragraph","text":"Цылин грустно улыбнулся."},{"kind":"paragraph","text":"Г­де-то с год назад они с супругой точно так же сидели за полночь, обсуждая нечеловеческие аспекты человеческого бытия. Только в том разговоре их роли с женой были прямо противоположны. Жена не могла смириться с мужем-­собакой, уверяла, что и без ошейника они смогут поставить дочерей на ноги, достроить сарай и в целом жить «как люди». Он же доказывал обратное, утверждая, что лучше быть условной собакой, чем условным человеком с вечно условными желаниями. Теперь их мнения сменили полярность, но сама жизнь не претерпела изменений. И это угнетало особенно сильно."},{"kind":"paragraph","text":"— Он меня в палку заставляет играть, — тихо сказал Цылин, откладывая в сторону карандаш и оставляя все цифры на бумаге неизменными."},{"kind":"paragraph","text":"— Силой, что ли? — поинтересовалась жена."},{"kind":"paragraph","text":"— В ­том-то и дело, что нет, — робко ответил Цылин, ощущая, как в этих словах шевельнулась «взаправда» уже принятого и не подлежащего дальнейшему обсуждению решения."},{"kind":"paragraph","text":"За неделю, которую Цылин не был собакой, кирпича и силикатных блоков у забора Вацлава поубавилось. Строительство свинарника находилось в самом разгаре и даже вошло в свою решительную стадию."},{"kind":"paragraph","text":"Настроение у Цылина было хорошее и в ­какой-то степени даже боевое. В круглосуточном бытии собакой были свои плюсы помимо денег. Как круглосуточная собака Цылин имел все основания для того, чтобы с особым усердием бить морду коту, не опасаясь последствий. Этим, собственно говоря, Цылин и планировал заняться безотлагательно."},{"kind":"paragraph","text":"Подойдя к воротам и отперев засов, Цылин попытался зайти внутрь, однако сделать этого ему не удалось. Стоило двери скрипнуть, как с обратной стороны ­кто-то с особым усердием навалился на дверь, огласив всю улицу криком."},{"kind":"paragraph","text":"— Гав! Гав! Блядь! Гав! — орал хрипловатый и знакомый Цылину голос. — Кого там черти несут?!"},{"kind":"paragraph","text":"— Это я, Цыля, — робко ответил Цылин, который совершенно не ожидал повстречать на пути к ошейнику ­каких-либо препятствий."},{"kind":"paragraph","text":"Ворота нехотя приоткрылись, и Цылин увидел перед собой недовольную физиономию Марокантова."},{"kind":"paragraph","text":"— Чего тебе? — сердито спросил тот, поправляя ошейник."},{"kind":"paragraph","text":"— К Вацлаву, — растерянно сказал Цылин и заглянул во двор."},{"kind":"paragraph","text":"Во дворе Вацлава видно не было. Несколько незнакомых кур неторопливо бродили, лузгая семечки. На ступенях веранды сидел кот Рябов, на помощь которого рассчитывать не приходилось."},{"kind":"paragraph","text":"— А ты что тут делаешь? — спросил Цылин Марокантова, который по-прежнему придерживал ворота и не спускал с Цылина глаз."},{"kind":"paragraph","text":"— Не твоё дело! — рявкнул Марокантов."},{"kind":"paragraph","text":"— Как это не моё?! Это мой ошейник! Моё место! Проваливай давай! — резко сказал Цылин и попытался оттолкнуть Марокантова."},{"kind":"paragraph","text":"— Не пущу! — крикнул тот и снова навалился на дверь."},{"kind":"paragraph","text":"На шум из сарая выглянуло несколько свиней, среди которых Цылин краем глаза заметил и Целлофена Чинзе. На этот раз ветеран наблюдал за происходящим молча и вступаться за Цылина не спешил."},{"kind":"paragraph","text":"Борьба тем временем продолжалась и явно входила в свою решающую стадию. Цылину удалось потеснить противника, и теперь они боролись с Марокантовым уже возле будки, под одобрительный хохот кота и настороженные оханья кур. Рубаха Цылина надрывно трещала, но и сам Цылин нашёл способ ощутимо досадить своему визави. Ухватившись за цепь, он дёргал шею Марокантова, причиняя тому существенные неудобства. Марокантов громко и нехорошо ругался, завывал."},{"kind":"paragraph","text":"Выскочившему на шум из дома Вацлаву далеко не сразу удалось разнять участников драки. Через несколько минут все трое, запыхавшись, сидели на траве и удивлённо друг на друга поглядывали."},{"kind":"paragraph","text":"— Ты это чего? — спросил, наконец, Вацлав Марокантова, поправлявшего ошейник и растиравшего шею."},{"kind":"paragraph","text":"— Да во двор, паскуда, проникнуть пытался, — деловито, с чувством исполненного долга, ответил Марокантов. — Видно, украсть ­чего-то планировал."},{"kind":"paragraph","text":"— А ты чего? — перевёл свой взгляд на Цылина Вацлав."},{"kind":"paragraph","text":"— Собакой пришёл быть, — смущённо ответил Цылин, осматривая порванную в нескольких местах рубаху."},{"kind":"paragraph","text":"— Катись к чёрту, Цыля! Даже не мечтай! Ошейник теперь мой! — оскалился Марокантов."},{"kind":"paragraph","text":"— С какой это стати?"},{"kind":"paragraph","text":"— А с такой!"},{"kind":"paragraph","text":"Драка была готова вспыхнуть вновь, но Вацлав, пользуясь своим авторитетом и неожиданной трезвостью, быстро предотвратил конфликт:"},{"kind":"paragraph","text":"— Фу, Мара, фу! Марш в будку! Я сам разберусь! И ты, Иван, тоже зря на пса не кричи! Он всего лишь дело своё делает. И, как видишь, неплохо справляется."},{"kind":"paragraph","text":"Фыркая и посыпая Цылина последними ругательствами, Марокантов послушно скрылся в будке."},{"kind":"paragraph","text":"Вацлав по-дружески похлопал Цылина по плечу."},{"kind":"paragraph","text":"— Слушай, Иван! Не хочу, чтобы между нами недопонимания остались, поэтому скажу всё как есть. Как собака ты мне всегда нравился, вот те крест! Но, положа руку на сердце, пёс из тебя сторожевой не получился. Тут уж Марианна права, как ни крути. Для города ты бы сгодился в самый раз, но здесь, — Вацлав трепетным взглядом обвёл двор, — здесь от собаки больше требуется. Тем более, сейчас, когда хозяйства прибавилось. Ты отгулы просишь, сомнения испытываешь. Сколько дней прошло, от тебя — ни слуху, ни духу. Не по-собачьи это ­как-то, понимаешь? А этот даже не спрашивал ничего! Пришёл, ошейник надел и сразу же прохожих матом на всю улицу обложил. Кота не гоняет, палку, как и положено, в зубах носит."},{"kind":"paragraph","text":"— У меня дочери замуж выходят, свадьбы делать надо, — обречённо сказал Цылин. — Хочется по-человечески дочерей выдать. Как же мне тогда, если не собакой?"},{"kind":"paragraph","text":"— Ну, тут уж не знаю, чем тебе помочь. Даже место петуха, и то третьего дня заняли, видишь?"},{"kind":"paragraph","text":"Вацлав кивнул головой в сторону сада, где в окружении десятка женщин между яблонь и кустов гордо вышагивал почтенных лет мужик в жакете и красных резиновых сапогах. Кажется, в недавнем прошлом это был врач местной больницы."},{"kind":"paragraph","text":"— А я уже согласен быть собакой круглосуточно. С одним выходным в неделю."},{"kind":"paragraph","text":"— Ну, сам видишь, — сочувственно вздохнул Вацлав, кивнув головой на будку, в которой Марокантов ­что-то увлечённо и громко ел. — И без всяких выходных! Ну как такого пса за ворота вышвырнуть?"},{"kind":"paragraph","text":"— Да подлец он, а не собака. Хоть у Целлофена спроси! — не согласился Цылин."},{"kind":"paragraph","text":"— А вот тут ты, Иван, не прав! — отозвался свинья Целлофен. — Как собака Марокантов полезнее тебя будет. Да и нельзя сказать, что он подсидел тебя. Ошейник на траве валялся. Лёха всего лишь расторопность проявил. В нынешнее время штука необходимая. Каждый устраивается как может, незачем на это пенять."},{"kind":"paragraph","text":"— И это твоё спасибо за то, что я тебя сюда устроил? — бессильно спросил Цылин."},{"kind":"paragraph","text":"— Большое тебе человеческое спасибо за это! А вот что касается собаки…— Целлофен не закончил свою фразу и скрылся в свинарнике."},{"kind":"paragraph","text":"В этот момент в ворота ­кто-то постучал, и уже через секунду, громко матерясь, из будки выскочил Марокантов."},{"kind":"paragraph","text":"— Фу, Мара, фу! — крикнул на него Вацлав, — Не ори! Это строители!"},{"kind":"paragraph","text":"Марокантов снова замолк и вернулся к прерванной трапезе."},{"kind":"paragraph","text":"— Ну ладно, Иван! — сказал, снова похлопав Цылина по плечу, Вацлав и ушёл встречать строителей, которые с опытной опаской проходили возле будки. — Спасибо, что зашёл. Заглядывай иной раз. Посидим, пивка попьём, вспомним, как я у тебя компот в школе отбирал. А сейчас извини, сам видишь — дел по горло. Нужно срочно сарай достраивать, а то свиньям уже спать негде."},{"kind":"paragraph","text":"Выйдя за ворота, Цылин окинул взглядом особняк Вацлава, в котором он как собака теперь был не нужен, а как человек не был нужен вообще никогда, и понуро поплёлся к автобазе, подпитывая себя робкой надеждой на то, что ему вернут его старый ЗИЛ, и что удача в этой жизни может улыбнуться даже самому обыкновенному человеку."}]'::jsonb,
  '2021-12-30T12:00:00.000Z'
)
