INSERT INTO "Articles" (slug, title, author_id, cover_path, cover_blur, cover_width, cover_height, excerpt, content_blocks, published_at)
VALUES (
  'mrd2-natsionalnost-robot',
  'Национальность робот',
  (SELECT id FROM "Authors" WHERE name = 'Оганес Мартиросян' ORDER BY id LIMIT 1),
  'mrd2/mrd2-natsionalnost-robot.jpg',
  'data:image/jpeg;base64,',
  1200,
  757,
  'Маяковский выкурил натощак сигарету, подзаправился чаем и пошёл в историю. В ней написал Во весь голос, фаллически продвинулся вперёд, растолкал жезлом толпу, роботизировался, взошёл над Соколовой горой и прочёл с неё св',
  '[{"kind":"image","path":"mrd2/mrd2-natsionalnost-robot.jpg","caption":null},{"kind":"paragraph","text":"Маяковский выкурил натощак сигарету, подзаправился чаем и пошёл в историю. В ней написал Во весь голос, фаллически продвинулся вперёд, растолкал жезлом толпу, роботизировался, взошёл над Соколовой горой и прочёл с неё свои ранние стихи. Его назвали больным, ненормальным, мрачным суицидальным типом, вызвали полицию и повезли в бобике на закат. На нём его распяли, напялили на его ноги, голову и лицо крест и пустили по улицам в таком виде, будто он прилетел с Сатурна; даже если и так, то нельзя так, кричал он им. Но дети бежали за ним и били камнями и комьями грязи, а железо стекало с Владимира и превращалось в чёрных огромных жаб. В ­какой-то момент Маяковский превратился даже в город Владимир и струился, и тёк по Саратову в обличии машин, домов и стихов, написанных стальными каплями дождя, идущего день за днём."},{"kind":"paragraph","text":"Впрочем, всё это было сном, потому что утром Маяковский сидел в кафе с Лилей, ел омлет, пил вино и писал о любви. Лиля молчала, курила и куталась в шарф, скрывающий под собой рассказы Бунина и Куприна. Стоял сентябрь, на улице похолодало, но тепло восходило с солнцем, не очень было холодно, просто тепло текло и становилось к вечеру холодом, повзрослев. Владимир хмелел, он удивлялся себе, двадцать первому веку, отсутствию мировой славы своей, крушению СССР и т.д. — просто приходил в себя пару лет; но рассылал стихи и пьесы по инету, торопил время, души и редакторов. Но они не спешили: чужд он был, громоздок. Так и пил, и писал, и гулял с Лилей Брик по Саратову. Пил виноградный сок, постаревший вином. Иногда набредал на Бурлюка и Кручёных, но они не узнавали друг друга, просто смотрели в глаза и расходились, как пьяные на свадьбе в кафе. А в этом кафе они с Лилей сидели уже час, не меньше, дышали собой и металлическими гайками и болтами столов, переходящих в стулья. Выпитое текло в озёра желудков, где плавали лодки потерпевших крушение их самих. Через час Маяковский отлил, вымыл руки и повёл Лилю с собой, довёл до дневного клуба, там покидал в бильярде шары, похожие на его глаза, выпил минеральной воды Нарзан, посмотрел на Ютубе ролик с отрезанием всего лишнего от текста тела, опять покурил, но две сигареты, и зашагал домой: Лиля умчалась к себе."},{"kind":"paragraph","text":"На квартире ревел и орал, бросался на замочные скважины и розетки, чувствовал поля электричества в воздухе, наносил по ним удары руками, ногами и головой, через пару часов затих, выпил холодной воды и лёг: отошёл ото сна. Внутри своего тела видел мировую славу, поездки в США и далее, чтение стихов, где каждая строка — столб с протянутым к другому столбу проводом — мыслью, чтобы горели концы, рифмы, фонари, светили всем, особенно пацанам, швыряющим в них камни и кирпичи, гасящим поэтов, убивающим их, ломающим."},{"kind":"paragraph","text":"Он вскочил от звонка, взял пятитонный телефон и заговорил с Луначарским, обрисовал ему свою жизнь, ситуацию, образы стихов и поэм. Тот покивал сквозь трубку и обещал помочь. Буду издан, воскрес Маяковский, сполоснулся в десятиметровой ванной, побрился, увлажнился лосьоном и стал собой: чугунным, свинцовым — литым. Обрюхатил свое сознание, родил поэму, выпил из бутыли сока, заправился молоком и поспешил на работу. На ней раздавал людям листовки из себя и других, рекламировал поэтический клуб Хорошо, где намечались его выступления, стоял над толпой и над всем и так проводил часы. Пил чай из зелёного термоса и вновь себя раздавал, некоторые листы даже подписывал, ставил росчерк пера под названием Паркер. К вечеру приехал Луначарский, дал Володе руб­ли, похвалил за труды и уехал на Вольво. Маяковский вздохнул облегчённо и пошёл по дороге, до глухого кафе. Там сел за стол и заказал водку Егор, выпил рюмку, запил необъятным соком и посмотрел на девочку. Та подмигнула ему, но он вспомнил о Лиле и перестал; начал пить и скучать, рассматривать свои ногти и покусывать заусенцы. Ничего, думал он, завтра вой­ду в стихи, выверну их наизнанку. Он поднял рюмку за хозяина заведения и осушил её. Ничего ужасного не решил, никого не сломал, не обвенчал с ничем, только тяжеловесно закурил сигарету и выдохнул мощный дым. Заказал жареные сардельки, начал макать их в соус и есть. Каждая весила жизнь, прожитую не зря. И он двигал бульдозерами челюстей, ехал ими по воздуху, распахивая его. Вокруг чудились пролетарские писатели, напичканные взрослой жизнью, совестью и ничем. Они рыдали каждым движением и обожали себя. Официанты танцевали с подносами и перебрасывались под музыку шутками и телами цыплят. Африка чувствовалась в каждом движении и струилась вином."},{"kind":"paragraph","text":"Маяковский плясал в центре зала и глотал небеса. Зажёвывал их целиком, радовался и пел. Хлопал в многовековые ладоши. Потом"},{"kind":"paragraph","text":"показал брейк-данс, прошёлся на руках, уронил бумажник, перевернулся, встал на ноги и завопил, что он величайший поэт. Все захлопали, кроме одного мужчины, который начал ходить по залу и искать пистолет. Я потерял ТТ, повторял он и переворачивал мозги, и заглядывал под них. Ночью Маяковский вернулся домой, включил телевизор и уснул под запах звёзд. Во сне взял три гири по очереди — Марс, Юпитер, Сатурн, и отжал их пять раз. Чуть и малость вспотел, отправился под душ, вытерся и сел за стихи."},{"kind":"paragraph","text":"Написал пару штук, выпил кофе, похожий на сгусток ночи, и посмотрел на часы. Они показывали Время жить и время умирать. Он закурил сигарету Восток и выстрелил ею в небо. Позвонил Лиле, позвал её в кино со своим участием и поехал к Победе. Встретил любимую и зашептал ей светила в уши. Поцеловал её, подал руку и повёл её в зал, где сидели десятки Маяковских и готовились к фильму. Они ели попкорн и смотрели в себя. Владимир и Лиля сели в первом ряду и уставились на экран, на котором шло действо: краны поднимали части тела Маяковского, а рабочие крепили их. Последним актом была установка головы, которая при присоединении к шее открыла рот и начала изрыгать слова, то есть бетон. Таким было кино. В конце его Маяковский взял Лилю за руку и повел её в парк. Там они катались на каруселях и ели сахарную вату. Наблюдали стихи Маяковского, выбегающие из него и убегающие прочь от него в форме детей, напичканных гексогеном. Маяковский радовался этому и курил абхазский табак. Смотрел на часы, на стрелки — колёса велосипедов и звал вселенную всем нутром. Тростью сшибал цветы. А позже привёл Лилю к себе, напоил шампанским и уложил в постель. Вогнал гвоздь в её стену и повесил на него картину Ван Гога. После курили и распинали себя на каждом пятаке земли. Лиля ушла, оставив предисловие себя в комнате — тонкий весьма аромат. Владимир вдохнул его, насытился и опал на планету дождём."},{"kind":"paragraph","text":"После пришёл в себя, купил билет до Москвы, доехал, пошёл к памятнику своему и поцеловал правый мизинец его. Прочёл под ним стихи, собрал толпу людей из одного человека, поболтал с ним поздней, выпил на лужайке вина, отнёс флешку со стихами в журнал Сталинград и уехал к себе. Мчался на скором и орал своё величие из окна, раздавался вокруг. Ему было тридцать три, тридцать четыре и сто двадцать семь лет везде. Глаза его были фейерверками, искрились в объёмах глазниц. Он превращался в киборга, нёсся вперёд и ломал ночной воздух — шоколад с орехами-­звёздами внутри. Отдыхал в вагоне-­ресторане, пил горячий грог, ломал и расширял голосом стены. В Саратове пил лимонад, обнимал встречающую Лилю, курил с ней и тосковал о себе двадцатых годов, когда он жил в Москве и колесил по планете, которая кончилась, как пирожок. Выпили в пабе чехословацкого пива и растранжирили свои юность и мозг."},{"kind":"paragraph","text":"И Маяковский начал расширяться и расти, он охватил своими объёмами Саратов и сжал его, сделал своим поклонником, чтобы ударить из него по всему — раскрошить своим творчеством мир и сделать его своим. Лиля накрасила губы, сделала глоток из бокала и усыновила его. Владимир заметил это и поздравил Лилю с ребёнком, выкушал творог и сыр, улетев через них. Побывал в горячей точке — в Сирии, почитал российским и сирийским бойцам стихи, отправился в Карабах, поддержал мир, побаюкал на руках вой­ну, дал ей молока, хоть она и просила пива, вернулся, не застал Лили, покончил с собой на Театральной площади, встал, отряхнулся, зажал рану пальцем, дождался закрытия её, как ресторана, когда внутри никого нет. И зашагал домой, чеканя ногами монеты — звёзды. Хотя есть ещё бумажные купюры — тоже светила в небе."},{"kind":"paragraph","text":"На квартире собрал всех своих друзей, обзвонив их, открыл шампанское и кричал Облако в штанах, данное навсегда, посколь-"},{"kind":"paragraph","text":"ку в кармане этих штанов отдыхает советский паспорт, читающий стихи о себе. Маяковский дымил двухметровой сигаретой, заглядывал метафизической головой к соседям сверху, воровал у них свет и предлагал им паштет. А в общем, листал журналы кино, пил из горла и радовался электричеству, выходящему из него. После квадратно спал, выдыхая прямоугольный воздух, участвовал в процессах Сталина, зачитывал в стихах приговоры и краснел от стыда. Был красным кирпичом, а не белым, поскольку стройка — гражданская вой­на, которую мирит серый бетон — серые небеса, обещающие дожди. Утром развесил красные флаги на балконе, протрубил из рога и прочел Левый марш. Собралась толпа; стояла, фотографировала, аплодировала и пела революционные песни."},{"kind":"paragraph","text":"Было хорошо и светло. Маяковский позировал, вбивал чугун в головы, а после пил чай и дышал сам собой. Позвонил в редакцию Красной нови, потребовал гонорар, получил отказ, приглашение к ним на выступление у них, оделся, собрался, поехал на Рено, прочёл среди редакторов громогласные стихи, получил деньги, завалился в кабак, раскуражился, растрезвонился, сыграл на гитаре, вызвал девочек, махнул в сауну, там провёл пару часов, накатил, поимел, расслабился по полной, зажигал в клубах, нюхал кокос в туалете, пробегал по дорожке носом, тащился от бёдер и губ сумасшедших девчонок. Дома долго блевал, пил минералку, смачивал и обрабатывал Мирамистином нужное место, спал, как отступал Наполеон, видел во сне Бородино и Лермонтова над ним, мычал и дышал, рождая ещё стихи. А когда заглянул в зеркало, то увидел Есенина в нём — вместо себя. Тот был тёмен, как Чёрный человек, и махал сам себе рукой."},{"kind":"paragraph","text":"Маяковский вздрогнул, протёр глаза, но от этого самим собой не стал. Два самоубийства на одного человека, понял он. Всё было понятно, потому через пару минут он курил сигарету, которая"},{"kind":"paragraph","text":"была очередным уменьшающимся от ударов воздуха гвоздём в крышку гроба — в лицо, за которым лежит труп Иисуса Христа. У каждого человека. У всех."}]'::jsonb,
  '2021-12-30T12:00:00.000Z'
)
