INSERT INTO "Articles" (slug, title, author_id, cover_path, cover_blur, cover_width, cover_height, excerpt, content_blocks, published_at)
VALUES (
  'mrd2-o-sinem-rytsare-i-devochke',
  'О синем рыцаре и девочке',
  (SELECT id FROM "Authors" WHERE name = 'Александр Шилякин' ORDER BY id LIMIT 1),
  'mrd2/mrd2-o-sinem-rytsare-i-devochke.jpg',
  'data:image/jpeg;base64,',
  1200,
  663,
  'Ночью здесь реки разлились, зимой замёрзли. Ночью здесь горы развалились, холодной зимой. Ночь здесь стоит — мгла чёрная. Снег во тьме идёт — мгла белая. Не привыкнут к темноте глаза, идёт в белом снегу, тёмной ночью.',
  '[{"kind":"image","path":"mrd2/mrd2-o-sinem-rytsare-i-devochke.jpg","caption":null},{"kind":"paragraph","text":"Ночью здесь реки разлились, зимой замёрзли. Ночью здесь горы развалились, холодной зимой. Ночь здесь стоит — мгла чёрная. Снег во тьме идёт — мгла белая. Не привыкнут к темноте глаза, идёт в белом снегу, тёмной ночью."},{"kind":"paragraph","text":"Горячо дышит, снега по пояс. Валится на колено, тонет в снегу, идёт. Снег неслышно падает, неба не видно. Корка на снегу ломается под ногами, и в звуке этом другой звук слышится: стонет в темноте ребёнок, не видит, но зовёт."},{"kind":"paragraph","text":"Рыщет в снегу, слышно, как кипит в горле; в чёрной мгле идёт туда, где зовёт ребёнок. Не кличет ребёнка — ищет на ощупь в снегу, в стороне голоса. Нет тут голоса, снег тихо идёт во тьме, громко лопается под ногами."},{"kind":"paragraph","text":"Упал на колени, ползёт, тонет в снегу, и во тьме глаза не привыкнут, не увидят и не найдут, руки онемеют в снегу и тогда только схватят тонкую ножку, холодную, едва не мёртвую. Руки поднимут"},{"kind":"paragraph","text":"голое холодное тело и прижмут губы к глазам, но не увидят глаза губ и лица, а только чуть тёплое учуют ноздри — запах, которым дышат дети."},{"kind":"paragraph","text":"Тогда возьмёт ребёнка на руки и положит себе на горячую грудь, под толстый вязаный свитер, под тяжёлую колючую шубу. Встанет в снегу и будет идти во тьме, нести будет ребёнка, пока не обессилеет. Ребёнок руками и ногами обхватит тёплое, прижмётся изо всех сил и будет дрожать, уткнётся лицом в шею, о бороду лицо царапая, задыхаясь от горячего перегара. Обессилев, упадёт на колени, и ребёнок будет засыпать вместе с ним, холодной зимой, надолго замерзать во мгле."},{"kind":"paragraph","text":"Ребенок не спит, ребёнок толкает, щиплет. Дёргает ребёнок замёрзшую от дыхания бороду, примёрзла шуба, онемело могучее тело. Ребёнок хочет разбудить, кусает грудь до крови, плачет, тянется руками через горло свитера к лицу, пальчиками тычет в холодные веки. Ребёнок хочет разбудить. Ребёнок разбудит."},{"kind":"paragraph","text":"— Просыпайся, — плачет ребёнок."},{"kind":"paragraph","text":"— Я не сплю, — он отвечает."},{"kind":"paragraph","text":"— Ты замерзаешь, — плачет ребёнок."},{"kind":"paragraph","text":"— Не замёрзнем, — он отвечает."},{"kind":"paragraph","text":"Он встаёт, ребёнок цепляется за его шею, ножками упирается в брючный ремень; он придерживает ребёнка рукой."},{"kind":"paragraph","text":"Ночь здесь стоит, мгла чёрная. Снег во тьме идёт, мгла белая. Громко крикнула вдалеке женщина:"},{"kind":"paragraph","text":"— Ты что, блядь, делаешь?! — потом тихо, и снова крик:"},{"kind":"paragraph","text":"— Ты охуел, блядь?!"},{"kind":"paragraph","text":"На ногах обессилевших побрёл он как мог к крикам, рукой держал ребёнка, другую сжимал в кулак. Уже ближе ­кто-то сквозь зубы сказал:"},{"kind":"paragraph","text":"— Ебись, сука."},{"kind":"paragraph","text":"Женщина крикнула:"},{"kind":"paragraph","text":"— Ты ебанутый, кого ебись, мороз под тридцать, нахуй!"},{"kind":"paragraph","text":"Быстрее побрёл, зашевелилась тьма, и он сказал:"},{"kind":"paragraph","text":"— Ничего не бойся."},{"kind":"paragraph","text":"Замахнулся во тьму рукой, ножки ребёнка болтались из-под свитера; он прижал ребёнка к себе крепче, замахнулся кулаком, снова замахнулся и снова."},{"kind":"paragraph","text":"— Мне не въеби смотри! — крикнула совсем близко женщина."},{"kind":"paragraph","text":"Содрогнулся в руках у него ребёнок, кулак ударил крепкое, треснули кости во тьме, ­что-то упало в снег и не двигалось."},{"kind":"paragraph","text":"— Так ему, хуеплёту, и надо, — сказала женщина. Похрустел снег, близко дышала женщина, тяжело дышала. Положила ладонь на его локоть, подняла руку и положила на плечо, пощупала шапку, бороду заледенелую. Отняла руку и сказала:"},{"kind":"paragraph","text":"— Нихуя себе, какой ты огромный, блядь. Откуда ты тут, нахуй, взялся?"},{"kind":"paragraph","text":"— Пришёл."},{"kind":"paragraph","text":"— Пришёл он, ёптить. Откуда ты пришёл?"},{"kind":"paragraph","text":"— Не помню, пьяный был."},{"kind":"paragraph","text":"— Т­о-то слышу, перегар пизданутый."},{"kind":"paragraph","text":"— Ты не ругайся так."},{"kind":"paragraph","text":"— А чё мне не ругаться, блядь нахуй?"},{"kind":"paragraph","text":"— Я с ребёнком."},{"kind":"paragraph","text":"— С каким, блядь нахуй, ребёнком?"},{"kind":"paragraph","text":"— У меня, здесь, подобрал."},{"kind":"paragraph","text":"— А нахуя тебе ребёнок? Вот вы тут все, сука, ебанутые! Этому ебаться в минус тридцать, этому ребёнок."},{"kind":"paragraph","text":"— Не ругайся, говорю! — громко он сказал. И тихо стало, больше не говорил никто."},{"kind":"paragraph","text":"— З­вать-то тебя как? — потом тихо сказала женщина."},{"kind":"paragraph","text":"— Леонид Семёнович."},{"kind":"paragraph","text":"— А ребёнок где?"},{"kind":"paragraph","text":"— Вот."},{"kind":"paragraph","text":"Леонид Семёнович пощупал во тьме, отыскал руку женщины и положил на свитер. Рука женщины под шерстью сжала коленку, погладила спину, вздрогнуло и сжалось под её рукой."},{"kind":"paragraph","text":"— Не бойся, крошечка, — сказала женщина."},{"kind":"paragraph","text":"Леонид Семёнович погладил ребёнка под свитером."},{"kind":"paragraph","text":"— И куда его теперь? — спросила женщина. — Пусть со мной будет, пока не рассветёт. — Тут уже не светает. — К­то-то всё равно встанет снег чистить утром. — Да, встают обычно, может, вынесут тебе похмелиться."},{"kind":"paragraph","text":"Свет загорелся в окне. Жёлтый свет, глухой, неяркий свет на снегу. Под светлым окном козырёк из бетона, под козырьком дверь. Стена высокая, длинная, окна, окна, и свет в окнах не горит."},{"kind":"paragraph","text":"Открылось светлое окно, мужчина выглянул, посмотрел кругом, бросил вниз лопату, вылез на козырёк, прыгнул в снег."},{"kind":"paragraph","text":"— Блядь, сколько ж ­намело-то, нахуй."},{"kind":"paragraph","text":"Мужчина взял лопату и у двери стал чистить от снега. А с неба снег падал снова, поднял мужчина голову, не видно ему было неба."},{"kind":"paragraph","text":"Леонид Семёнович от света сощурился, смотрел на женщину, смотрела женщина на Леонида Семёновича."},{"kind":"paragraph","text":"Шапка у Леонида Семёновича большая, борода седая заледенела. Шуба длинная лежит в снегу, под свитером держит ребёнка огромный Леонид Семёнович огромной ладонью."},{"kind":"paragraph","text":"Женщина ­когда-то была красивая, волосы у неё спутаны, в изодранном пальто от мороза прячется, в снегу её шапка лежит. А рядом с ними лежит мужчина, жопа голая и кровь идёт из лица: красный кругом снег."},{"kind":"paragraph","text":"Мужчина с лопатой их увидел, идёт в глубоком снегу, лопату следом тащит. Подошёл, глянул мельком на женщину, на Леонида Семёновича долго смотрел, потом на человека, что лежал в снегу."},{"kind":"paragraph","text":"— Он мёртвый, чи шо? — Не знаю. — Ёбнул его? — Не знаю. — А за шо? — Ебаться ему приспичило, — сказала женщина. — Как у них на таком морозе ­хуй-то стоит, — покачал головой мужчина. — Вот и мы про то, блядь нахуй."},{"kind":"paragraph","text":"— Не ругайтесь, ребёнок боится."},{"kind":"paragraph","text":"— Какой ребёнок, блядь?"},{"kind":"paragraph","text":"— Не матерись, у него ребёнок там, — показала женщина на живот Леонида Семёновича."},{"kind":"paragraph","text":"— Ты что, блядь, забеременел?"},{"kind":"paragraph","text":"Леонид Семёнович взял руку мужчины и потащил."},{"kind":"paragraph","text":"— Э, бля! — мужчина сказал. Леонид Семёнович руку мужчины положил на свитер. Под свитером вздрогнуло и сжалось."},{"kind":"paragraph","text":"— А, — сказал мужчина. — Ребёнку в тепло надо."},{"kind":"paragraph","text":"Мужчина вытер нос перчаткой."},{"kind":"paragraph","text":"— Надо значит надо."},{"kind":"paragraph","text":"— И покормить."},{"kind":"paragraph","text":"— Пойду жинку будить, накормит, — мужчина побрёл к двери, лопату тащил за собой. Обернулся мужчина, поглядел: Леонид Семёнович следом шёл."},{"kind":"paragraph","text":"Поравнялся мужчина с Леонидом Семёновичем, рядом брёл."},{"kind":"paragraph","text":"— Т­ы-то сам откуда? — Не местный. — И за каким ты сюда приехал? — Я не ехал. — А дитё где подобрал? — Там, в снегу. — Чьё же дитё? — Если никто искать не будет, заберу с собой. — Да я не о том, мне не жалко."},{"kind":"paragraph","text":"Леонид Семёнович посмотрел на мужчину, мужчина кивнул на дверь. Вошли в подъезд — тепло и сухо тут, — постучал Леонид Семёнович сапогами, потряс шубой, и мужчина с ним постучал, потряс. Мимо них другой мужчина прошёл, не взглянул. Вышел за дверь и встал у подъезда, закурил. К нему женщина подошла, протянула руку. Мужчина полез в карман шубы, достал коробку папирос и открыл перед женщиной, женщина взяла папиросу замёрзшими пальцами. Мужчина ей свою папиросу дал, она от неё прикурила."},{"kind":"paragraph","text":"— А-а-а, — потянула женщина и дым пустила."},{"kind":"paragraph","text":"— Замёрзла? — мужчина спросил."},{"kind":"paragraph","text":"— Да, подмёрзла. Так ещё меня тут чуть не выебли, хорошо мужик мимо шёл, отбил."},{"kind":"paragraph","text":"— Какой?"},{"kind":"paragraph","text":"— Да только что зашёл, у него ребёнок с собой, замёрз."},{"kind":"paragraph","text":"— Здоровый такой?"},{"kind":"paragraph","text":"— Да, охуеть какой здоровый."},{"kind":"paragraph","text":"— На вот, — мужчина достал из другого кармана шубы круглую металлическую флягу."},{"kind":"paragraph","text":"Женщина неуверенно протянула руку, взяла флягу. Мужчина отвинтил крышку и кивнул женщине."},{"kind":"paragraph","text":"Женщина сделала мелкий глоток, потом ещё, побольше. Выдохнула паром изо рта и ещё несколько раз глотнула жадно."},{"kind":"paragraph","text":"— Ну, хорош, — мужчина флягу забрал и сам отпил."},{"kind":"paragraph","text":"— Ух, заебись! — весело сказала женщина. Из подъезда вышли Леонид Семёнович и мужчина с лопатой. Женщина кивнула на флягу и сказала, глядя на Леонида Семёновича:"},{"kind":"paragraph","text":"— Коля, дай похмелиться ему."},{"kind":"paragraph","text":"Коля посмотрел на Леонида Семёновича и протянул ему флягу. Леонид Семёнович отпил, к фляге потянулся мужчина с лопатой."},{"kind":"paragraph","text":"— Э, вы так всё выжрете! — сказал сердито Коля и забрал флягу у Леонида Семёновича."},{"kind":"paragraph","text":"— Какой ты, сука, жадный стал, — обиженно сказал мужчина с лопатой."},{"kind":"paragraph","text":"Коля подержал холодную флягу, вздохнул и сказал: — Ну на, только не всё!"},{"kind":"paragraph","text":"Мужчина с лопатой взял флягу, дохнул паром и запрокинул её, горло его задвигалось."},{"kind":"paragraph","text":"— Пиздец, я это на весь день себе налил!"},{"kind":"paragraph","text":"— Ой, да заебал! Холод такой, имей совесть, — сказал мужчина с лопатой отдавая Коле пустую флягу."},{"kind":"paragraph","text":"— Совесть, блядь."},{"kind":"paragraph","text":"— Сейчас приду, — сказала женщина и вошла в подъезд."},{"kind":"paragraph","text":"Мужчины стояли у подъезда, курили Колины папиросы."},{"kind":"paragraph","text":"— Так чего ты здесь забыл? — спросил мужчина с лопатой. — Я здесь всё помню, — сказал ему Леонид Семёнович."},{"kind":"paragraph","text":"Долго потом молчали трое мужчин, докурили Колины папиросы, когда женщина вышла из подъезда: несла бутылку подмышкой, ещё две в руке, а во второй — хлеб в шелестящем пакете и газетка. Мужчина с лопатой вздохнул, поднял лопату и стал копать в сугробе. Долго копал, и все смотрели на него, а когда перестал копать, бросил лопату далеко."},{"kind":"paragraph","text":"Под снегом лавочка была, теперь на дне снежной ямы она стояла низкая и косая. В яму влезли мужчины и женщина. Женщина постелила газету на лавочку, вытащила хлеб, поломала на куски и положила сверху на шелестящий пакет, поставила на газету бутылки. Коля потянулся к бутылке, взял за крышку — щёлкнула. Все на него смотрели и молчали."},{"kind":"paragraph","text":"— Чё вы молчите, стаканы где?"},{"kind":"paragraph","text":"— Да давайте так, — сказал мужчина без лопаты."},{"kind":"paragraph","text":"— Нет, так не надо, стаканы надо, — сказала женщина и стала из ямы вылезать, опираясь на плечо Леонида Семёновича."},{"kind":"paragraph","text":"— Захвати ещё чего, а то принесла один хлеб."},{"kind":"paragraph","text":"Женщина зашла в подъезд, Коля открытую бутылку протянул Леониду Семёновичу."},{"kind":"paragraph","text":"— Подождём до стаканов, — Леонид Семёнович сказал."},{"kind":"paragraph","text":"Коля сел на лавку и вздохнул, отпил глоток. Дышали паром они на тусклый свет из окна."},{"kind":"paragraph","text":"— Не можешь ты минуту подождать! — выходя из подъезда, сказала женщина."},{"kind":"paragraph","text":"Она спустилась в яму, поставила стаканы на лавку, вытащила из кармана куриные яйца и положила на газетку рядом с хлебом. Взяла у Коли бутылку, расплескала водку по стаканам, подала всем по гранёному в руку и сама взяла."},{"kind":"paragraph","text":"Выпил мужчина, который снег копал, и посмотрел, как остальные пьют. Выпила женщина и смотрела усталыми глазами, как Леонид Семёнович пьёт, вытирает усы — лёд в бороде у него. Коля последний выпил, чмокнул и опустил голову на руки."},{"kind":"paragraph","text":"Женщина тонкими пальцами льдинки из бороды у Леонида Семёновича стала выбирать; тот смотрел спокойно, и не видно было, как он улыбается."},{"kind":"paragraph","text":"— Как тебя зовут? — Леонид Семёнович спросил."},{"kind":"paragraph","text":"— Дашей, — ответила женщина."},{"kind":"paragraph","text":"— Коль, ты чего? — мужчина без лопаты положил руку на Колю и потряс."},{"kind":"paragraph","text":"Коля помотал головой, но не поднял лица. Так и стал говорить, голос его глухо звучал, снег тихо на Колю падал."},{"kind":"paragraph","text":"— Как тут стемнело, так и уехала она. Долгое было лето, светило на людей солнце, на траву светило и на дома. А потом стемнело, и пошёл снег. Думали тогда, что закончилась вой­на, и кто в ней умер, тех будем хоронить. Но всё не до этого было, а ей, она красивая, умная, у неё наука своя, вот она и уехала, когда стемнело и пошёл снег. А мы ведь видели с ней, как началась вой­на. Мы поехали на велосипедах из дому, через поля жёлтые — обожгло их солнце. Нам с ней кожу тем летом тоже обожгло, и кожа у нас была красивая, особенно у неё. Она ехала впереди, у неё сухая высокая трава запуталась в колесе; она остановилась и смотрела на колесо, а я остановился и на неё смотрел, вспоминал, как первый раз её увидел под стеклянным куполом главной аудитории университета: она писала, а я читал, что она пишет. И вот я из её колеса достаю впутавшуюся траву, а она кладёт мне на затылок руку, я поднимаюсь и смотрю на её лицо — небо у неё позади. Я хочу её целовать, а в стороне города, за полем далеко яркое что-то, ярче дня светит, и в небо поднимается большая куча дыма, становится длинная, поднимается выше всех облаков серая, чёрная пыль и копоть. И когда уже закрыла куча дыма полнеба, подул ветер, упали мы и наши велосипеды, услышал я звук, как будто бы не снаружи он был, а внутри у меня, лежали мы тогда в траве с ней и смотрели друг на друга. Дашенька, налей выпить, а?"},{"kind":"paragraph","text":"Даша расплескала водку по стаканам. Почистила яйцо от скорлупы и подала Коле."},{"kind":"paragraph","text":"— Мы ведь даже не заметили, когда вой­на закончилась, она как будто началась, но так и не закончилась. Она смеялась, радовалась, и я радовался, когда смотрел на неё, вся вой­на так и прошла, но темноту она уже не смогла пережить и уехала, у неё ведь наука такая, ей свет нужен, она ищет древние клады, вазы, шкатулки, монеты. Она мне рассказывала: есть такой город, где вот так тоже поднялась куча пыли, когда взорвалась гора, и засыпало всех людей, они там так и остались — с монетами в руках, ­кто-то спал, лежал в траве."},{"kind":"paragraph","text":"— Эх, Колюшка, я тоже помню, как началась вой­на. Тогда и перестали люди умирать. Только те, что убило в вой­не, умирали, и то, — Даша налила водки в стаканы, отломила кусочек подмёрзшего хлеба. — У нас недалеко от дома лежал несколько недель взорванный гранатой и всё не умирал. Я его из болота граблями вытащила и сидела с ним, мне было шестнадцать лет. Я ему говорила: умирай, чего же ты мучаешься, у тебя вон ни рук толком, ни ног не осталось. А он одним глазом плакал и смотрел на меня. Говорит: как же умереть, когда небо такое здесь, воздух такой и ты, — это он мне, — ты, говорит, красивая такая. Я плакала и просила его умирать, а он не просил меня ни о чём, только говорил: иди домой, а я подышу и умру. Вот ведь как, началась та вой­на и люди перестали умирать, даже взорванные, как тот солдат."},{"kind":"paragraph","text":"Мужчина без лопаты вылез из ямы и пошёл искать в снегу лопату. Снег их в яме засыпал, уже совсем они замёрзли."},{"kind":"paragraph","text":"— Ты куда пошёл? — спросила Даша."},{"kind":"paragraph","text":"— Всякую хуйню рассказываете, — сказал мужчина и нашёл в снегу лопату."},{"kind":"paragraph","text":"— Леонид Семёнович, ты замёрз? — спросила Даша."},{"kind":"paragraph","text":"— Скоро уже пойду, — ответил Леонид Семёнович."},{"kind":"paragraph","text":"Из подъезда вышла женщина, за руку держала девочку, одетую в шубку, в валенки и в пуховый платок."},{"kind":"paragraph","text":"— Мужчина, девочка ваша?"},{"kind":"paragraph","text":"Леонид Семёнович обернулся и посмотрел из ямы на женщину и девочку."},{"kind":"paragraph","text":"— Да, моя."},{"kind":"paragraph","text":"— Я тут приодела её, у меня от старшей осталось."},{"kind":"paragraph","text":"— Спасибо вам, — Леонид Семёнович вышел из ямы и сел на колено перед девочкой, потянул за узелок шерстяного платка, погладил по щеке, девочка стеснительно отвела глаза, потом посмотрела с боязнью. Леонид Семёнович обнял девочку. Женщина стояла с ними рядом и смотрела на Дашу и Колю, они тоже смотрели, как Леонид Семёнович обнимает девочку."},{"kind":"paragraph","text":"— Мы пойдём, спасибо вам, — сказал Леонид Семёнович, выпустив девочку из рук. — Вы добрые люди, — Леонид Семёнович долго посмотрел на всех, и взял девочку на руки, и пошёл вдоль стены дома; скоро его не стало видно в темноте."},{"kind":"paragraph","text":"Над темнотой вдали пролетает свет. Свет улетает в темноту, возвращается из темноты. Перед пригородным автовокзалом горят белые фонари. В холодном свете у стены билетной будки сидит женщина и курит: положила лицо на руку, от лица её дым идёт. Собаки холодной ночью лежат друг на друге у входа в мотель «Казачка», смотрят собаки, как идёт сюда могучий Леонид Семёнович, несёт ребёнка."},{"kind":"paragraph","text":"Одна собака встала и налаяла на него. Остальные собаки поёжились и молча посмотрели на Леонида Семёновича. Собака больше"},{"kind":"paragraph","text":"не лаяла — пришла к ногам Леонида Семёновича и поглядела на него. Леонид Семёнович поглядел собаке в глаза, она махнула хвостом, Леонид Семёнович погладил собачью голову. Женщина встала со стула, собаки посмотрели на неё. Женщина подошла к Леониду Семёновичу и поглядела на него. Леонид Семёнович поглядел ей в глаза, женщина улыбнулась и отряхнула снег с одежды девочки."},{"kind":"paragraph","text":"— Автобус только что ушёл."},{"kind":"paragraph","text":"— Мы тогда зайдём погреться, — Леонид Семёнович поставил девочку на землю, взял её за руку и пошёл к двери мотеля «Казачка»."},{"kind":"paragraph","text":"Душно натоплено и гудят лампы дневного света в мотеле «Казачка». Никого нет, слышно, как на кухне из телевизора песню женщина поёт:"},{"kind":"paragraph","text":"— Плачет девочка в автомате, прячет в зябкое пальтецо всё в слезах и в губной помаде перепачканное лицо."},{"kind":"paragraph","text":"Леонид Семёнович отодвинул стул от стола, девочка сняла платок, расстегнула пуговицы на шубке. Леонид Семёнович снял с неё шубку и повесил на стул, девочка забралась на стул, посмотрела на календарь с красной гоночной машиной и покачала валенками."},{"kind":"paragraph","text":"— Мёрзлый след по щекам блестит, первый лёд от людских обид, поскользнёшься, ведь в первый раз бьёт по радио поздний час."},{"kind":"paragraph","text":"Сел за стол Леонид Семёнович и увидел угол телевизора — женщина там улыбалась и музыка играла, а потом другая женщина запела:"},{"kind":"paragraph","text":"— Блики на окошках, воробей за крошкой, мы глотками меряем наше время, радужные точки, смятые комочки, мы с тобой одни, хотя со всеми."},{"kind":"paragraph","text":"Девочка и Леонид Семёнович смотрели друг на друга и слушали песню. Хозяйка быстро выглянула из кухни, поглядела на телевизор и пошла к столу, за которым сидели девочка и Леонид Семёнович."},{"kind":"paragraph","text":"— Ты что будешь кушать? — спросил Леонид Семёнович. — Картошку, — сказала девочка."},{"kind":"paragraph","text":"Хозяйка подошла к столу и посмотрела на Леонида Семёновича."},{"kind":"paragraph","text":"— Нам одну картошку…"},{"kind":"paragraph","text":"— Какую? — спросила хозяйка Леонида Семёновича."},{"kind":"paragraph","text":"— Какую? — спросил Леонид Семёнович девочку."},{"kind":"paragraph","text":"— Варёную, — сказала девочка тихо, не поднимая глаз от облезлой скатерти в клетку."},{"kind":"paragraph","text":"— Варёную картошку, семь котлет и пол-литра вина, — Леонид Семёнович посмотрел на девочку, — а что ты будешь пить?"},{"kind":"paragraph","text":"— Я тоже вина хочу, — сказала девочка, крутя в руках пластмассовую зелёную солонку."},{"kind":"paragraph","text":"— Значит, не пол-литра, а литр, — сказал Леонид Семёнович."},{"kind":"paragraph","text":"Хозяйка посмотрела на девочку, потом на Леонида Семёновича, смотрела, как он запустил пальцы в волосы, седые, густые и длинные. Ничего больше не сказала хозяйка, ушла на кухню, оттуда пела женщина из телевизора:"},{"kind":"paragraph","text":"— Да, конечно, сложно, но ещё возможно, сердце прошептало, я сказала, наверно, в следующей жизни, когда я стану кошкой на-на, на-на."},{"kind":"paragraph","text":"— Сколько тебе лет? — спросила девочка."},{"kind":"paragraph","text":"— Триста шесть, — сказал Леонид Семёнович."},{"kind":"paragraph","text":"— А мне просто шесть. А тебе какая музыка больше нравится: со словами или без слов?"},{"kind":"paragraph","text":"— Я давно музыку не слушал, уже не помню, какая нравилась. А тебе нравится, которая здесь играет?"},{"kind":"paragraph","text":"— Да, здесь хорошая, слова красивые."},{"kind":"paragraph","text":"— Ты умеешь читать?"},{"kind":"paragraph","text":"— Нет, не умею."},{"kind":"paragraph","text":"— Надо тебе научиться, если тебе нравятся песни со словами."},{"kind":"paragraph","text":"— Почему?"},{"kind":"paragraph","text":"— Потому что читать слова интересно, — Леонид Семёнович посмотрел, как из кухни вышла хозяйка. Она несла две тарелки одной рукой, в другой несла стеклянный графин с красным вином и два гранёных стакана на пальцах."},{"kind":"paragraph","text":"Девочка поёрзала на стуле, когда хозяйка ставила перед ней картошку-пюре, наваленную на тарелку дымящимися буграми. На тарелке у Леонида Семёновича гурьбой лежали блестящие котлеты, одну из них он поддел вилкой и положил в девочкину картошку. Леонид Семёнович поставил стаканы рядом и налил в них вино до половины. Девочка тут же взяла один из стаканов двумя руками и поднесла к носу. Хозяйка не уходила от них: отвернувшись от стола, смотрела в сторону кухни. Потом она быстро взглянула, как Леонид Семёнович с девочкой пьют вино, и ушла."},{"kind":"paragraph","text":"По залу пробежал свет от фар приехавшего автобуса. Леонид Семёнович расплачивался у прилавка, а девочка смотрела из окна на чёрный автобус: как собаки лают на него, как отбегают собаки от открытой двери, как выходит из автобуса и закуривает сигарету старик-­водитель."},{"kind":"paragraph","text":"Леонид Семёнович подошёл к девочке и накинул ей шубку на плечи."},{"kind":"paragraph","text":"— Скоро поедем туда, где тепло."},{"kind":"paragraph","text":"Девочка обернулась и посмотрела на Леонида Семёновича, высоко подняв голову."},{"kind":"paragraph","text":"— Я буду жить там с тобой?"},{"kind":"paragraph","text":"Леонид Семёнович взял из руки девочки пуховый платок и покрыл ей голову. Девочка улыбнулась, а Леонид Семёнович поцеловал её улыбку."},{"kind":"paragraph","text":"— Да, будем там жить вместе, — сказал Леонид Семёнович."},{"kind":"paragraph","text":"В автобус сели только они одни. Водитель ещё немного подождал, сказал ­что-то женщине через окошко кассы и сел в автобус. Он завёл мотор, оглянулся в салон, увидел взгляд Леонида Семёновича и отвернулся."},{"kind":"paragraph","text":"— Нам там в наших шубах жарко будет, если там тепло, — сказала девочка."},{"kind":"paragraph","text":"— Купим тебе платье, голубое, — сказал Леонид Семёнович."},{"kind":"paragraph","text":"— А тебе белую рубашку, — сказала девочка, устраиваясь на коленях Леонида Семёновича спать. Уже сквозь сон она сказала:"},{"kind":"paragraph","text":"— И бороду тебе побреем."},{"kind":"paragraph","text":"Тьмы не стало, когда проснулся Леонид Семенович. По дороге текли ручьи воды, таял снег в полях. Когда девочка проснулась, кругом были пески, редко видны были обожжённые пальмы."},{"kind":"paragraph","text":"Автобус высадил их на остановке «Универмаг». Леонид Семенович и девочка держали в руках свои шубы, шли по занесённым песком улицам, никого не встречая по пути. Они вошли в универмаг, магазин «Голубые платья и белые рубашки» был открыт. Они купили одежду, продавщица в высоком тюрбане, чернокожая, улыбалась девочке, смеялась над Леонидом Семё-"},{"kind":"paragraph","text":"новичем, который, стоя на одном колене, помогал девочке надеть туфельку."},{"kind":"paragraph","text":"— Веве ни бабу вакучекеша! — смеялась молодая чернокожая продавщица."},{"kind":"paragraph","text":"Леонид Семёнович и девочка вышли из универмага и зашагали по улице. Они увидели впереди большой котлован, в нём бурлила вода, в воду был опущен трос; двое чернокожих юношей спорили на странном языке."},{"kind":"paragraph","text":"Леонид Семёнович смотрел на них: они говорили друг другу о ­чём-то, как будто в стихах, а трос в воде стал быстро вздрагивать. Девочка сказала:"},{"kind":"paragraph","text":"— Там человек под водой."},{"kind":"paragraph","text":"Леонид Семёнович подбежал к котловану, схватил трос и стал рывками поднимать его, молодые негры смотрели на него испуганно."},{"kind":"paragraph","text":"Леонид Семёнович выбрал последний метр троса и схватил под руки человека, вытащил из воды и положил на жёлтую размокшую глину, которая здесь была всей землёй. Молодая женщина с глиняной амфорой в руке кашляла, выплёвывая грязную воду, глаза её, широко раскрытые, смотрели на Леонида Семёновича и девочку, которая взяла у неё из рук тяжёлую амфору и сразу же уронила. Амфора раскололась, и в глиняной каше, которой она была наполнена, показались золотые монеты. Женщина кашляла, всхлипывала, хватала ртом воздух, а руками обнимала девочку. Негры смотрели на Леонида Семёновича и бормотали один другому:"},{"kind":"paragraph","text":"— Хую бабу ни мкубвакама темпо."}]'::jsonb,
  '2021-12-30T12:00:00.000Z'
)
