INSERT INTO "Articles" (slug, title, author_id, cover_path, cover_blur, cover_width, cover_height, excerpt, content_blocks, published_at)
VALUES (
  'mrd2-chaepitie',
  'Чаепитие',
  (SELECT id FROM "Authors" WHERE name = 'Николай Старообрядцев' ORDER BY id LIMIT 1),
  'mrd2/mrd2-chaepitie.jpg',
  'data:image/jpeg;base64,',
  1200,
  690,
  'Софья Николаевна сидела в небольшом мягком креслице у окна и синей ниткой вышивала изящный вензель на белом платочке, натянутом на пяльцах. В дверь комнаты постучали. Она отложила рукоделие, опустила ноги в тёплые тапочк',
  '[{"kind":"image","path":"mrd2/mrd2-chaepitie.jpg","caption":null},{"kind":"paragraph","text":"Софья Николаевна сидела в небольшом мягком креслице у окна и синей ниткой вышивала изящный вензель на белом платочке, натянутом на пяльцах. В дверь комнаты постучали. Она отложила рукоделие, опустила ноги в тёплые тапочки, отороченные мехом. Бесшумно ступая по мягкому ковру, подошла к двери и, повернув блестящую медную ручку, открыла её. Григорьев, специалист отдела планирования, работавший с Софьей Николаевной на одном заводе, стоял в коридоре и теребил в руках свою серую шляпу, энергично разминая нервными пальцами и без того истёртые поля."},{"kind":"paragraph","text":"— Добрый день, Софья Николаевна! Шёл мимо и увидел ваше окно. Взбрело в голову: дай зайду, поздороваюсь, — затараторил Григорьев. — Помните, давеча проходили с вами после работы, вы мне ­окна-то ваши и указали."},{"kind":"paragraph","text":"— Заходите скорее, Игнатий Петрович, — приветливо улыбаясь, Софья Николаевна отошла от двери вглубь комнаты,"},{"kind":"paragraph","text":"приглашая Григорьева. — Очень правильно сделали, что заглянули. А я как раз чай пить собиралась."},{"kind":"paragraph","text":"— Да ведь я ненадолго, всего только на минуточку, — Григорьев широким шагом вступил в комнату. — Предложение ваше, впрочем, приму с удовольствием величайшим, но только по причине того, что за чаем буду не так неловок, как без чаю, хоть и пристыжён уже неприличной пустотой своих рук, отсутствием, так сказать, сладостных продуктов к столу в них, моих руках, то есть, для непосредственного вручения вам, Софья Николаевна."},{"kind":"paragraph","text":"— Проходите же, снимайте туфли и дайте вашу шляпу, — пролепетала Софья Николаевна, оторопевшая от нелепой тирады Григорьева, но и не без некоторого удовольствия, вызванного его смущением, бросающимся в глаза. — Садитесь к столу, буду поить вас чаем."},{"kind":"paragraph","text":"Но прежде чем заняться сервировкой стола, Софья Николаевна подошла к креслицу и как можно небрежнее, стараясь случайно не возбудить любопытства Григорьева, убрала своё рукоделие на широкий подоконник и немного прикрыла занавески так, чтобы одна из них скрыла вышитое."},{"kind":"paragraph","text":"Немного левее окна была установлена простая деревянная ширма. Она была предназначена для отделения некоего пространства, выделенного из комнаты для приготовления пищи и удовлетворения простейших гигиенических нужд. За ширмой этой помещалась электрическая плитка с чайником, маленький рукомойник, зеркало в узорчатой гипсовой рамке, несколько кастрюль и сковород, а также небольшой шкафчик, содержащий в себе, по всей видимости, мелкие предметы кухонного хозяйства."},{"kind":"paragraph","text":"В то время как Софья Николаевна, скрывшись за ширмой, извлекала из шкафчика чашки и бумажные свёртки, в которых хранились запасённые на случай гостей лакомства, Григорьев"},{"kind":"paragraph","text":"принялся с грохотом придвигать к журнальному столику, стоявшему подле креслица, столь же аккуратную маленькую табуреточку, отставленную в угол комнаты. Излишне шаркая ногами и ежесекундно оборачиваясь, придавая своими кривляниями процессу придвижения табуретки к столу как бы чрезвычайную деликатность, Григорьев улучил момент и загнул голову в сторону окна, чтобы увидеть прикрытую занавеской вышивку, сокрытие которой он, разумеется, приметил. На белой ткани платочка, туго натянутого на пяльцах, была изображена недовышитая латинская буква «S», затейливо обрамлённая цветочными лепестками."},{"kind":"paragraph","text":"— Вы такой высокий… Должно быть, с такими длинными ногами будет не очень уютно сидеть в такой крошечной обстановке, — сказала Софья Николаевна, появившаяся из-за ширмы с горячим чайником и тарелкой, в которой лежали козинаки и большой кусок щербета."},{"kind":"paragraph","text":"— Нет-нет, не беспокойтесь, я устроился совершеннейшим образом уютно, — заторопился Григорьев. — Я, знаете ли, не охотник до пиршеств в тронных залах, а вот такие маленькие комнатки, почти кукольные комнатки, — это, откроюсь вам, моя тайная страсть!"},{"kind":"paragraph","text":"— Это почему же? — рассмеялась Софья Николаевна, оторопевшая уже во второй раз и даже остановившаяся посреди комнаты с двумя фарфоровыми чашками, расписанными гжелью. — Какие такие кукольные комнатки?"},{"kind":"paragraph","text":"— Я может и сдуру ляпнул про эти комнатки, Софья Николаевна, — продолжал лепетать Григорьев, — просто прольститься перед вами желая в извинение за неожиданный визит свой. А комнатки эти — сущий пустяк. Люблю просто, как царь Пётр, при великом росте мелкие объёмы оккупируемых пространств. Пугаюсь лишь только мысли, будто это во мне из-за желания казаться больше, чем я по факту своего существования являюсь. Или даже в скорлупке какой оказаться хочется, всё равно, что был бы я невылупившийся птенец."},{"kind":"paragraph","text":"— Глупости какие, Игнатий Петрович! Птенец, скажете тоже, — разливая по чашкам горячий чай, возмутилась Софья Николаевна, — при ­вашем-то росте и вашем значении на заводе, — при этих словах Григорьев невольно приосанился и поправил узел галстука, до того безобразнейше висевший. — Вы даже скромнее, чем от вас можно было бы ожидать! Пейте, пожалуйста, чай. С мятой, мама из деревни привезла, очень вкусно."},{"kind":"paragraph","text":"— М-м-м, и правда, восхитительный чай, — отпив немного, прошептал Григорьев, — давно не пивал такого. Вкусней любого вина, ей богу, Софья Николаевна."},{"kind":"paragraph","text":"— А вы вино любите? — удивлённо, но тут же смутившись, спросила Софья Николаевна. — То есть я хотела сказать, вкус вина умеете понимать?"},{"kind":"paragraph","text":"— О, нет совсем, — расхохотался неожиданно громко Григорьев. — Мне до такой изысканности далеко шагать. Про вино это я так, для красного словца. Я ведь спиртного почти совсем не приемлю. Расслабляет мысль, знаете ли. Поэтом стать можно. Могу пива светлого выпить кружку после бани, уж больно хорошо, но больше — ни-ни!"},{"kind":"paragraph","text":"— Строгий вы человек, Игнатий Петрович, — надломила щербет Софья Николаевна. — А я вот люблю поэзию. Ахматову, Гумилёва, Есенина очень. Мне кажется, поэзия делает человека внутренне светлее…"},{"kind":"paragraph","text":"— Позвольте вам возразить, Софья Николаевна, — перебил вдруг Григорьев. — То есть не совсем возразить категорично, а как бы возразить, одновременно соглашаясь. Мыслится мне, будто просто есть рычажок некий в человеке, как бы кнопочка золотая, нажмёшь — и светлее становится. И любит так человек просветляться, искать, чем поднажать на эту кнопочку, невзначай как бы поднажать, будто прислониться к холодной твёрдой стене и спину почесать усталую. Есть ловкость рук — фокусами-­покусами обзывается в цирках, а есть ловкость человеческого языка — называют поэзией или высоким штилем. А я другое поэзией называю. Вот"},{"kind":"paragraph","text":"помните, после работы у проходной мы случайно встретились и пошли неожиданно по одной дороге? Вы домой пешком всегда ходите, да и я в тот вечер пройтись решил — уж больно погода хорошей была. И вот идём мы, значит, в одном направлении, но поодаль друг от друга. Не знакомы близко вроде бы, хоть и видимся. Помните? А что дальше было, припоминаете? Старушечка горбатенькая. Идёт-ковыляет, подходит к людям и на хлебушек кротко спрашивает. Смотрят на неё люди влажными, умными глазами. Кто даст копеечку, кто десять копеечек, и пошёл прочь — от забот подальше. Интеллигентным людям вредно старушечьими эмоциями пропитываться. Вдруг замечаю я (и вы замечаете) как проходит мимо старушечки этой хулиган. Сразу видно: злодей отпетый, потому как морда протокольная, глаза навыкате, папироса во рту дымит. Сближается морда эта с бабулечкой нашей. Ну, думаю, не получишь ты, старая, копеечки, даже не проси. А чего доброго, так и собранное потеряешь. Далее — гром средь ясного неба: обращается старушка к бандиту этому, подай, дескать, на хлебобулочное изделие, мил человек. Ну, думаю: оторвёт старухе башку и в канаву выкинет такой мил человек. Ан нет! Берёт хулиган изо рта цигарку и в лужицу бросает, а другой рукой выгребает из кармана всё, что есть, и передаёт во владение бабушкино. Да говорит напоследок: благослови, мать. «Мать», сказал, представляете! Перекрестила его старушка, да тут же и прослезилась, а хулиган развернулся и прочь пошёл широкими шагами, чуть не побежал. Вот ­тут-то я оторопел. Подхожу к вам и говорю: позвольте до самого дома идти с вами рядом, потому как жизнь невыносимо прекрасна! Тогда и ощутил я, будто Пушкин во мне зардел, да не тот Пушкин, что с ногтями, что с картинки лукаво смотрит, а другой Пушкин — подземный что ли, глубинный Пушкин. Скрутило меня тогда бессовестно. Вот такое состояние и хочется мне именовать поэтикой бушующей и радостной жизни, а не бумаги и пыли междустраничной."},{"kind":"paragraph","text":"Всё то время, пока Григорьев рассказывал, Софья Николаевна держала чашку чая в руках, но отпить не решалась, боясь показаться невежливой."},{"kind":"paragraph","text":"— Странно вы рассуждаете, — сказала она, когда Григорьев наконец умолк. — Я тоже озадачена была этим происшествием, но ­каким-то смешным показалось мне оно. Нет, не смешным, ведь смеяться тут не над чем. Тут не смеяться надо. Обидно просто, что наши сограждане так равнодушны к старикам, к чужим проблемам. Особенно когда так легко помочь. Будто брезгливость какая к чужому горю. Настолько, что уличный хулиган порой кажется человечнее порядочного гражданина. Изгой оказывается человеком, хотя считают, что должно быть наоборот. Но отчего вы так воодушевились, именно, как вы говорите, до такой степени, что в вас Пушкин зардел? И при чём здесь Пушкин? Этого я совсем не могу понять."},{"kind":"paragraph","text":"Григорьев отломил большой кусок шербета, отправил его в рот, торопливо прожевал и запил большим глотком чая, осушив чашку практически до дна."},{"kind":"paragraph","text":"— А вы любите вышивать? — неожиданно резко спросил он, с ­каким-то даже усилием поставив чашку на столик."},{"kind":"paragraph","text":"— Вышивать? — недоумённо переспросила огорошенная Софья Николаевна. — Я вышиваю иногда мулине, — ответила она, напрасно пытаясь казаться невозмутимой."},{"kind":"paragraph","text":"— А что такое мулине, Софья Николаевна? — грубо выпалил Григорьев, требовательно наклонившись вперёд."},{"kind":"paragraph","text":"— Мулине? Шитьё это такое… нить… и зачем, зачем вам это, господи, — пальцы Софьи Николаевны задрожали, она поспешно спрятала руки."},{"kind":"paragraph","text":"— Господи! Вы упомянули имя Господа нашего? — перешёл почти на шёпот Григорьев, но чувствовался в этом и ­какой-то"},{"kind":"paragraph","text":"восторг, будто он только и ждал, что имя это будет упомянуто. — Господа нашего Иисуса Христа, исковерканного, освежёванного и препарированного грязными сальными руками обиженных жизнью диссидентов и отупевших от мелкой злости кухарок? Вера в которого приносит успокоение, снимает неприятный осадок от общения с руководством предприятия? Того самого, вера в которого позволяет двигать горы силой мысли, но не для того, чтобы вскрывать полезные ископаемые, таящиеся в глубине наших святых недр, и не для того, чтобы давить врага, который не дремлет, который нас гнетёт ежесекундно и неустанно, как клещ или лесной комар, а единственно только для фокуса! — перейдя почти на восторженный крик, Григорьев снова зашептал, на этот раз злобно шипя: — А как же кукольные комнаты, такие мягкие, такие уютные, что даже захочешь, то и тогда не сможешь себя тяжело травмировать в такой комнате? Мне, Софья Николаевна, думается, что в такой вот комнатке, как ваша, не достаёт ­какого-то постамента, тяжёлого и с острыми твёрдыми углами, желательно из белого мрамора, и почтенного старичка на стульчике, светлоокого такого старичка — мудренького и возвышенного, будто всю жизнь он писал только оды одни, да представлял при этом, будто туфельку императрицы Екатерины Великой поцеловал кротко. И вот взять рукой стульчик за ножку и неожиданно так выхватить из-под старичка, чтобы он упал вдруг и седой головушкой о край постамента ударился до крови, и схватить со стола, с блюдечка, пирожочек мягонький, и пихать в рот старичку, и приговаривать: «А что это вы, милостивый государь, пирожочек не кушаете? Али недостаточно мягок он? Недостаточно сладок для вас?» — заканчивая тираду, Григорьев весь уже извивался на табуретке и, скрючивая пальцы, изображал, как он засовывает пирожок в рот воображаемого старичка. На лице же его застыл такой спазм, будто это было лицо самого этого несчастного умирающего старичка."},{"kind":"paragraph","text":"Софья Николаевна резко встала и, выйдя на середину комнаты, скрестила на груди руки."},{"kind":"paragraph","text":"— Игнатий Петрович, — сдерживая гнев и слёзы, официально сказала она. — Я не понимаю и не желаю понимать, почему вы всё это говорите. Я совсем другого ожидала от вас. Прошу вас, если я обидела вас ­чем-то… простите. Не смею вас задерживать более! — проговорив это, Софья Николаевна закрыла лицо руками и отвернулась."},{"kind":"paragraph","text":"Григорьев вдруг снова успокоился, отвернулся к окну и пальцем руки начал было непроизвольно ковырять недоеденный щербет, но тут же отдёрнул его, поняв, видимо, нелепость и карикатурность своего занятия."},{"kind":"paragraph","text":"— Софья Николаевна, простите, что я устроил здесь весь этот фарс, — настойчиво, но вкрадчиво и примирительно заговорил Григорьев. — Но можно ли слушать такое? И зачем? Зачем слушать человека? Что такое вообще говорящий человек? Имеем ли мы право говорить друг другу? Я не знаю, я просто хочу сказать… я совсем не то имел в виду… будто жертвоприношение нужно совершить, чтобы другой человек посмотрел на тебя и увидел тебя, а не своё отражение, будто мы все из зеркального стекла и нужно вдребезги разбиться, чтобы не отражать, чтобы пропал этот блеск, этот вторичный искусственный свет, совсем лишний свет. Не от того ли это, что только в смерти есть соединение. Из небытия всё вышло, и всё уйдёт в небытие, а бытие, мыслимое существование — это ад на земле, ад одиночества."},{"kind":"paragraph","text":"Софья Николаевна отняла руки от лица и взглядом, полным страдания и неожиданного тепла посмотрела на Григорьева."},{"kind":"paragraph","text":"— Я понимаю вас, Игнатий Петрович, — сказала она. — Я и сама давно уже думала об этом, но не могла высказать. Извините меня, что я вас испугалась, что я обозлилась на вас и подумала, что вы меня оскорбить пришли."},{"kind":"paragraph","text":"— Софья Николаевна, не говорите так, прошу вас, заклинаю вас, — Григорьев как будто весь обмяк, стёк с табуретки на пол и пополз на четвереньках в сторону Софьи Николаевны."},{"kind":"paragraph","text":"— А я ведь и шёл к вам, чтобы оскорбить вас, чтобы надругаться, ноги об вас вытереть, — Григорьев встал на колени и обнял ноги Софьи Николаевны, прижавшись головой к животу. — Ведь давно следил за вами, год почти, всё думал: «Вот она ходит и ждёт, когда ноги об неё вытирать придут, кровью её пыль придорожную с сапог смывать будут». Но я был дураком, я ужасно, грязно ошибался, вижу это теперь! Я умереть, погибнуть хочу теперь. Умереть и воскреснуть, чтобы каждый день заново рождаться, снова умирать и снова воскресать!"},{"kind":"paragraph","text":"Григорьев схватил Софью Николаевну и стал жадно целовать через одежду, увлекая на пол."},{"kind":"paragraph","text":"Через пятнадцать минут Григорьев встал и, застёгивая брюки, прошёл к двери, туда, где на крючке висели его плащ и шляпа. Пошарив в плаще, Григорьев извлёк бутылку водки и, откупорив, жадно отпил из неё."},{"kind":"paragraph","text":"— Есть в этом ­что-то ницшеанское, на мой взгляд, в хорошем глотке русской водки, — поморщившись, сказал Григорьев, не глядя на Софью Николаевну, которая тем временем села в креслице, подобрала ноги и отвернулась к окну. — Хороший сегодня день. На теплоходах хорошо по реке кататься. Вы любите теплоходы, Софья Николаевна?"}]'::jsonb,
  '2021-12-30T12:00:00.000Z'
)
