INSERT INTO "Articles" (slug, title, author_id, cover_path, cover_blur, cover_width, cover_height, excerpt, content_blocks, published_at)
VALUES (
  'mrd2-tabornye',
  'Таборные',
  (SELECT id FROM "Authors" WHERE name = 'Ольга Иванова' ORDER BY id LIMIT 1),
  'mrd2/mrd2-tabornye.jpg',
  'data:image/jpeg;base64,',
  1200,
  663,
  'Снявшийся поутру табор приближался к городским окраинам. До осени было ещё далеко, однако по ночам стало чуть прохладнее. Можно было продолжать кочевье, двигаться на юг, ближе к тёплому морю.',
  '[{"kind":"image","path":"mrd2/mrd2-tabornye.jpg","caption":null},{"kind":"paragraph","text":"Снявшийся поутру табор приближался к городским окраинам. До осени было ещё далеко, однако по ночам стало чуть прохладнее. Можно было продолжать кочевье, двигаться на юг, ближе к тёплому морю."},{"kind":"paragraph","text":"Зимовали обычно у крестьян в прибрежных сёлах, чаще хорошо знакомых по прежним годам кочевья. Если не удавалось договориться с тем, кто пускал на постой, отыскивали брошенный домишко, надворную избушку, флигель, да хоть сарай. Утепляли как могли, ставили железную печурку, которую возили с собой в открытой телеге. Прежде табор перед зимовкой ничто не могло остановить или повернуть назад."},{"kind":"paragraph","text":"Если женщина рожала, она с семьёй и повитухами догоняла табор после родов. Её ждали, встречали песнями, ей готовили лучшую еду, ставили хорошую маленькую палатку, в которой мать кормила младенца, укрывала его от непогоды и чужих взглядов: не сразу нового цыганёночка знакомили с соплеменниками,"},{"kind":"paragraph","text":"до сорокового дня старались особо не раскрывать, не показывать никому, кроме самых близких."},{"kind":"paragraph","text":"Когда смерть настигала таборного бродягу, останавливались до похорон. Хоронили на кладбище, если оно было недалеко. Место выбирали поближе к дороге. А если кладбища поблизости не случалось, так выкапывали могилу просто на обочине. Покойника заворачивали в одеяло, на котором он спал в последние дни жизни. Ставили небольшой деревянный крест. Читали молитвы, обещали покойному: пойдём ещё по этой дороге — навестим тебя. А если наши пути мимо лягут, то другой табор пойдёт. Православные шапку снимут, поклонятся, перекрестятся."},{"kind":"paragraph","text":"На могиле устраивали скромные поминки: курили трубки, рассказывая друг другу истории про то, каким замечательным человеком был умерший. Было вино — мужчины выпивали, пуская чашу по кругу. Женщины и дети довольствовались чаем с сушёной вишней, черносливом, курагой. На закуску ставили сывьяко — печённый в золе под костром пирог с яблоками и изюмом."},{"kind":"paragraph","text":"Всё действо занимало не больше двух часов. После похорон сразу снимались с места: жить рядом с могилой не позволяли старые обычаи. На этот раз нашёл покой в придорожной могиле давно хворавший Артюх. Он был не молодой, но и не старый, имел хорошую семью, в которой младшая дочь была ещё совсем маленькой, а старший, уже женатый, ждал первенца."},{"kind":"paragraph","text":"Жена Артюха, Марга, привезённая из румынского табора, была краснощёкой, пышногрудой, проворной и шумной. Она говорила хоть и на близком, но всё же ином наречии, а иногда переходила на румынский. Софье, двоюродной племяннице Артюха, это было интересно, и она часто просила Маргу спеть"},{"kind":"paragraph","text":"на румынском и объяснить смысл песни или спрашивала, как по-румынски будет то или иное слово."},{"kind":"paragraph","text":"Артюх всегда понимал жену, потому что любил её без памяти. Родила Марга пятерых детей. Старшие вышли лицом в мать, а характером в Артюха: сдержанные, молчаливые, серьёзные."},{"kind":"paragraph","text":"Анфим унаследовал от отца охотничье ружьё и страсть бродить по лесам в поисках добычи, которая не раз выручала табор в голодные дни. Когда он был ещё подростком, отец брал его с собой на охоту, учил стрелять, ставить силки и плашки, читать следы и слушать лесные голоса. Парень постиг эту науку в совершенстве; незадолго до смерти отец сказал ему, что теперь есть на кого оставить табор: охотник есть, к нему ружьё. Голодными не будут. Да ещё и запас хороший был: Артюху, любившему мену, удалось ­как-то обменять казачье седло на целый ящик заводских охотничьих патронов."},{"kind":"paragraph","text":"Второй, Ульян, больше всего на свете любил музыку. Скрипка досталась ему от чужого дедушки: ­какое-то время вместе с Артюховой семьёй кочевал подобранный на ярмарке старик. Он отстал от своего котлярского табора, угодив в тюрьму за кражу поросёнка, а выйдя вместе с неразлучной скрипкой, сильно захворал: всё время кашлял, бесконечно занимая себя музыкой. От него Ульян научился играть, и когда дедушка покидал табор, встретив наконец родню, он оставил мальчику скрипку, сказав:"},{"kind":"paragraph","text":"— Мне уж недолго осталось. Ты теперь играй, Ульяшко. У тебя ладно выходит. Да смотри, не бросай скрипочку, она живая!"},{"kind":"paragraph","text":"Ульян был по-цыгански красив: большеглаз, широкоплеч, высок и строен, но характером больно строг и суров. Как вырос, стал ссориться со всеми, придираясь к каждой мелочи и не перенося"},{"kind":"paragraph","text":"чужих ошибок. И однажды, так же из-за мелочи, из-за глупости, распаляясь в споре и распаляя соперника, подрался со своим двоюродным братом Силкой, старше его на два года. Парни едва не покалечили друг друга, и ни один не оказался в драке сильнее и ловчее другого. Но когда их растащили и утихомирили, Ульян прокричал, что раз его не признают правым, он покидает табор."},{"kind":"paragraph","text":"Так и случилось: ушёл со своей скрипкой тем же вечером, голодный — не стал обедать со всеми! — гордый, несогласный. Слышали, что приглянулся в городе ­какой-то торговке, вдвое старше его, и живёт в её доме, как сыр в масле катается. Иногда Артюх и Марга просили Софью погадать, как там их непутёвый сын. Выходило, что у него всё хорошо, живёт без горя. Но после его ухода стал хворать отец. И ничего не смогли сделать ни старые знахарки, ни Софья, как ни старались. Болел и чах помаленьку Артюх, пока не позвала его к себе смерть. А Ульян так и не появился в родном таборе."},{"kind":"paragraph","text":"Третий сын, Лога, едва подрос, в любом селе, где бы ни остановились, начал бегать в церковь, научился молиться не на цыганском языке, а по-поповски. Лет двенадцать ему было, когда он принёс псалтырь, купленный у местного дьячка. Поступок этот показался странным обитателям табора. Никто из цыган не стал бы тратить деньги на книгу. И красть никто не стал бы, в церкви грешить! Да и зачем цыганам книга? Костёр разжигать? Но настоящее удивление вызвало то, что парень, как оказалось, умеет читать."},{"kind":"paragraph","text":"В таборе было двое грамотных: Софья да старый Пров, научившийся чтению и письму в Варшавской тюрьме, где в молодости провёл четыре года. Знал и по-русски, и по-польски, и по-румынски. А вот теперь ещё и Лога. Он и раньше просил"},{"kind":"paragraph","text":"Прова научить его, да тот по старости уже видел плохо. А Софью попросить Лога стеснялся."},{"kind":"paragraph","text":"— Кто тебя научил? — пытали его цыгане."},{"kind":"paragraph","text":"Он отвечал:"},{"kind":"paragraph","text":"— Попы, дьяки да прихожане. Тот маленько покажет, другой…"},{"kind":"paragraph","text":"У костров часто вместо песен стали звучать притчи и рассказы о Христе, после которых цыгане порой впадали в тихую задумчивость. Логу прозвали в таборе Дьячком."},{"kind":"paragraph","text":"Алек родился нездоровым. Большеглазый, тонкорукий и тонконогий, почти до четырёх лет он не ходил, потом начал передвигаться, кособочась. Речь его до поры была невнятной, но голос был сильный и звонкий. Запевал — всё замирало вокруг, казалось, даже птицы притихали послушать цыганёнка. Софья жалела мальчишку больше других, всегда старалась приберечь для него сладкий кусочек, укрыть его потеплее, ­чем-то ему помочь. Он платил ей робкой привязанностью. Они будто бы чувствовали друг в друге нечто общее."},{"kind":"paragraph","text":"Младшая, кучерявая быстроглазая Патринка, певунья, плясунья, всеобщая любимица, опекала больного братца так, будто бы это она была старшей, а не наоборот. Она помогала ему встать с земли, поддерживала его, когда нужно было идти по камням и кочкам, освобождала для него удобное местечко в палатке или в кибитке, вовлекала его в детские игры."},{"kind":"paragraph","text":"Однажды, когда Софья занималась штопкой ветхого полога, напевая и аккуратно подрезая разлохмаченные края прорех острым ножом, Алек подошёл к ней кривой неуклюжей поход-"},{"kind":"paragraph","text":"кой, торопясь настолько, насколько у него это получалось, и стал горячо просить о ­чём-то. Не сразу разобрала она его путаную речь. Мальчик звал её с собой к берегу. Она взяла его за руку, помогая передвигаться, и они вместе пошли туда, куда он тянул её, вдоль реки, не по тропе, продираясь через густой прибрежный кустарник."},{"kind":"paragraph","text":"Когда Софья пыталась направить Алека более лёгким путём, он сопротивлялся и мотал головой. Вскоре в кустах послышались непонятные звуки — будто тяжёлое дыхание, пыхтение, шуршание. А затем сквозь ветви кустарников стало видно ­что-то большое, сероватое с рыжиной — ­какой-то зверь. Алек крепче вцепился в руку Софьи, призывно оглядываясь на неё. Когда они приблизились, животное — это был молодой олень, — заметалось, тяжело дыша, однако не убежало."},{"kind":"paragraph","text":"Софья велела Алеку остановиться, а сама приблизилась к оленёнку. Его задняя нога запуталась в небольшом обрывке старой рыболовной сети, затянувшейся петлёй выше копытца, а другим краем зацепившейся за обломок кривого корня, торчащего из травы. Софья хотела позвать ребят, но, оглянувшись на Алека, решила сама освободить несчастное животное. Ведь цыганские парни увидели бы в олене скорее лёгкую добычу, чем несчастное живое существо, которому нужно помочь. Мальчишка смотрел на Софью с мольбой и надеждой."},{"kind":"paragraph","text":"Выбившись из сил, оленёнок перестал дёргаться. Когда она приблизилась, упал и, видимо, смирился с судьбой. Софья, опустившись на колени, крепко ухватила его за ногу. Он задышал, высунув язык, как собака, но не шевельнулся. Ниже впившейся в кожу прочной сети, над самым копытцем, нога распухла и была горячей. Шепча тихонько молитву лошадиным покровителям, святым Фролу и Лавру, Софья ­кое-как подцепила верёвочку"},{"kind":"paragraph","text":"кончиком ножа. Непросто было разрезать её, не повредив кожу, но всё же, с большим трудом и осторожностью, Софья сумела сделать это."},{"kind":"paragraph","text":"Когда она поднялась, олень всё ещё неподвижно лежал на траве. Алек восторженно закричал, зверь вскочил и большими прыжками унёсся сквозь заросли. Обрывок сети остался в руке Софьи. Мальчик взял его, рассмотрел и спрятал за пазуху."},{"kind":"paragraph","text":"Возвращаясь в табор, Софья расспрашивала парнишку, откуда он узнал об олене: ведь далеко от костров табора он один не отходил никогда. Алек отвечал:"},{"kind":"paragraph","text":"— Он звал меня."},{"kind":"paragraph","text":"У палаток встревоженная мать начала спрашивать, куда ходили. Но Софья поняла, что Алек не хочет рассказывать о происшествии. Наверняка им стали бы пенять, что вкусное мясо не попало в котёл. Она сказала, что были на берегу, собирали пёстрые камешки для гадания. Алек смотрел на неё с благодарностью. Он сжёг в костре обрывок сети и тщательно разворошил пепел."},{"kind":"paragraph","text":"В другой раз мальчишка стал проситься со старшим братом в лес, проверять силки. Тот не хотел брать — Алек ходил плохо и медленно, — но Софья уговорила, да и Лога вступился: пусть погуляет братишка! Что он всё время у костра, да у костра! Надо и ему больные ножки размять. Анфим согласился, только когда Лога сказал, что с ними пойдёт. Старший быстро ушёл вперёд, а Лога с братишкой шли медленнее, и Алек всё время тянул в сторону."},{"kind":"paragraph","text":"— Куда ты, куда? — спрашивал Дьячок, а парнишка показывал рукой вглубь леса."},{"kind":"paragraph","text":"— Туда, туда!"},{"kind":"paragraph","text":"На полянке у старой берёзы под корнями в силке трепыхалась ушастая сова. Алек сам освободил её, упав рядом с ней на колени. Однако она и не думала улетать. Набожный и милосердный, старший брат с умилением смотрел, как младший осторожно расправляет птице перья и бережно складывает крылья."},{"kind":"paragraph","text":"— Ты отпусти её! — попросил Лога."},{"kind":"paragraph","text":"Алек ответил:"},{"kind":"paragraph","text":"— Я её не держу. Она не может лететь."},{"kind":"paragraph","text":"— Повредилась?"},{"kind":"paragraph","text":"— Нет. Она пить очень хочет. Вон там лужица, видишь? Напоить её надо. Она давно здесь. Плохо ей."},{"kind":"paragraph","text":"Лога намочил в прозрачной лесной лужице конец своего кушака и выжал немного водицы в ловко раскрытый Алеком клюв. После второй порции совушка стала встряхиваться и осторожно распускать крылья над ладонями мальчика, но улетать не торопилась."},{"kind":"paragraph","text":"В лесу послышался посвист Анфима, зовущего братьев. Лога отозвался звонким переливом. Алек оглянулся на него тревожно:"},{"kind":"paragraph","text":"— Сову же не едят?"},{"kind":"paragraph","text":"— Не едят. Она мышей ловит, её есть противно. Только уж если совсем нечего."},{"kind":"paragraph","text":"Мальчик успокоенно заулыбался."},{"kind":"paragraph","text":"Анфим подошёл почти неслышно, но сова сразу повернула голову в его сторону, защёлкала клювом и раскинула пёстрые"},{"kind":"paragraph","text":"крылья. Алек склонился над ней и прикрыл её рукой, оберегая от охотника. Анфим показал свою добычу: четырёх куропаток и рябчика, притороченных к поясу. А о сове сказал:"},{"kind":"paragraph","text":"— Добыча ваша нестоящая. Разве собакам отдать."},{"kind":"paragraph","text":"Алек с трудом встал на ноги и поднял сову над головой:"},{"kind":"paragraph","text":"— Лети, совушка, подружка моя! Ещё увидимся!"},{"kind":"paragraph","text":"Птица несколько раз взмахнула крыльями, тяжело оторвалась от рук своего благодетеля. Сначала полетела, снижаясь, но потом в несколько сильных взмахов поднялась и исчезла за деревьями. Анфим оглянулся на братьев:"},{"kind":"paragraph","text":"— Ну, вот как с вами на охоту идти? В игрушки играете… Ладно, этот, малой ещё, но ­ты-то, Лога!"},{"kind":"paragraph","text":"— На что тебе сова? — спросил Дьячок. — Пусть летает, мышей меньше будет. Давеча вон ­просвирки-то погрызли…"},{"kind":"paragraph","text":"— Вот ­то-то, что с совы вашей толку нет, — отвечал старший брат."},{"kind":"paragraph","text":"Он взял Алека подмышки, поднял на валежину и подставил ему спину:"},{"kind":"paragraph","text":"— Полезай, брат! А то с тобой до ночи не дойдём к табору. Э, да в тебе весу, как в той сове!"},{"kind":"paragraph","text":"Софья с Терезкой и Патринкой встретили братьев на опушке. Девушки копали и складывали в мешок сладкие корешки медовой огнецветки. За спиной Терезки в тёплой шалюшке дремал ребёнок."},{"kind":"paragraph","text":"— А у меня вот тоже дитёнок за спиной! — весело закричал Анфим."},{"kind":"paragraph","text":"Смеясь и перешучиваясь, весёлая компания отправилась к табору."},{"kind":"paragraph","text":"Только когда девушки принялись щипать и потрошить охотничью добычу, погрустневший Алек сказал так, что слышала только Софья:"},{"kind":"paragraph","text":"— Я их есть не буду… Они живые были."},{"kind":"paragraph","text":"Софья обняла его и зашептала ему на ушко:"},{"kind":"paragraph","text":"— Миленький мой! Ты ведь знаешь: вокруг нас всё так! Если бы рябчик в силок не попался, его бы ястреб поймал. Волк овечку ест, лисица мышку ловит. По-другому они не могут! Господь их такими создал! И нас Господь создал так. Дороги наши дальние, на одной траве не проживёшь! А тебе и подавно кушать надо: хворый ты, ножки худые!"},{"kind":"paragraph","text":"Алек со слезами побрёл к брату:"},{"kind":"paragraph","text":"— Лога, зачем Господь велел нам мясо кушать? Я не хочу! Я птиц и зверей жалею!"},{"kind":"paragraph","text":"Лога, помолчав, серьёзно ответил:"},{"kind":"paragraph","text":"— На Петровский пост я тоже мяса не ел… Да и не было у нас, помнишь? А сейчас поста нет, можно… Пока здесь стоим, на хлебушке, на корешках да на травах продержимся… А пойдём — тяжело будет."},{"kind":"paragraph","text":"Но с той поры Алек не ел ни похлёбку из птицы, ни мясо, как его ни уговаривали. Иногда мог покушать немного рыбы, если ­кому-то удавалось её поймать в быстрой речке. Софья специально чистила для него печённые в костре корешки огнецвет-"},{"kind":"paragraph","text":"ки, размышляя над его странностями и при этом любя его всей душой."},{"kind":"paragraph","text":"— Вот братовья у меня! — посмеивался Анфим. — Дьячок да монашек!"},{"kind":"paragraph","text":"В ночь перед смертью отца Алек не спал, сидел у костра, не сводя глаз с раскалённых углей и бормоча ­что-то себе под нос. Молиться, как Лога, он не умел, но в его бормотании слышались просьбы к ­кому-то неведомому, с кем он будто бы был знаком."},{"kind":"paragraph","text":"К утру, за несколько минут до того, как, будя табор, закричала, заголосила в палатке мать, он встал и, закрыв лицо руками с тонкими, худыми пальцами, тихонько заплакал."},{"kind":"paragraph","text":"Отца Лога отпевал как умел, как помнил виденное за небольшой срок прожитой жизни."},{"kind":"paragraph","text":"Цыгане слушали серьёзно, подпевали, крестились, иногда невпопад, поправляли неумелое троеперстие детям."},{"kind":"paragraph","text":"У женщин по щекам катились слёзы: хороший человек был Артюх, пожил не шибко много, а добра людям много сделал… Софья обнимала всхлипывающего Алека. А когда все были готовы в путь и братья усадили его на задок телеги, он попросил:"},{"kind":"paragraph","text":"— Ты, Софьюшка, за моей кибиткой иди. Я буду тебе батюшкину душеньку на небе казать. Я её вижу. А мама не видит."},{"kind":"paragraph","text":"Могучий Русский Динозавр"},{"kind":"paragraph","text":"Василий Вялый, Дарина Стрельченко, Артём Северский,"},{"kind":"paragraph","text":"Александр Олексюк, Олег Золотарь, Оганес Мартиросян, Александр Шилякин, Николай Старообрядцев, Ольга Иванова"},{"kind":"paragraph","text":"Редакторы: Анастасия Ворожейкина, Алёна Купчинская,"},{"kind":"paragraph","text":"Полина Шарафутдинова"},{"kind":"paragraph","text":"Корректор: Денис Дронов"},{"kind":"paragraph","text":"Харина, Елена Солнцева, Екатерина Яковлева, Анна Мухина"},{"kind":"paragraph","text":"Дизайнеры: Даниил Румянцев, Катерина Видяскина"},{"kind":"paragraph","text":"Верстальщик: Александра Яшаркина"},{"kind":"paragraph","text":"без разрешения правообладателя запрещено."},{"kind":"paragraph","text":"Степан Фёдорович Домрачёв, чудной пятидесятилетний слесарь, приезжает в село забрать вещи умершего дяди. Там у него угоняют «Газель», поэтому уехать из села он не может. Он начинает переворачивать жизнь местных жителей с ног на голову, постепенно лишаясь рассудка."},{"kind":"paragraph","text":"Горстка людей, обладающих тайным знанием и доступом к опасным и разрушительным технологиям, противопоставляет себя человечеству и творит собственную историю, не считаясь с последствиями."},{"kind":"paragraph","text":"Череда на первый взгляд не связанных друг с другом событий, свидетельств и артефактов раскрывает истинную суть тоталитарного мирового заговора."},{"kind":"paragraph","text":"В центре повествования — масштабная и трагическая борьба сверхчеловеков, жаждущих подчинить своей воле не только время, но и самое естество Бытия."},{"kind":"paragraph","text":"Роман погружает читателя в мир титанических вызовов и зашкаливающих эмоций, рисует картины реальности, в которой морально ничтожная личность в стремлении освободиться от условностей вырастает до размеров макрокосма, вступая в спор с бесконечностью."},{"kind":"paragraph","text":"Способен ли гордый разум победить законы Вселенной — ответ вы найдёте на страницах книги."},{"kind":"paragraph","text":"Не столь давняя история оживает, и современность играет новыми гранями: Ленин встречается с омоновцами, воспоминания провинциального детства обрываются вместе с жизнью старого пса, любовь рождается на стройплощадке и умирает в студенческой тетради, а преступлением может оказаться не только причёска, но и трезвость. Это рассказы о хрупкости и ценности человеческой жизни, которую люди готовы разменять на пачку купюр или корм для псов. Сердцевина книги — искренняя, напряжённая проза, обострённая чувствительность к тому, мимо чего многие пройдут, не задумываясь."},{"kind":"paragraph","text":"Ветеран войны за возвращение южных территорий Егор Клевин не находит себя в мирной жизни. Он соглашается сопровождать свою возлюбленную на студенческом митинге. Однако мероприятие оборачивается политической провокацией, и Егор попадает на объект «Рай» — новейшее отечественное изобретение на стыке системы правосудия и IT."}]'::jsonb,
  '2021-12-30T12:00:00.000Z'
)
